#include <bits/stdc++.h>
using namespace std;

#define dump(x)  cout << #x << " = " << (x) << endl;

typedef long long ll;
typedef pair<int, int> ii;
const int mod = 1000003;
const ll INF = 1e18;
const int inf = 1e9;

const int MAX = mod;
ll fac[MAX], finv[MAX], inv[MAX];

void cominit()
{
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (ll i=2; i<MAX; i++) {
    fac[i] = fac[i-1] * i % mod;
    inv[i] = mod - inv[mod%i] * (mod/i) % mod;
    finv[i] = finv[i-1] * inv[i] % mod;
  }
}

ll com(ll n, ll k)
{
  if (n<k) return 0;
  if (n<0 || k<0) return 0;
  return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}

ll modpow(ll a, ll n)
{
  ll res=1;
  while (n>0) {
    if (n&1) res = res*a % mod;
    a = a*a % mod;
    n >>= 1;
  }
  return res;
}

void solve()
{
  cominit();
  int q; cin>>q;
  vector<ll> ans(q);
  for (int i=0; i<q; i++) {
    ll x, d, n;
    cin >> x >> d >> n;

    if (d==0) {
      ans[i] = modpow(x,n);
      continue;
    }

    ll p = x * inv[d] % mod;
    if (p+n-1 >= mod) {
      ans[i] = 0;
      continue;
    }

    ll tmp = modpow(d,n);
    tmp = tmp * fac[p+n-1] % mod;
    if (p>0) tmp = tmp * finv[p-1] % mod;
    ans[i] = tmp;
  }
  for (int i=0; i<q; i++) {
    cout << ans[i] << endl;
  }
}

int main()
{
  solve();
  return 0;
}

