typedef tree<int, null_type, less<int>, rb_tree_tag, tree_order_statistics_node_update> ordered_set;
const int N = 2000010;
ll t[N << 1];
int sze;

void init(int n){
	sze = n;
	cu(i,0,n)t[i + n] = i + 1;
	cd(i,n,1){
		t[i] = t[i<<1] * t[i<<1|1] % MOD;	
	}
}

ll query(int l,int r){
	ll res = 1;	
	for(l+=sze,r+=sze;l < r;l>>=1,r>>=1){
		if(l&1)res = res * t[l++] % MOD;
		if(r&1)res = res * t[--r] % MOD;
	}
	return res;
}

ll modpow(ll x, ll p){
	if(p == 0)return 1;
	ll y = 1;
	while(p > 1){
		if(p&1)y = y * x % MOD;
		x = x * x % MOD;
		p>>=1;
	}
	return x * y % MOD;
}

