			cout << 0 << '\n';
		}
		else{
			ll ans = modpow(d,n);
			ll start = x * modpow(d,MOD-2) % MOD;
			ans *= query(start-1,start+n-1);
			ans %= MOD;
			cout << ans << '\n';
		}
	}
}

