const int N = 2000010, mod = 1e6 + 3;

inline int ksm(int a, int b)
{
    int res = 1;
    while(b)
    {
        if(b & 1)
            res = (ll) res * a % mod;
        a = (ll) a * a % mod, b >>= 1;
    }
    return res;
}

int fac[N], ifac[N], x, n, d, Q;

int main()
{
    fac[0] = 1;
    for (rg i = 1; i < mod; i++)
        fac[i] = (ll) fac[i - 1] * i % mod;
