vector<ll> kaijo;
ll modpow(ll x, ll n) {
    if(n==0){
        return 1;
    }else if(n%2==0){
        ll h = modpow(x,n/2);
        return h * h % MOD;
    } else {
        return x * modpow(x,n-1) % MOD;
    }
}

int main(void){
	int q;
	cin>>q;
	int x,d,n;
	vector<int> X,D,N;
	rep(i,q){
		cin>>x>>d>>n;
		X.push_back(x);
		D.push_back(d);
		N.push_back(n);
	}

	kaijo.push_back(1);
	reps(i,MOD){
		kaijo.push_back((kaijo[i-1] * i)%MOD);
	}

	rep(i,q){
		x = X[i]; d = D[i]; n = N[i];
		if(d == 0){
			cout<< x * n << endl;
		}else{
			//  (x/d) * (x/d + 1) * ... * (x/d + n - 1) の　%MOD
			//= (x/d)の%MOD * (x/d + 1)の%MOD * ... * (x/d + n - 1)の%MOD
			//= (x/d)の%MOD * ((x/d)の%MOD + 1)%MOD * ... * ((x/d)の%MOD + n - 1)%MOD
			ll first = (x * modpow(d, MOD-2))%MOD;
			ll last = (x * modpow(d, MOD-2) + n - 1)%MOD;

			if(first > last || first == 0){
				//first > last : 1 * 2 * ... * last * first * first+1 * ... * MOD-1 * MOD(=0)
				cout << 0 << endl;	
			}else{
				cout << kaijo[last] * modpow(kaijo[first - 1], MOD-2) %MOD * modpow(d,n) %MOD << endl;
			}
		}
	}
	return 0;
}

#ifndef CLASS_MODINT
#define CLASS_MODINT

#include <cstdint>

template <std::uint32_t mod>
class modint {
private:
	std::uint32_t n;
public:
	modint() : n(0) {};
	modint(std::int64_t n_) : n((n_ >= 0 ? n_ : mod - (-n_) % mod) % mod) {};
	static constexpr std::uint32_t get_mod() { return mod; }
	std::uint32_t get() const { return n; }
	bool operator==(const modint& m) const { return n == m.n; }
	bool operator!=(const modint& m) const { return n != m.n; }
	modint& operator+=(const modint& m) { n += m.n; n = (n < mod ? n : n - mod); return *this; }
	modint& operator-=(const modint& m) { n += mod - m.n; n = (n < mod ? n : n - mod); return *this; }
	modint& operator*=(const modint& m) { n = std::uint64_t(n) * m.n % mod; return *this; }
	modint operator+(const modint& m) const { return modint(*this) += m; }
	modint operator-(const modint& m) const { return modint(*this) -= m; }
	modint operator*(const modint& m) const { return modint(*this) *= m; }
	modint inv() const { return (*this).pow(mod - 2); }
	modint pow(std::uint64_t b) const {
		modint ans = 1, m = modint(*this);
		while (b) {
			if (b & 1) ans *= m;
			m *= m;
			b >>= 1;
		}
		return ans;
	}
};

#endif // CLASS_MODINT

