template<ll mod>
class Fp {
public:
	ll val;

private:
	inline void calc_mod(ll& v) {
		if (v >= mod)v -= mod;
	}
public:
	Fp(){}
	Fp(ll v) :val(v%mod) {
		if (val < 0)val += mod;
	}

	Fp operator+=(const Fp &in) {
		val += in.val;
		calc_mod(val);
		return *this;
	}

	Fp operator+(const Fp &in) const{
		return Fp(*this) += in;
	}

	Fp &operator-=(const Fp &in) {
		val -= in.val;
		calc_mod(val);
		if (val < 0)val += mod;
		return *this;
	}

	Fp operator-(const Fp &in) const{
		return Fp(*this) -= in;
	}

	Fp& operator*=(const Fp& in) {
		val = val * in.val % mod;
		return *this;
	}

	Fp operator*(const Fp &in) const{
		return (Fp(*this) *= in);
	}

	Fp& operator/=(const Fp& in) {
		*this *= modpow(in, mod - 2);
		return *this;
	}

	Fp operator/(const Fp& in) const{
		return (*this)*modpow(in, mod - 2);
	}

	bool operator==(const Fp&in)const {
		return val == in.val;
	}

	bool operator!=(const Fp&in)const {
		return val != in.val;
	}

	friend Fp modpow(const Fp& in, ll n){
		if (n == 0)return 1;
		if (n & 1) {
			return in*modpow(in*in, n / 2);
		}
		else {
			return modpow(in*in, n / 2);
		}
	}
};
using modll = Fp<mod>;

class Factorial {
public:
	vector<modll> fact, finv;
	Factorial(ll n) :fact(n, modll(1)), finv(n, modll(1)) {
		for (int i = 2; i < n; i++) {
			modll tmp(i);
			fact[i] = fact[i - 1] * tmp;
			finv[i] = finv[i-1] / tmp;
		}
	}

	modll com(const ll& n, const ll& k) {
		if (n < k || n < 0 || k < 0)return modll(0);
		return fact[n] * finv[k] * finv[n - k];
	}
};


int main() {
	cin >> Q;
	Factorial f(mod);
	for (int _ = 0; _ < Q; _++) {
		ll _x, _d, n;
		cin >> _x >> _d >> n;
		modll x(_x), d(_d);
		x /= d;
		if (d.val == 0) {
			cout << modpow(x, n).val << endl;
			return 0;
		}

		if (x.val <= mod && mod <= x.val + n - 1) {
			cout << 0 << endl;
		}
		else if (x.val == 0) {
			cout << 0 << endl;
		}
		else {
			cout << (modpow(d, n)*f.fact[x.val+n-1]*f.finv[x.val-1]).val << endl;
		}
	}
}

#include <bits/stdc++.h>
using namespace std;
namespace mint {
  constexpr int md = 1'000'003;
  inline void add (int &a, int b) {
    a += b; if (a >= md) a -= md;
  }
  inline void sub (int &a, int b) {
    a -= b; if (a < 0) a += md;
  }
  inline int sum (int a, int b) {
    add(a, b); return a;
  }
  inline int dif (int a, int b) {
    sub(a, b); return a;
  }
  template<class... A>
  inline int prod (A... args) {
    long long ret = 1;
    for (int a : initializer_list<int>{args...}) {
      ret *= a;
    }
    return (int)(ret % md);
  }
  inline void mul (int &a, int b) {
    a = prod(a, b);
  }
  inline int inv (int a) {
    a %= md;
    if(a < 0) a += md;
    int b = md, u = 0, v = 1;
    while (a) {
      int t = b / a;
      b -= a * t; swap(a, b);
      u -= v * t; swap(u, v);
    }
    assert(b == 1);
    if(u < 0) u += md;
    return u;
  }
  inline int quat (int a, int b) {
    return prod(a, inv(b));
  }
  inline void div (int& a, int b) {
    a = quat(a, b);
  }
  inline int pow (int a, long long b) {
    int res = 1;
    for (; b; b >>= 1) {
      if (b & 1) mul(res, a);
      mul(a, a);
    }
    return res;
  }
}
int main() {
  cin.tie(0); cin.sync_with_stdio(false);
  const int pmx = 32;
  vector<vector<int>> dp(pmx, vector<int>(mint::md, 1));
  vector<int> iv(mint::md);
  for (int i = 1; i < mint::md; i++) {
    iv[i] = mint::inv(i);
  }
  for (int i = 1, p = 1; i < pmx; i++) {
    for (int y = 1; y < mint::md; y++) {
      dp[i][y] = ((1 << i) > mint::dif(0, iv[y])) ?
        0 :
        mint::prod(
          dp[i - 1][y],
          mint::pow(mint::sum(1, mint::prod(y, p)), p),
          dp[i - 1][mint::prod(y, iv[mint::sum(1, mint::prod(y, p))])]
        );
    }
    p *= 2;
  }
  auto dal = [&] (int x, int d, int i) -> int{
    return mint::prod(mint::pow(x, (1 << i)), dp[i][mint::prod(d, iv[x])]);
  };
  auto cal = [&] (int x, int d, int n) -> int {
    int ret = 1;
    for (int i = 0; i < pmx; i++) {
      if (n >> i & 1) {
        mint::mul(ret, dal(x, d, i));
        mint::add(x, mint::prod(d, 1 << i));
      }
    }
    return ret;
  };
  int q;
  cin >> q;
  while (q--) {
    int x, d, n;
    cin >> x >> d >> n;
    int ret;
    if (n == 0) ret = 1;
    else if (x == 0) ret = 0;
    else ret = cal(x, d, n);
    cout << ret << endl;
  }
  return 0;
}

