ll pow(ll a, ll b) {
	ll ans = 1;
	while (b > 0) {
		if (b % 2 == 1) {
			ans *= a;
			ans %= MOD;
		}
		b /= 2;
		a *= a;
		a %= MOD;
	}
	return ans;
}

ll frac(ll n) {
	static VL memo(MOD + 1);
	static ll now = 2;
	if (n >= MOD) { return 0; }
	memo[1] = 1;
	if (n < now) { return memo[n]; }

	FOR(i, now, n + 1) {
		memo[i] = (memo[i - 1] * i) % MOD;
	}
	now = n + 1;
	return memo[n];
}

