const int MOD=1000003;
const int MAXQ=100000;
int pw(int x,int n) { int ret=1; while(true) { if(n&1) ret=(ll)ret*x%MOD; if((n>>=1)==0) return ret; x=(ll)x*x%MOD; } }

int nq;
int qx[MAXQ],qd[MAXQ],qn[MAXQ],qans[MAXQ];

int inv[MOD];
int fac[MOD];
int ifac[MOD];


void solve() {
	inv[1]=1; FORE(i,2,MOD-1) inv[i]=(ll)(MOD-MOD/i)*inv[MOD%i]%MOD;
	fac[0]=1; FORE(i,1,MOD-1) fac[i]=(ll)fac[i-1]*i%MOD;
	ifac[0]=1; FORE(i,1,MOD-1) ifac[i]=(ll)ifac[i-1]*inv[i]%MOD;

	REP(i,nq) {
		int x=qx[i],d=qd[i],n=qn[i];
		if(d==0) { qans[i]=pw(x,n); continue; }
		int a=(ll)inv[d]*x%MOD;
		int b=a+n-1;
		if(b>=MOD) { qans[i]=0; continue; }
		if(a==0) { qans[i]=0; continue; }
		//printf("a=%d b=%d\n",a,b);
		qans[i]=(ll)fac[b]*ifac[a-1]%MOD*pw(d,b-a+1)%MOD;
	}

}

void run() {
	scanf("%d",&nq);
	REP(i,nq) scanf("%d%d%d",&qx[i],&qd[i],&qn[i]);
	solve();
	REP(i,nq) printf("%d\n",qans[i]);
}

int main() {
	run();
	return 0;
}

