struct mint {
    ll x;
    mint(ll x = 0) : x(x % MOD) {}
    mint& operator += (const mint a) {
        if ( (x += a.x) >= MOD) { x -= MOD; }
        return *this;
    }
    mint& operator -= (const mint a) {
        if ( (x += MOD - a.x) >= MOD) { x -= MOD; }
        return *this;
    }
    mint& operator *= (const mint a) {
        (x *= a.x) %= MOD;
        return *this;
    }
    mint operator + (const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator - (const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator * (const mint a) const {
        mint res(*this);
        return res *= a;
    }
};

// x の y 乗を求める O(log MOD)
ll modpow(ll x, ll y) {
    if (y == 0) return 1;
    ll res = modpow(x, y / 2);
    return res * res % MOD * (y & 1 ? x : 1) % MOD;
}
// x の逆元を求める O(logMOD)
ll modinv(ll x) { return modpow(x, MOD - 2); }
mint modinv(mint x) { return modpow(x.x, MOD - 2); }

// n の m 上昇階乗べきを求める O(log MOD)
// fact には [0, mod] の階乗を事前計算したものを渡す
// 例) 4 の 3 上昇階乗べき -> 4 * (4+1) * (4+2)
ll raising_fact(const vector<mint>& fact, ll n, ll m) {
    // 剰余の関係上 MOD! 以上の階乗は 0 になる
    if(n + m - 1 >= MOD) { return 0; }

    mint ret = fact[ n + m - 1 ];
    ret *= modinv(fact[ n - 1 ]);
    return ret.x;
}

// 等差数列の積を求める O(log MOD)
// 初項 x, 公差 d, 第 n 項までを求める
// MOD は 10^6 程度までが限界
// fact には [0, mod] の階乗を事前計算したものを渡す
// 例) x = 3, d = 1, n = 4 -> 3 * 4 * 5 * 6 = 360
ll AriProMul(const vector<mint>& fact, ll x, ll d, ll n) {
    mint x_d = mint(x) * mint(modinv(d));
    // d が 0 のときは例外 -> x^n になる
    if(d == 0) { return modpow(x, n); }
    return (modpow(d, n) * raising_fact(fact, x_d.x, n)) % MOD;
}

