long long inv(long long a) {
    long long b = p, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= p;
    if (u < 0) u += p;
    return u;
}
long long exponen(long long a,long long b){
    if (b==0){
        return 1;
    }
    else if(b%2==0){
        return exponen((a*a)%p,b/2);
    }
    else{
        return (a*exponen((a*a)%p,b/2))%p;
    }
}
