    if (d==0){
        return exponen(x,n);
    }
    long long check=((p-d)*inv(x))%p;
    if (0<=check && check<n){
        return 0;
    }
    long long a=(x*inv(d))%p;
    return (exponen(d,n)*(fact(n-1+a)*inv(fact(a-1)))%p)%p;
}
