using namespace std;

using ll = long long;

const ll MOD = 1000003;

ll modpow(ll x, ll n, ll mod = MOD) {
    if (x == 0) return 0;
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int q;
