  ll ans=pow(d,n%(mod-1));
  ll X=(x*gyaku(d))%mod;
  if(mod-X<=n) return 0;
  ans*=frac[(X+n-1)%mod];
  ans%=mod;
  ans*=gfrac[(X+mod-1)%mod];
  ans%=mod;
  return ans;
}
