#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e6 + 3;

int fact[MOD];

inline int mul(int x, int y) {
	return (long long)x * y % MOD;
}

int pot(int x, int y) {
	int res = 1;
	for (; y; y /= 2) {
		if (y % 2)
			res = mul(res, x);
		x = mul(x, x);
	}
	return res;
}

int divide(int x, int y) {
	return mul(x, pot(y, MOD - 2));
}

int calc(int x, int n) {
	if (x > 0 && x + n <= MOD)
		return divide(fact[x + n - 1], fact[x - 1]);
	return 0;
}

int solve(int x, int d, int n) {
	if (d)
		return mul(pot(d, n), calc(divide(x, d), n));
	return pot(x, n);
}

int main() {
	fact[0] = 1;
	for (int i = 1; i < MOD; i++)
		fact[i] = mul(fact[i - 1], i);

	int Q;
	scanf("%d", &Q);
	while (Q--) {
		int x, d, n;
		scanf("%d%d%d", &x, &d, &n);
		printf("%d\n", solve(x, d, n));
	}

	return 0;
}

