ll seki(int x, int d, int n, int mod){
  ll ans = x;
  reps(i,n-1){
    ll next = x+i*d;
    if(dp[ans][next]==0 && dp[next][ans]==0){
      int pre_ans = ans;
      ans *= next;
      ans %= mod;
      dp[pre_ans][next] = ans;
      dp[next][pre_ans] = ans;
    }else{
      ans = max(dp[ans][next],dp[next][ans]);
    }
  }
  return ans;
}


