ll modpow(ll x, ll n){
    ll ret = 1LL;
    ll cur = x;
    while(n > 0){
        if(n & 1){
            ret = MUL(ret, cur, mod);
        }
        cur = MUL(cur, cur, mod);
        n /= 2;
    }
    return ret;
}

