int mul(int x,int y) {
  return (ll)x*y%mod;
}
int dp[mod][M];
int mypow(int x,int c) {
  int ret = 1;
  while(c>0) {
    if(c&1) {
      ret = mul(ret,x);
    }
    x = mul(x,x);
    c/=2;
  }
  return ret;
}

void solve() {
  for(int i=1;i<=mod-2;++i) {
    dp[i][0] = i;
  }
  for(int j=1;j<M;++j) {
    for(int i=1;i<=mod-2;++i) {
      dp[i][j] = mul(dp[i][j-1], dp[ (i+ (1LL<<(j-1) )  )%mod][j-1]);
    }
  }
  int Q;scanf("%d",&Q);
  while(Q--) {
    int x,d,n;scanf("%d %d %d ", &x,&d,&n);
    if(d==0) {
      printf("%d\n", mypow(x,n));
    }
    else {
      int cur = x,ret = 1;
      cur = mul(cur, mypow(d,mod-2));
      int u = mypow(d,n);
      for(int i=M-1;i>=0;--i) {
        if(n&(1LL<<i)) {
          ret = mul(ret, dp[cur][i]);
          cur = (cur + (1LL<<i))%mod;
        }
      }
      ret = mul(ret,u);
      printf("%d\n", ret);
    }
  }
}

