int const md = 1000003;
int fc[md];

int pw(int a, int p){
	int an = 1;
	while (p){
		if (p & 1)an = (ll)an * a % md;
		a = (ll)a * a % md;
		p >>= 1;
	}
	return an;
}

int go(int d, int n) { return (ll)fc[n] * pw(d, n) % md; }

int solve(){
	int x, d, n;
	scanf("%d%d%d", &x, &d, &n);
	if (x == 0 || n >= md)return 0;
	if (d == 0)return pw(x, n);
	int ed = x + (ll)d * (n - 1);
	if (ed == 0)return 0;
	int i = (ll)ed * pw(d, md - 2) % md;
	if (i < n)return 0;
	int an = (ll)go(d, i) * pw(go(d, i - n), md - 2) % md;
	return an;
}

int main(){
