    ans%=Mod;
    if((x*dm+n-1)%Mod<n-1){
      ans*=table[Mod];
      ans%=Mod;

      ans*=retable[Mod-((n-1)-((x*dm+n-1)%Mod))];
      ans%=Mod;
    }

    ans*=retable[(x*dm-1+Mod)%Mod];
    ans%=Mod;

    ans*=modpow(d,n,Mod);
    ans%=Mod;
    cout<<ans<<endl;
  }
}

