#include <bits/stdc++.h>
using namespace std;
using LL = long long;
#define repex(i, a, b, c) for(int i = a; i < b; i += c)
#define repx(i, a, b) repex(i, a, b, 1)
#define rep(i, n) repx(i, 0, n)
#define repr(i, a, b) for(int i = a; i >= b; i--)
const LL MOD = 1e6 + 3;
const int LIMIT = 1010101;
LL FAC[LIMIT], INV[LIMIT];

// Fermat's little theorem から, 大きな冪乗の計算を行う.
// @param a: べき乗したい正整数.
// @param b: 指数.
// @return:  べき乗した計算結果(mod版).
LL mPow(LL a, LL b){
    LL t = 1;
    while(b){
        if(b & 1) t = (t * a) % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return t % MOD;
}

// 組み合わせ(nCk)計算用(mod版).
// ※配列FAC, INV は, 事前に計算済のものを使う.
// @param n: 対象となる要素の個数.
// @param k: 選択する要素の個数.
// @return: 組み合わせ(nCk)の計算結果(mod版).
LL combination(LL n, LL k){
    if(n < 0 || k < 0 || k > n) return 0LL;
    if(n == k || k == 0LL) return 1LL;
    LL ret = FAC[n] * INV[k] % MOD * INV[n - k] % MOD;
    return ret;
}

int main(){

    // 1. 入力情報.
    int Q;
    scanf("%d", &Q);
    FAC[0] = 1;
    repx(i, 1, LIMIT) FAC[i] = (LL)i * FAC[i - 1] % MOD;
    rep(i, LIMIT)     INV[i] = mPow(FAC[i], MOD - 2);

    // 2. クエリ回答(解説通り).
    rep(i, Q){
        LL x, d, n;
        scanf("%lld %lld %lld", &x, &d, &n);

        // 2-1. d が 0 の 場合.
        if(d == 0){
            LL ans = mPow(x, n);
            printf("%lld\n", ans);
        }

        // 2-2. d が 0 でない 場合.
        if(d != 0){
            LL xd = x * mPow(d, MOD - 2) % MOD; // (x / d) を 計算.
            LL q1 = xd / MOD;
            LL q2 = (xd + n - 1) / MOD;
            // 1000003 の倍数 が 見つかったか否かで 分岐.
            if(q2 > q1){
                puts("0");
            }else{
                // xd が 0 か 否かで 分岐.
                if(xd == 0){
                    puts("0");
                }else{
                    LL r1 = (xd + MOD - 1) % MOD;
                    LL r2 = (xd + MOD + n - 1) % MOD;
                    LL ans = FAC[r2] * INV[r1] % MOD * mPow(d, n) % MOD;
                    printf("%lld\n", ans);
                }
            }
        }
    }
    return 0;

}

