template<int MOD>
class mod_int {
	unsigned x;
public:
	mod_int() : x(0) { }
	mod_int(int sig) { int sigt = sig % MOD; if (sigt < 0) sigt += MOD; x = sigt; }
	mod_int(long long sig) { int sigt = sig % MOD; if (sigt < 0) sigt += MOD; x = sigt; }
	int get() const { return (int)x; }

	mod_int &operator+=(mod_int that) { if ((x += that.x) >= MOD) x -= MOD; return *this; }
	mod_int &operator-=(mod_int that) { if ((x += MOD - that.x) >= MOD) x -= MOD; return *this; }
	mod_int &operator*=(mod_int that) { x = (unsigned long long)x * that.x % MOD; return *this; }
	mod_int &operator/=(mod_int that) { return *this *= that.inverse(); }

	mod_int operator+(mod_int that) const { return mod_int(*this) += that; }
	mod_int operator-(mod_int that) const { return mod_int(*this) -= that; }
	mod_int operator*(mod_int that) const { return mod_int(*this) *= that; }
	mod_int operator/(mod_int that) const { return mod_int(*this) /= that; }

	bool operator==(const mod_int& that) const { return x == that.x; }

	mod_int inverse() const {
		long long a = x, b = MOD, u = 1, v = 0;
		while (b) {
			long long t = a / b;
			a -= t * b; swap(a, b);
			u -= t * v; swap(u, v);
		}
		return mod_int(u);
	}
};

template<int MOD>
istream& operator >> (istream& is, mod_int<MOD>& val) {
	long long x;
	is >> x; val = x;
	return is;
}

template<int MOD>
ostream& operator << (ostream& os, const mod_int<MOD>& val) {
	os << val.get();
	return os;
}

const int mod = 1e6 + 3;
using mint = mod_int<mod>;

mint fac[mod + 1];

mint power(mint x, int n) {
	mint res = 1;
	while (n) {
		if (n & 1) res *= x;
		n >>= 1;
		x *= x;
	}
	return res;
}

int main()
{
	fac[0] = 1;
	for (int i = 0; i < mod; i++) {
		fac[i + 1] = fac[i] * (i + 1);
	}
	int Q;
	cin >> Q;
	while (Q--) {
		mint x, d;
		int n;
		cin >> x >> d >> n;
		assert(1 <= n && n <= 1e9);
		if (x.get() == 0) {
			puts("0");
			continue;
		}
		if (d == 0) {
			printf("%d\n", power(x, n).get());
		}
		if (((mint(0) - x) / d).get() < n) {
			puts("0");
			continue;
		}
		int off = (x / d).get() - 1;
		assert(0 <= off && off < mod && off + n < mod);
		mint v = fac[off + n] / fac[off];
		printf("%d\n", (v * power(d, n)).get());
	}
	return 0;
}

