//very very useful functions
//n**k
Modulo pow(Modulo n, long long k)
{
    Modulo tmp = n;
    tmp = tmp.pow(k);
    return tmp;
}

//n!
Modulo fact(long long n)
{
    Modulo tmp = 1;
    for(int i=2; i<=n; i++)
        tmp *= i;
    return tmp;
}

Modulo mul(int x, int d, int n)
{
    if(n == 1){
        Modulo r = x;
        return r;
    }
    if(n % 2 == 0){
        return mul(x, d, n/2) * mul(x + d*n/2, d, n/2);
    }
    if(n % 2 != 0){
        Modulo r = x + d * n / 2;
        return mul(x, d, n/2) * mul(x + d*(n+1)/2, d, n/2) * r;
    }
}

