	fact_inv[MOD - 1] = modpow(fact[MOD - 1], MOD - 2);

	for (int i = MOD - 2; i >= 0; i--) {
		fact_inv[i] = fact_inv[i + 1] * (i + 1);
		fact_inv[i] %= MOD;
	}
}

void set_inv() {
	for (int i = 0; i < MOD; i++) {
		inv[i] = modpow(i, MOD - 2);
	}
}

int main() {
	set_inv();
	set_fact();
	int Q;
	cin >> Q;
	for (int q = 0; q < Q; q++) {
		ll x, d, n;
		cin >> x >> d >> n;
		//全体の式を/(d^n)すると、等差1の数列の積になる。それって階乗じゃん。
		//x/dは割り切れなくても、modの世界なので整数になるので、結局問題なし。
		//階乗とそれぞれの数字に逆元を事前に計算しておけばO(1)で取得できるので解ける
		ll tmp = (x * inv[d]) % MOD;
		if (n - 1 >= (MOD - tmp)) {
			cout << 0 << endl;
		}
		else {
			cout << (((fact[(tmp + n - 1) % MOD] * fact_inv[(tmp - 1 + MOD) % MOD]) % MOD) * modpow(d, n)) % MOD << endl;
		}
	}

	return 0;
}

