		else {
			ll inv_d = mod_pow(d, mod - 2, mod);
			ll xd = x * inv_d % mod;
			if (xd + n - 1 >= mod) ans = 0;
			else {
				ans = fact[xd + n - 1] * inv[xd - 1] % mod; 
				ans = ans * mod_pow(d, n, mod) % mod;
			}
		}
