    for (int i = 1; i < MOD; i++) {
        fact[i] = fact[i - 1] * i;
    }
    factinv[MOD - 1] = fact[MOD - 1].inv();
    for (int i = MOD - 2; i >= 0; i--) {
        factinv[i] = factinv[i + 1] * (i + 1);
    }
    assert(factinv[0] == 1);
}

mint rfact(int x, int r) {
    if (x + r >= MOD) return mint(0);
    return fact[x + r - 1] * factinv[x - 1];
}


