lint extgcd(lint a, lint b, lint &x, lint &y) {
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}
	lint d = extgcd(b, a % b, y, x);
	y -= a / b * x;
	return d;
}

lint invmod(lint a, lint m) {
    lint x, y;
    extgcd(a, m, x, y);
    return (x % m + m) % m;
}

lint powmod(lint x, lint k) {
	lint ret = 1;	
	while (k > 0) {
		if (k & 1) modMul(ret, x, MOD);
		modMul(x, x, MOD);
		k >>= 1;
	}
	return ret;
}

