	while(p){
		if(p & 1)
			res = res * x % mod;
		x = x * x % mod;
		p >>= 1;
	}
	return res;
}
ll inv(ll x){
	return binpow(x, mod - 2);
}
ll G(ll l, ll r){
	if((l - 1) / mod != r / mod)
		return 0;			
	l %= mod;
	r %= mod;
	assert(l <= r);
	if(l == 0)
		return f[r];
	return f[r] * rf[l - 1] % mod;
}
