long long int N, M, K, H, W, L, R;

long long int power(long long int x, long long int n, long long int M) {
	long long int ret = 1;
	long long int by = x;
	while (n) {
		if (n & 1) {
			ret *= by;
			ret %= M;
		}
		by *= by;
		by %= M;
		n >>= 1;
	}
	return ret;
}

long long int gcd(long long int a, long long int b) {
	while (b) {
		a %= b;
		swap(a, b);
	}
	return a;
}

long long int extended_gcd(long long int a, long long int b, long long int c, long long int d, long long int m) {
	long long int ret = 0;
	if (c == 1)return d;
	ret = extended_gcd(c, d, a%c, (b + (MOD *MOD / m)*m - ((a / c) % m)*(d%m)) % m, m);
	return ret;
}

long long int extended_gcd(long long int a, long long int b) {
	int g = gcd(a, b);
	a /= g;
	b /= g;
	long long int box = a % b;
	long long int bag = b - (a % b);
	long long int bbox = 1;
	long long int bbag = b - 1;
	return extended_gcd(box, bbox, bag, bbag, b)*g;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	int T;
	cin >> T;
	vector<long long int>by(MOD, 1);
	vector<long long int>rev(MOD, 1);
	for (int i = 2; i < MOD; i++) {
		by[i] = by[i - 1] * i;
		by[i] %= MOD;
		rev[i] = power(by[i], MOD - 2, MOD);
	}
	while (T--) {
		cin >> N >> M >> K;
		if (K >= MOD) {
			cout << 0 << endl;
			continue;
		}
		if (!M) {
			cout << power(N, K, MOD) << endl;
			continue;
		}
		if (!N) {
			cout << 0 << endl;
			continue;
		}
		long long int box = extended_gcd(M, MOD);
		box *= N;
		box %= MOD;
		long long int ed = box + K - 1;
		if (ed >= MOD) {
			cout << 0 << endl;
			continue;
		}
		long long int ans = by[ed];
		ans *= power(by[box - 1], MOD - 2, MOD);
		ans %= MOD;
		ans *= power(M, K, MOD);
		ans %= MOD;
		cout << ans << endl;
	}
}

