using namespace std;
using int64 = long long;

constexpr int DEBUG = 0;

constexpr int64 P = 1000003;

struct FiniteField {
 private:
  int64 x;
  static inline int64 Normalize(int64 x) {
    if (0 <= x && x < P) return x; x %= P; if (x < 0) x += P; return x;
  }
 public:
  FiniteField(int64 x) : x(Normalize(x)) {}
  FiniteField() : x(0) {}
  int64 Value() const { return x; }
  inline FiniteField operator+(FiniteField o) const {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) const {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) const {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) const {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

ostream& operator<<(ostream& s, const FiniteField& v) { s << v.Value(); return s; }

vector<FiniteField> MakeFactorialTable(int n) {
  vector<FiniteField> factorials(n + 1);
  factorials[0] = 1;
  for (int i = 1; i <= n; i++) {
    factorials[i] = factorials[i - 1] * i;
  }
  return factorials;
}

FiniteField Power(FiniteField x, int p) {
  if (p < 0) return FiniteField(1) / Power(x, -p);
  FiniteField value = 1;
  while (p) {
    if (p % 2) value *= x;
    x *= x;
    p /= 2;
  }
  return value;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  auto factorials = MakeFactorialTable(P - 1);

  int q_count;
  cin >> q_count;
  for (int q_id = 0; q_id < q_count; q_id++) {
    int x, d, n;
    cin >> x >> d >> n;
    if (d == 0) {
      cout << Power(FiniteField(x), n) << endl;
      continue;
    }
    if (x == 0) {
      cout << 0 << endl;
      continue;
    }

    FiniteField k = FiniteField(x) / d;
    // cout << "k: " << k << endl;
    if (k.Value() + n - 1 >= P) {
      cout << 0 << endl;
      continue;
    }

    cout << (factorials[k.Value() + n - 1] / factorials[k.Value() - 1] * Power(d, n)) << endl;
  }
}

