constexpr long long mod = 1000003;

class combination_mod{
public:
  const long long mod;
  const long long size;

  vector<long long> fact; //n!
  vector<long long> fact_inv; // (n!)^-1

  void make_fact(){
    fact[0] = 1;
    for(long long i=1; i<size; i++){
      fact[i] = fact[i-1]*i % mod;
    }
  }

  void make_fact_inv(){
    fact_inv[0] = fact_inv[1] = 1;
    for(long long i=2; i<size; i++){
      fact_inv[i] = fact_inv[mod%i] * (mod - mod/i) % mod;  // x ^ -1
    }
    for(int i=2; i<size; i++){
      fact_inv[i] = fact_inv[i-1] * fact_inv[i] % mod;  // x! ^ -1
    }
  }

  combination_mod(long long mod_, long long size_ = 2000000) : mod(mod_), size(size_+1){
    fact.resize(size);
    fact_inv.resize(size);
    make_fact();
    make_fact_inv();
  }

  //nCk mod p O(1)
  long long operator()(long long n, long long k){
    if(k==0 || n==k) return 1;
    long long ret = fact[n] * fact_inv[k] % mod * fact_inv[n-k] % mod;
    return ret;
  }
};

int main(){
  int q;
  cin >> q;

  combination_mod c(mod, mod+10);

  while(q--){
    long long x, d, n;
    cin >> x,d,n;

    if(d == 0){
      println(my_pow_mod(x, n, mod));
      continue;
    }

    if(x == 0){
      println(0);
      continue;
    }

    long long y = x * my_pow_mod(d, mod-2, mod) % mod;

    // eprintln(y);
    if(y + n > mod){
      println(0);
      continue;
    }

    long long ans = c.fact[y+n-1] * my_pow_mod(d, n, mod) % mod;
    if(y != 0){
      println(ans * my_pow_mod(c.fact[y-1], mod-2, mod) % mod);
    }else{
      println(ans);
    }
  }

  return 0;
}

