vector<ll> fact(MOD*2), inv(MOD*2);

ll power(ll x, ll n){
    x %= MOD;
    ll res = 1;
    while(n>0){
        if(n&1){
            res = res*x%MOD;
        }
        x = x*x%MOD;
        n >>= 1;
    }
    return res;
}

ll init(){
    fact[0] = 1;
    inv[0] = 1;
    for(int i=1;i<MOD*2;i++){
        fact[i] = fact[i-1]*i%MOD;
        inv[i] = power(fact[i], MOD-2);
    }
}

ll solve(ll x, ll d, ll n){
    if(x==0 || n>=MOD) return 0;
    if(d==0) return power(x,n);
    ll y = x*power(d,MOD-2)%MOD;
    if(y%MOD > (y+n-1)%MOD) return 0;
    return power(d,n)*fact[y+n-1]%MOD*inv[y-1]%MOD;
}

int main(){
