class fact {
public:
	long long fmod = 1e9+7;
	vector<long long> fac, inv;
	fact (long long n, long long Mod = 1e9+7) {
		fmod = Mod;
		fac = vector<long long>(n,0);
		inv = vector<long long>(n,0);
		fac[0] = 1; for (long long i = 1; i < n; i++) fac[i] = fac[i-1] * i % fmod;
		for (long long i = 0;i < n;i++) inv[i] = fact::POW(fac[i],fmod-2);
	}
	ll nCr(ll n, ll r) {return (fac[n] * inv[r] % fmod) * inv[n-r] % fmod;}
	ll POW(ll a, ll b) {ll c = 1; while (b > 0) {if (b & 1) {c = a * c%fmod;}a = a * a%fmod; b >>= 1;}return c;}
};

