const ll M = 1000003;

class Felmat
{
  ll M;
  vector<ll> fac;  // n! (mod M)
  vector<ll> ifac; // k!^{M-2} (mod M)

public:
  Felmat(ll max_nk, ll m)
  {
    M = m;
    fac.reserve(max_nk + 1);
    ifac.reserve(max_nk + 1);
    fac[0] = 1;
    ifac[0] = 1;
    for (ll i = 0; i < max_nk; i++) {
      fac[i + 1] = fac[i] * (i + 1) % M;              // n! (mod M)
      ifac[i + 1] = ifac[i] * mpow(i + 1, M - 2) % M; // k!^{M-2} (mod M)
    }
  }
  ll mfac(ll x)
  {
    int i;
    return fac[x];
  }
  ll mpow(ll x, ll n)
  { // x^n (mod M)
    ll ans = 1;
    while (n != 0) {
      if (n & 1)
        ans = ans * x % M;
      x = x * x % M;
      n = n >> 1;
    }
    return ans;
  }
  ll minv(ll a)
  { // 1/a (mod M)
    ll b = M, u = 1, v = 0;
    while (b) {
      ll tmp = a / b;
      a -= tmp * b;
      swap(a, b);
      u -= tmp * v;
      swap(u, v);
    }
    u %= M;
    if (u < 0)
      u += M;
    return u;
  }
  ll comb(ll n, ll k)
  { // nCk (mod M)
    if (n == 0 && k == 0)
      return 1;
    if (n < k || n < 0)
      return 0;
    ll tmp = ifac[n - k] * ifac[k] % M;
    return tmp * fac[n] % M;
  }
  ll perm(ll n, ll k)
  { // nPk (mod M)
    if (n < k)
      return 0;
    ll tmp = ifac[n - k] % M;
    return tmp * fac[n] % M;
  }
};

int main()
{
  int q;
  Felmat fm(1000003, M);
  cin >> q;
  int i;
  for (i = 0; i < q; i++) {
    ll x, d, n, j;
    cin >> x >> d >> n;
    ll ans = 0;
    if (x == 0) {
      ans = 0;
    } else if (d == 0) {
      ans = fm.mpow(x, n);
    } else {
      ll x_d = x * fm.minv(d) % M;
      if (M <= x_d + n - 1) {
        ans = 0;
      } else {
        ans = fm.mfac(x_d + n - 1);
        ans = ans * fm.minv(fm.mfac(x_d - 1)) % M;
        ans = ans * fm.mpow(d, n) % M;
      }
    }
    cout << ans << endl;
  }
  return 0;
}

