constexpr uint64_t kMod = 1000003;

uint64_t Solve(uint64_t x, uint64_t d, uint64_t n) {
  uint64_t result = x % kMod;
  for (uint64_t i = 1; i < n; i++) {
    uint64_t r = x + (i * d);
    result *= r % kMod;
    if (result > kMod) {
      result %= kMod;
    }
  }
  return result % kMod;
}

