			cout << 0 << '\n';
		}
		else
		{
			n %= MOD;
			Int ans = 1, v = Int(x);
			for (int i = 0; i < n; i++)
			{
				ans *= v;
				v += d;
			}
			cout << ans << '\n';
		}
	}
}

