#define MX1 200
#define MOD 1000003
#define SIZE 100005

using namespace std;
typedef long long int ll;
typedef pair <int,int> P;
typedef pair <P,int> PP;

struct Q
{
	int x,i,d,n;
	int id;
	Q(int x=0,int i=0,int d=0,int n=0,int id=0):x(x),i(i),d(d),n(n),id(id){}
};
ll ans[SIZE];
vector <Q> query[MX1];
int ord[MOD];
ll prod[MOD];
ll prod2[MOD];

ll inv[MOD],fac[MOD],finv[MOD];
void make()
{
	fac[0]=fac[1]=1;
	finv[0]=finv[1]=1;
	inv[1]=1;
	for(int i=2;i<MOD;i++)
	{
		inv[i]=MOD-inv[MOD%i]*(MOD/i)%MOD;
		fac[i]=fac[i-1]*(ll) i%MOD;
		finv[i]=finv[i-1]*inv[i]%MOD;
	}
}
ll mpow(ll x,ll t)
{
	if(t==0) return 1;
	ll ret=mpow(x,t/2);
	ret=ret*ret%MOD;
	if(t%2==1) ret=ret*x%MOD;
	return ret;
}
void solve(int t)
{
	int x,d,n;
	scanf("%d %d %d",&x,&d,&n);
	for(int i=1;;i++)
	{
		ll a=(ll) d*(ll) i%MOD;
		if(a<MX1)
		{
			query[a].push_back(Q(x,i,d,n,t));
			break;
		}
		ll b=MOD-a;
		if(b<MX1)
		{
			ll f=x+(ll) (n-1)*(ll) d;
			f%=MOD;
			query[b].push_back(Q(f,i,MOD-d,n,t));
			break;
		}
	}
}
int main()
{
	make();
	int q;
	scanf("%d",&q);
	for(int t=0;t<q;t++)
	{
		solve(t);
		ans[t]=1;
	}
	for(int i=0;i<MX1;i++)
	{
		if(query[i].empty()) continue;
		if(i==0)
		{
			for(int j=0;j<query[i].size();j++)
			{
				Q p=query[i][j];
				ll x=p.x;
				for(int k=0;k<p.i;k++)
				{
					int c=(p.n-k+p.i-1)/p.i;
					ans[p.id]=ans[p.id]*mpow(x,c)%MOD;
					x+=p.d;
					if(x>=MOD) x-=MOD;
				}
			}
		}
		else
		{
			int pos=0;
			ll pr=1,pr2=1;
			for(int j=1;j<MOD;j++)
			{
				pos+=i;
				if(pos>=MOD) pos-=MOD;
				ord[pos]=j;
				pr=pr*(ll) pos%MOD;
				prod[pos]=pr;
				prod2[pos]=pr2;
				pr2=pr2*inv[pos]%MOD;
			}
			for(int j=0;j<query[i].size();j++)
			{
				Q p=query[i][j];
				//printf("%d : %d %d %d %d : %d\n",i,p.x,p.i,p.d,p.n,p.id);
				ll x=p.x;
				for(int k=0;k<p.i;k++)
				{
					int c=(p.n-k+p.i-1)/p.i;
					ll to=x+(ll) (c-1)*(ll) i;
					to%=MOD;
					//if(p.id==0) printf("%lld %lld : %d %d\n",x,to,ord[x],ord[to]);
					if(ord[to]==ord[x]+c-1) ans[p.id]=ans[p.id]*prod2[x]%MOD*prod[to]%MOD;
					else
					{
						ans[p.id]=0;
						break;
					}
					x+=p.d;
					if(x>=MOD) x-=MOD;
				}
			}
		}
	}
	for(int i=0;i<q;i++) printf("%lld\n",ans[i]);
	return 0;
}

