	int mod=1e6+3;
	modCalc mc(mod,mod-1);

	rep(i,q){
	int x0=x[i],d0=d[i],n0=n[i];
	if(x0==0){cout<<0<<endl;continue;}
	if(d0==0){cout<<mc.modpow(x0,n0)<<endl;continue;}
	if(n0==1){cout<<x0<<endl;continue;}

	int dn=mc.modpow(d0,n0);
	int xd=mc.modinv(d0)*x0%mod;
	if(xd+n0-1>=mod){cout<<0<<endl;continue;}
	int ret=mc.nPm(xd+n0-1,n0)*dn%mod;	
	cout<<ret<<endl;
	}


}

