vector<mint> f, fi;
inline mint mpow(mint x, ll n) {
    mint res = 1;
    while(n > 0) {
        if(n & 1) {
            res *= x;
        }
        x = x * x;
        n >>= 1;
    }
    return res;
}
void comb(int n) {
    f.resize(n + 1);
    fi.resize(n + 1);
    f[0] = 1;
    for(ll i = 1; i <= n; i++) {
        f[i] = f[i - 1] * i;
    }
    fi[n] = mpow(f[n], MOD - 2LL);
    for(ll i = n - 1; i >= 0; i--) {
        fi[i] = fi[i + 1] * (i + 1LL);
    }
}
mint ncr(ll n, ll r) {
    if(n < r || n < 0 || r < 0) {
        return 0;
    }
    return f[n] * fi[r] * fi[n - r];
}
int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int q;
