long long modpow(long long a, long long b, long long m) {
	long long p = 1, q = a;
	for (int i = 0; i < 22; i++) {
		if ((b & (1LL << i)) != 0) { p *= q; p %= m; }
		q *= q; q %= m;
	}
	return p;
}

long long mod = 1000003;
long long fact[3000003], inv[1000007];

void init() {
	for (int i = 0; i < 1000003; i++) inv[i] = modpow(i, mod - 2, mod);
	fact[0] = 1;
	for (int i = 1; i <= 3000000; i++) fact[i] = (1LL * fact[i - 1] * i) % mod;
}

long long query(long long N, long long X, long long D) {
	if (D == 0) {
		return modpow(X, N, mod);
	}
	if (N >= 1000003) return 0;
	if (X == 0) return 0;

	long long E1 = (X * inv[D]) % mod; // 初項が何番目か
	long long P1 = fact[E1 + N - 1];
	long long P2 = fact[E1 - 1];
	long long P3 = modpow(P2, mod - 2, mod);
	long long P4 = modpow(D, N, mod);
	return ((P1 * P3 % mod) * P4 % mod);
}

