template<int mod=MOD>
inline Num<mod> mod_pow(Num<mod> x, Int k){
	if(k==0) return 1;
	Num<mod> res(mod_pow(x,k/2));
	res*=res;
	if(k%2)res*=x;
	return res;
}
template<int mod=MOD>
inline Num<mod> mod_pow2(Int x, Int k){
	if(k==0) return 1;
	Num<mod> res(mod_pow2(x,k/2));
	res*=res;
	if(k%2)res*=x;
	return res;
}

