vi fac(MAX_N); //n!(mod M)
vi ifac(MAX_N); //k!^{M-2} (mod M)
vi inv(MAX_N);

ll mpow(ll x, ll n) {
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % MOD;
        x = x*x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll comb(ll a, ll b) {
    if(a == 0 && b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b]* ifac[b] % MOD;
    return tmp * fac[a] % MOD;
}

ll p(ll x, ll n) {
  return fac[x] * ifac[x-n];
}

void init() {
  fac[0] = 1; ifac[0] = 1; inv[0] = 1;
  for (ll i = 0; i<MAX_N; i++){
      fac[i+1] = fac[i] * (i+1) % MOD;
      inv[i+1] = mpow(i+1, MOD-2);
      ifac[i+1] = ifac[i] * inv[i+1] % MOD;
  }
}

ll calc(ll x, ll d, ll n) {
  ll rec = p(((MOD-x)*inv[d])%MOD, n) * mpow(MOD-d, n);
  return rec % MOD;
}

