//ここから編集する
class Combination {

public:
    vector<ll> fact;

    Combination() {

    }

    Combination(int max_n) {
        //1 ~ n!までの階乗modを求める
        int n = max_n;
        vector<ll> fact(n + 1);
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        this->fact = fact;
    }


    template<typename T>
    //templateをつかってみｔか
    ll pow(T x, int y) {
        if (y == 0) return 1;
        if (y == 1) return x;
        if (y == 2) return (x * x) % MOD;
//        if (y % 2 == 1) return pow(x, y / 2) * pow(x, y / 2) % MOD;
        if (y % 2 == 1) return pow(pow(x, y / 2), 2) * x % MOD;
//        return pow(x, y / 2) * pow(x, y / 2) % MOD;
        return pow(pow(x, y / 2), 2) % MOD;
    }

    ll nCk(int n, int k) {
//        return (fact[n] * pow(fact[n-k],MOD-2) * pow(fact[k],MOD-2)) % MOD;
        return (((fact[n] * pow(fact[n - k], MOD - 2)) % MOD) * pow(fact[k], MOD - 2)) % MOD;
    }

    /**
     * x ^ -1を求める
     */
    template<typename T>
    ll inv(T x) {
        return pow(x, MOD - 2);
    }
};

class Solve {
public:
    Combination cmb;

    void input() {
        cmb = Combination(1000003);
    }

    void query(ll x, ll d, ll n) {
        if (d == 0) {
            ll ans = cmb.pow(x, n);
            cout << ans << endl;
            return;
        }
        if (n >= MOD) {
            cout << 0 << endl;
            return;
        }
        ll begin = (x * cmb.inv(d)) % MOD;
        ll end = (begin + n - 1) % MOD;

        ll ans = cmb.fact[end];
        if (x > 0) {
            ll tmp = begin - 1;
            if (tmp < 0) tmp += MOD;
            ans *= cmb.inv(cmb.fact[tmp]);
            ans %= MOD;
        }
//        ans *= cmb.inv(cmb.pow(d, n));
        ans *= cmb.pow(d, n);
        ans %= MOD;
        cout << ans << endl;
    }

    void solve() {
        input();
        int q;
        cin >> q;
        while (q--) {
            ll x, d, n;
            cin >> x >> d >> n;
            query(x, d, n);
        }

    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

