constexpr ll MOD = 1000003LL;
ll myPow(ll x, ll n, ll m) {
	if (n == 0)
		return 1;
	if (n % 2 == 0)
		return myPow(x * x % m, n / 2, m);
	else
		return x * myPow(x, n - 1, m) % m;
}

int main() {
#ifdef DEBUG
	ifstream ifs("in.txt");
	cin.rdbuf(ifs.rdbuf());
#endif

	auto FAC = make_v(MOD + 1, 0LL);
	auto DEFAC = make_v(MOD + 1, 0LL);
	FAC[0] = 1;
	FAC[1] = 1;
	FOR(i, MOD) {
		auto j = i + 2;
		if (j >= MOD) break;
		FAC[j] = (FAC[j - 1] * static_cast<ll>(j)) % MOD;
	}
	DEFAC[MOD - 1] = myPow(FAC[MOD - 1], MOD - 2, MOD);
	for (auto i = MOD - 2; i > 0; --i) {
		DEFAC[i] = DEFAC[i + 1] *  ll(i+1 ) % MOD;
	}
	DEFAC[0] = -1;



	ll Q; cin >> Q;


	FOR(i, Q) {
		ll x, d, n;
		cin >> x >> d >> n;
		if (d == 0) {
			cout << myPow(x, n, MOD) << endl;
			continue;
		}
		ll k = (x * myPow(d, MOD - 2, MOD) % MOD);
		ll rightLimit = k + n - 1;
		ll ans;
		if (rightLimit >= MOD or k == 0) {
			ans = 0;
		}
		else {
			ans = FAC[rightLimit];
			ans = ans * DEFAC[k - 1] % MOD;
			ans = ans * (myPow(d, n, MOD)) % MOD;
		}

		cout << ans % MOD << endl;

	}

	return 0;
}

