        if(n >= MOD){ cout << 0 << endl; continue; }

        long long int x0 = x * modpow(d, MOD-2) % MOD;
        long long int ans = f[x0 + n-1] * modpow(f[x0 - 1], MOD-2) % MOD;
        ans *= modpow(d, n);
        ans %= MOD;
        cout << ans << endl;
    }
    return 0;
}

