template<class T=int, T P=1000003>
struct ModuloP {
    T x;
    ModuloP() : x(0) {}
    ModuloP(T y) { x = y%P; if(x < 0) x += P; }
    ModuloP<T> operator+(const ModuloP<T> y) { return (ModuloP<T>(x)+=y); }
    ModuloP<T> operator*(const ModuloP<T> y) { return (ModuloP<T>(x)*=y); }
    ModuloP<T> operator-(const ModuloP<T> y) { return (ModuloP<T>(x)-=y); }
    ModuloP<T> operator/(const ModuloP<T> y) { return (ModuloP<T>(x)/=y); }
    ModuloP<T> operator-() { return (x == 0) ? ModuloP<T>(P-x) : ModuloP<T>(x); }
    ModuloP<T>& operator+=(ModuloP<T> y) { x+=y.x; if(x>=P)x-=P; return *this; }
    ModuloP<T>& operator*=(ModuloP<T> y) { x=(1LL*x*y.x)%P; return *this; }
    ModuloP<T>& operator-=(ModuloP<T> y) { x+=P-y.x; if(x>=P)x-=P; return *this; }
    ModuloP<T>& operator/=(ModuloP<T> y) { return ((*this)*=y.fermetinv()); }
    bool operator==(const ModuloP<T> y) { return x == y.x; }
    bool operator!=(const ModuloP<T> y) { return x != y.x; }
    bool operator<(const ModuloP<T> y) { return x < y.x; }
    bool operator<=(const ModuloP<T> y) { return x <= y.x; }
    bool operator>(const ModuloP<T> y) { return x > y.x; }
    bool operator>=(const ModuloP<T> y) { return x >= y.x; }

    ModuloP<T> pow(T n) { // O(log n)
        ModuloP<T> ans(1), t(x);
        while(n) {
            if(n & 1) ans *= t;
            t *= t; n >>= 1;
        }
        return ans;
    }

    ModuloP<T> fermetinv() { return pow(P-2); }
};
