const ll MOD = 1000003;
const ll max_n = 2000010;

ll fact_[max_n];
bool fact_init = false;

ll mod(ll a, ll b){
  a %= b;
  return a < 0 ? a + b : a;
}

ll powmod(ll a, ll b){
  if(b == 0) return 1;
  if(b & 1) {
    return a * powmod(a, b - 1) % MOD;
  } else {
    ll d = powmod(a, b / 2) % MOD;
    return d * d % MOD;
  }
}

ll sub(ll a, ll b){
  a %= MOD, b %= MOD;
  a -= b;
  return a < 0 ? a + MOD : a;
}

ll inv(ll a){
	return powmod(a, MOD - 2);
}

ll fact(ll n){
    if(!fact_init){
		fact_[0] = 1;
		fact_[1] = 1;

		for(ll i = 2; i < max_n; i++){
			fact_[i] = fact_[i-1] * i;
			fact_[i] %= MOD;
		}

		fact_init = true;
	}

    return fact_[n];
}

ll comb(ll n, ll k){

	ll ret = fact(n);
	ret *= powmod(fact(k),MOD-2);
	ret %= MOD;
	ret *= powmod(fact(n-k),MOD-2);
	ret %= MOD;
	return ret;

	// X^(-1) = X^(p-2) (mod p) (Fermat's little theorem)
}
