    cin >> a.n >> d.n >> n;
    if (d.n == 0) {
      cout << modpow(a, n) << '\n';
      continue;
    } else if (a.n == 0) {
      cout << 0 << '\n';
      continue;
    }
    mint ans = modpow(d, n);
    mint x = a * modinv(d);
    if (x.n + n - 1 >= MOD) {
      cout << 0 << '\n';
    } else {
      ans *= F(x.n + n - 1) * R(x.n - 1);
      cout << ans.n << '\n';
    }
  }
}

