ll calc_pow(ll x, ll pow) {
    if (pow == 0) return 1;
    ll a = calc_pow(x, pow / 2);
    a = a * a % mod;
    if (pow % 2 == 1) a *= x;
    return a % mod;
}

ll waru(ll a, ll b) {
    return a * calc_pow(b % mod, mod - 2) % mod;
}

