const ll MOD = (ll)1e6 + 3;
ll add(ll x, ll y) {
	x += y;
	if (x >= MOD) return x - MOD;
	return x;
}
ll sub(ll x, ll y) {
	x -= y;
	if (x < 0) return x + MOD;
	return x;
}
ll mult(ll x, ll y) {
	return (x * y) % MOD;
}
ll bin_pow(ll x, ll p) {
	if (p == 0) return 1;
	if (p & 1) return mult(x, bin_pow(x, p - 1));
	return bin_pow(mult(x, x), p / 2);
}
ll rev(ll x) {
	return bin_pow(x, MOD - 2);
}

ll pref[MOD + 5];

ll solve() {
	ll x, d, n;
	scanf("%lld%lld%lld", &x, &d, &n);
	if (x == 0) return 0;
	if (d == 0) return bin_pow(x, n);
	x = mult(x, rev(d));
	if (x + n >= MOD) return 0;
	ll res = mult(pref[x + n - 1], rev(pref[x - 1]));
	res = mult(res, bin_pow(d, n));
	return res;
}

int main()
{
//	freopen("input.txt", "r", stdin);
//	freopen("output.txt", "w", stdout);

	pref[0] = 1;
	for (int i = 1; i < MOD; i++)
		pref[i] = mult(pref[i - 1], i);

	int q;
	scanf("%d", &q);
	while(q--) printf("%lld\n", solve());

	return 0;
}

