ll fact_inv[SZ];
ll choose(int n, int r) {
  if (n < 0 || r < 0 || n < r) return 0;
  return fact[n] * fact_inv[n-r] % MOD * fact_inv[r] % MOD;
}
ll mod_pow(ll a, ll b, ll p) {
  ll res = 1;
  while (b > 0) {
    if (b & 1) res = (res * a) % p;
    a = (a * a) % p;
    b >>= 1;
  }
  return res;
}

ll mod_inv(ll a, ll p) {
  return mod_pow(a % p, p - 2, p);
}

ll easy(ll a, ll n) {
  if (n >= MOD) return 0;
  ll s = a % MOD;
  ll t = (a + n - 1 + MOD) % MOD;
  if (s > t) return 0;
  if (s == 0) return 0;
  return fact[t] * fact_inv[s-1] % MOD;
}

