int main(){
    using namespace std;
    constexpr unsigned long MOD = 1000003;
    vector<unsigned long> fr(MOD, 1), inv(MOD, 1), ifr(MOD, 1);
    iota(fr.begin() + 1, fr.end(), 1UL);
    for(unsigned long i = 2; i < MOD; ++i)inv[i] = (MOD - MOD / i) * inv[MOD % i] % MOD;
    partial_sum(fr.begin(), fr.end(), fr.begin(), [&MOD](auto a, auto b){return a * b % MOD;});
    partial_sum(inv.begin(), inv.end(), ifr.begin(), [&MOD](auto a, auto b){return a * b % MOD;});
    unsigned long Q;
    cin >> Q;
    auto modpow = [&MOD](auto a, auto b, auto n){
        a %= MOD;
        while(n){
            if(n & 1)(a *= b) %= MOD;
            (b *= b) %= MOD;
            n >>= 1;
        }
        return a;
    };
    for(unsigned long iter = 0, x, d, n; iter < Q; ++iter){
