        lint x, d, n;
        cin >> x >> d >> n;
        if (d == 0) {
            cout << power(x, n) << endl;
        } else {
            lint ans = power(d, n);
            lint a = x * minv(d) % MOD;
            lint b = (a + n - 1) % MOD;
            ans = ans * fact[b] % MOD * minv(fact[(a - 1 + MOD) % MOD]) % MOD;
            cout << ans << endl;
        }
    }

    return 0;
}

