template <typename T>
T modpow(T x, T n, T m) {
  if (n == 0) return 1;
  if (n % 2 == 0) {
    return modpow(x * x % m, n / 2, m);
  } else {
    return x * modpow(x, n - 1, m) % m;
  }
}

template <typename T>
T modinv(T a, T m) {
  T b = m, u = 1, v = 0;
  while (b != 0) {
    const auto t = a / b;
    a -= t * b;
    std::swap(a, b);
    u -= t * v;
    std::swap(u, v);
  }
  u %= m;
  if (u < 0) {
    u += m;
  }
  return u;
}

