vector<int> doublestep(int p){
  vector<int> y = {};
  while (p != 0){
    y.push_back(p%2);
    p /= 2;
  }
  reverse(y.begin(), y.end());
  return y;
}
int64_t doubling(int z, int num){
  vector<int> y = doublestep(num);
  int64_t tet = 1;
  for (int i=0;i<y.size();i++){
    if (y.at(i) == 1){
      tet *= z;
      tet %= mod;
    }
    if (i != y.size() - 1){
      tet *= tet;
      tet %= mod;
    }
  }
  return tet;
}
