const ll k = 1000003;
#define mod %
ll f[2*k+10] , inv[2*k+10] , fin[2*k+10];
void factorial()
{
    f[0] = 1 ;
    f[1] = 1 ;
    forn(i , 2 , 2*k+5){
       f[i] = (i*f[i-1]) mod k ;
    }
}
void inverse()
{
    inv[0] = inv[1] = 1 ;
    forn(i , 2 , 2*k+5){
       inv[i] = (inv[k mod i]*(k-k/i)) mod k ;
    }
}
void factinverse()
{
    fin[0] = fin[1] = 1 ;
    forn(i , 2 , 2*k+5){
       fin[i] = (inv[i] * fin[i-1]) mod k ;
    }
}
ll exp(ll x , ll y)
{
    if(y == 0 ) return 1 ;
    if(y & 1){
        return (((x*exp(x,y/2)) mod k) * exp(x,y/2)) mod k;
    }
    else return (((exp(x,y/2)) mod k) * exp(x,y/2)) mod k;
}
int main()
{
    ios;
    factorial();
    inverse();
    factinverse();
    ll q;
    cin >> q ;
    while(q--){
        ll x , d , n ;
        cin >> x >> d >> n ;
        if(d==0){
            cout << exp(x , n ) ;
            con ;
        }
        else if(d == 1) {
            ll ans = (f[x+n-1] * fin[x-1]) mod k ;
            cout << ans << el ;
            con ;
        }
        else {
            ll dinv = exp(d , k-2) ;
            ll X = (x*dinv) mod k ;
            ll ans = (f[X+n-1]*fin[X-1]) mod k ;
            ll dn = exp(d , n ) ;
            ans = (ans * dn) mod k ;
            cout << ans << el ;
            con ;
        }
    }
}

