        ll val = (n + b_div_a - 1) % mod;
        ll ans = 1;
        ll n_mod = n % mod;
        if(n_mod > 0) {
            if(val - n_mod >= 0) {
                ans = fact[val] * __pow(fact[val - n_mod], mod - 2);
            } else {
                ll rest = n_mod - (val + 1);
                ans = fact[val];
                (ans *= fact[mod - 1] * __pow(fact[mod - 1 - rest], mod - 2)) %= mod;
            }
        }
        (ans *= __pow(fact[mod - 1], n / mod)) %= mod;
        (ans *= __pow(a, n)) %= mod;
        cout << ans << endl;
    }
