			}
			ll ans = co.f[x+n-1]*co.fr[x-1]%md;
			cout << ans << endl;
			continue;
		}
		(x *= co.calc(d,md-2)) %= md;
		if(x+n-1>=md){
			cout << 0 << endl;
			continue;
		}
		ll ans = co.calc(d,n) * co.f[x+n-1] % md;
		if(x>0)(ans *= co.fr[x-1]) %= md;
		cout << ans << endl;
	}
}

