  if(d == 0)
    ans = calc(x);
  else{
      x *= inverse[d];
      x %= N;
      if((x + n + N - 1) % N > (x + N - 1) % N && n < N) {
        ans = factorial[(x + n + N - 1) % N] *
        finverse[(x + N - 1) % N] % N * calc(d) % N;
    }
  }
  return ans;
}

long long calc(long long now) {
  long long ans = 1, nown = n;
  memo[0] = now;
  for(long long i = 1; i < 33; ++i)
    memo[i] = memo[i - 1] * memo[i - 1] % N;
  for(long long i = 32; i >= 0; --i)
    if((1LL << i) <= nown) {
      nown -= 1LL << i;
      ans *= memo[i];
      ans %= N;
    }
  return ans;
}

