ll frac(ll n) {
	static VL memo(MOD + 1, 1);
	static ll now = 2;
	if (n >= MOD) { return 0; }
	if (n < now) { return memo[n]; }

	FOR(i, now, n + 1) {
		memo[i] = (memo[i - 1] * i) % MOD;
	}
	now = n + 1;
	return memo[n];
}

