vector<modint> fact, fact_inv;

void factinit(const ll &MAX) {
    fact.resize(MAX + 1);
    fact_inv.resize(MAX + 1);
    fact[0] = 1;
    rep(i, MAX) fact[i + 1] = fact[i] * (i + 1);
    fact_inv[MAX] = fact[MAX].inverse();
    for(int i = MAX; i; i--)
        fact_inv[i - 1] = fact_inv[i] * i;
}

modint solve1(const modint &x, const int &n) {
    int xint = x.getint();
    if(xint + n - 1 >= 1000003) return 0;
    if(xint == 0) return 0;
    return fact[xint + n - 1] * fact_inv[xint - 1];
}

modint solve(const modint &x, const modint &d, const int &n) {
    if(d == 0) return x.pow(n);
    int dint = d.getint();
    return solve1(x / d, n) * (fact[dint] * fact_inv[dint - 1]).pow(n);
}

