  invfac[n-1] = inv_mod(fac[n-1],MOD);
  for (int i = n-2; i >= 0; i--) invfac[i] = invfac[i+1]*(i+1)%MOD;
  for (int i = 1; i < n; i++) inv[i] = invfac[i]*fac[i-1]%MOD;
}

