const lint MOD = 1000003;

long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a / b * x;
    return d;
}

inline lint mod(lint a, lint m) {
    return (a % m + m) % m;
}

lint modinv(lint a, lint m) {
    lint x, y;
    extGCD(a, m, x, y);
    return mod(x, m);
}

lint modPow(lint x, lint k) {
	lint ret = 1;	
	while (k > 0) {
		if (k & 1) modMul(ret, x, MOD);
		modMul(x, x, MOD);
		k >>= 1;
	}
	return ret;
}

const int MAX_I = 1000005;
lint modfact[MAX_I];
lint invfact[MAX_I];

void solve(lint x, lint d, lint n) {
	lint dn = modPow(d, n);	
	lint base = (x * modinv(d, MOD)) % MOD;
	if (x % MOD == 0 || d % MOD == 0 || base == 0 || base + n - 1 >= MOD) {
		cout << 0 << endl;
		return;
	}
	lint ans = modfact[base + n - 1];
	modMul(ans, invfact[base - 1], MOD);
//	for_(i,0,n) {
//		lint ai = (base + i) % MOD;
//		modMul(ans, ai, MOD);
//	}
	modMul(ans, dn, MOD);
	cout << ans << endl;
}

