// 逆元を求める
long long mod_inv(long long value) {

	long long b = mod, u = 1LL, v = 0LL;

	while (b) {
		long long t = value / b;
		value -= t * b;
		swap(value, b);
		u -= t * v;
		swap(u, v);
	}
	u %= mod;
	if (u < 0) u += mod;

	return u;
}

ll mod_pow(ll num, long long n) {
	long long a = num;
	long long res = 1;
	while (n > 0) {
		if (n & 1) res = res * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return res;
}

