            scanf("%d %d %d",&x,&d,&n);
            x %= MOD;
            d %= MOD;

            if (d==0) {
                printf("%lld\n", pw(x,n));
                continue;
            }

            LL st = x * pw(d, MOD-2) % MOD;
            LL tmp = (MOD-x) * pw(d, MOD-2) % MOD;
            if (n-1>=tmp) {
                puts("0");
                continue;
            }            

            LL ans = pw(d, n) * fct(st+n-1, n) % MOD;
            printf("%lld\n", ans);
        }
    }
    return 0;
}

