using namespace std;

using ll = long long;

const ll MOD = 1000003;

ll modpow(ll x, ll n, ll mod = MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int q;
    cin >> q;

    vector<ll> f(MOD, 1);
    for (int i = 1; i < MOD; i++) f[i] = f[i - 1] * i % MOD;

    for (int i = 0; i < q; i++) {
        ll x, d, n;
        cin >> x >> d >> n;
        if (n == 1) {
            cout << x % MOD << endl;
            continue;
        }

        ll hoge = x * modpow(d, MOD - 2) % MOD;
        ll foo = hoge + n - 1;
        if (hoge == 0 || foo - hoge >= MOD) {
            cout << 0 << endl;
        } else {
            foo %= MOD;
            if (foo == 0 || foo < hoge) cout << 0 << endl;
            else {
                cout << f[foo] * modpow(f[hoge - 1], MOD - 2) % MOD * modpow(d, n) % MOD << endl;
            } 
        }
    }
    return 0;
}

