static SDWORD getContinuousProduct(
    SDWORD lStart,
    SDWORD lNum)
{
    if (0 == (lStart % ANS_MOD)) {
        return 0;
    }
    if (((SQWORD)lStart / ANS_MOD) != ((lStart + lNum - 1LL) / ANS_MOD)) {
        return 0;
    }

    SDWORD lRet = divMod(s_alFactoryTable[lStart + lNum - 1], 
                        s_alFactoryTable[lStart - 1]);
    return lRet;
}


