ll powMod(ll x, ll k) {
  if (k == 0)     return 1;
  if (k % 2 == 0) return powMod(x*x % mod, k/2);
  else            return x*powMod(x, k-1) % mod;
}

ll fact(ll N){
  if(N==0)return 1;
  if(memo[N]!=0)return memo[N];
  return memo[N]=(N*fact(N-1))%mod;
