    for (auto xdn : xdnlist) {
        ll x = get<0>(xdn);
        ll d = get<1>(xdn);
        ll n = get<2>(xdn);
        solve(acum_mlt, acum_mlt_inv, x, d, n);
    }

    return 0;
}

