void Solve(){
  int q;
    scanf("%d",&q);
  int Mod=1000003;
  vector<int> table(Mod);
  vector<int> retable(Mod);

  table[0]=1;
  table[1]=1;
  for(int i=2;i<Mod;++i){
    table[i]=table[i-1]*i%Mod;
  }

  retable[0]=1;
  retable[1]=1;
  for(int i=2;i<Mod;++i){
    retable[i]=modpow(i,Mod-2,Mod);
    retable[i]*=retable[i-1]%Mod;
  }

  for(int i=0;i<q;++i){
    int ans=1;
    int x,d,n;
      scanf("%d%d%d",&x,&d,&n);
    int dm=modpow(d,Mod-2,Mod); 

    if(d==0){
      printf("%d\n",modpow(x,n,Mod));
    }

    else if(n>=Mod){
      printf("%d\n",0);
    }  

    else if((x*dm+n-1)%Mod<=n-1){
      printf("%d\n",0);
    }
    else{
      ans*=table[(x*dm+n-1)%Mod];
      ans*=retable[(x*dm-1+Mod)%Mod]%Mod;
      ans*=modpow(d,n,Mod)%Mod;
      printf("%d\n",ans);
    }
  }
}

#include<bits/stdc++.h>
using namespace std;
// #define ll long long int
#define int long long int
#define N 10000005
#define MOD 1000003

int fact[N], inv[N], finv[N];

int mexp(int a, int b)
{
	int res = 1;
	while(b)
	{
		if(b & 1)
			res = res * a % MOD;
		b >>=1;
		a = a * a % MOD;
	}
	return res;
}

void make()
{
	fact[0] = fact[1] = 1;
	inv[1] = 1;
	finv[1] = finv[0] = 1;
	for (int i = 2; i <= N; ++i)
	{
		fact[i] = fact[i - 1] * i % MOD;
		inv[i] = MOD - (MOD/i) * inv[MOD % i] % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

int32_t main()
{
	ios::sync_with_stdio(false);
	cin.tie(NULL);

	make();
	int q;
	int x, d, n;

	cin >> q;

	while(q--)
	{
		cin >> x >> d >> n;
		if(d == 0)
		{
			cout << mexp(x, n) << "\n";
		}
		else
		{
			int k = x * inv[d] % MOD;
			// cout << "k : " << k << '\n';
			int ans;
			if(k + n - 1 >= MOD)
				ans = 0;
			else
			{
				ans = fact[k + n - 1] * finv[k - 1] % MOD;
				ans = ans * mexp(d, n) % MOD;
			}
			cout << ans << "\n";
		}
	}
	return 0;
}

