#define MAXN (1 << 20)

mod f[MAXN];

int solve() {
	int tx, td, tn;
	cin >> tx >> td >> tn;
	if ((tx + tn - 1 >= MOD) || (tx == 0)) {
		return 0;	
	}
	mod x(tx), d(td);
	if (td == 0) {
		return (x.mypow(tn)).x;
	}
	x *= d.inv();
	return ((f[x.x + tn - 1] * f[x.x - 1].inv()) * d.mypow(tn)).x;

}

int main() {
	cout << fixed << setprecision(12);	
	f[0] = mod(1);
	for (int i = 1; i < MOD; i++) {
		f[i] = f[i - 1] * mod(i);
	}

	int q;
	cin >> q;
	while (q--) {
		cout << solve() << endl;
	}

	return 0;
}

