void Solve() {

	mFact(MOD * 3);
	li(Q);
	REP(q, Q) {
		li(x, d, n);
		if (n >= MOD) {
			sal(0);
		}
		else {
			ll y = mll(d).pow(n - 1).v;
			ll z = (mll(x + d) / mll(d)).v;
			ll w = (mFact(z + n - 2) * mFact(z - 1).inv).v;
			sal(mll(x)*mll(y)*mll(w));
		}
	}

}

