typedef long long ll;
const ll mod=1000003;
ll f[1000003];
ll w[1000003];
ll pow(ll d,ll n)
{
    ll res=1;
    while(n)
    {
        if(n&1)
            res=res*d%mod;
        d=d*d%mod;
        n>>=1;
    }
    return res;
}
void init()
{
    f[0]=1;
    for(ll i=1;i<mod;i++)
        f[i]=(i*f[i-1])%mod,w[i]=pow(f[i],mod-2);
}
int main()
{
    init();
    int q;
    scanf("%d",&q);
    ll x,d,n;
    while(q--)
    {
        scanf("%lld%lld%lld",&x,&d,&n);
        if(d==0)
        {
            printf("%lld\n",pow(x,n));
        }
        else
        {
            x=x*pow(d,mod-2)%mod;
            if(x==0 || x+(n-1)>=mod)
            {
                puts("0");
                continue;
            }
            ll ans=(f[x+n-1]*w[x-1])%mod;
            ans=(ans*pow(d,n))%mod;
            printf("%lld\n",ans);
        }
    }
    return 0;
}

