ll MOD = 1000003ll;

ll power(ll x, ll e) {
  ll v = 1;
  for (; e > 0; e >>= 1) {
    if (e & 1) {
      v = v * x % MOD;
    }
    x = x * x % MOD;
  }
  return v;
}

ll inverse(ll x) {
  return power(x, MOD - 2);
}

vector<ll> fact, factInv;
void initFact(int N) {
  fact.resize(N + 1);
  factInv.resize(N + 1);
  fact[0] = 1;
  for (int i = 1; i <= N; i++) {
    fact[i] = fact[i - 1] * i % MOD;
  }
  factInv[N] = inverse(fact[N]);
  for (int i = N - 1; i >= 0; i--) {
    factInv[i] = factInv[i + 1] * (i + 1) % MOD;
  }
}

ll f(ll x, ll d, ll n) {
  if (d == 0) {
    return power(x, n);
  }
  if (d == 1) {
    if (MOD <= x + n - 1) return 0;
    return fact[x + n - 1] * factInv[x - 1] % MOD;
  }
  return f(x * inverse(d) % MOD, 1, n) * power(d, n) % MOD;
}

