		if(n >= mod){
			cout << 0 << endl;
			continue;
		}
		llint l = modpow(d, mod-2) * x % mod;
		llint r = modpow(d, mod-2) * (x + (n-1)*d%mod) % mod;
		if(l > r){
			cout << 0 << endl;
			continue;
		}
		llint ans = fact[r];
		if(l > 0) ans *= fact_inv[l-1], ans %= mod;
		else ans = 0;
		ans *= modpow(d, r-l+1), ans %= mod;
		cout << ans << endl;
	}

	return 0;
}

