using namespace std;

using ll = long long;
constexpr ll MOD = 1000003;

// a^b O(log b)
template <typename T>
T mypow(T a, T b)
{
    if (b == 0)
        return 1;
    T tmp = mypow(a, b / 2);
    if (b % 2)
        return (((tmp * tmp) % MOD) * a) % MOD;
    else
        return (tmp * tmp) % MOD;
}

struct RangeProductQuery
{
    using type = ll;
    static type id() { return 1; }
    static type op(const type &l, const type &r) { return l * r % MOD; }
};

template <typename M>
class DisjointSparseTable
{
    using T = typename M::type;
    std::vector<std::vector<T>> memo;

public:
    DisjointSparseTable(const std::vector<T> &v)
    {
        int b = 0;
        while ((1 << b) <= static_cast<int>(v.size()))
            b++;
        memo.resize(b, std::vector<T>(static_cast<int>(v.size()), M::id()));
        for (int i = 0; i < static_cast<int>(v.size()); i++)
            memo[0][i] = v[i];
        for (int i = 1; i < b; i++)
        {
            int st = 1 << i;
            for (int j = 0; j < static_cast<int>(v.size()); j += st << 1)
            {
                int t = std::min(j + st, static_cast<int>(v.size()));
                memo[i][t - 1] = v[t - 1];
                for (int k = t - 2; k >= j; k--)
                    memo[i][k] = M::op(v[k], memo[i][k + 1]);
                if (static_cast<int>(v.size()) <= t)
                    break;
                memo[i][t] = v[t];
                int r = min(t + st, static_cast<int>(v.size()));
                for (int k = t + 1; k < r; k++)
                    memo[i][k] = M::op(memo[i][k - 1], v[k]);
            }
        }
    }

    // [a, b) の op 結果
    T query(int l, int r)
    {
        if (l >= --r)
            return memo[0][l];
        int b = 31 - __builtin_clz(l ^ r);
        return M::op(memo[b][l], memo[b][r]);
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int q;
    cin >> q;
    vector<ll> v(2222222);
    for (int i = 0; i < 2222222; i++)
        v[i] = i % MOD;
    DisjointSparseTable<RangeProductQuery> dst(v);
    while (q--)
    {
        // x, x+d, ..., ... x+(n-1)d の積mod
        ll x, d, n;
        cin >> x >> d >> n;
        if (n >= MOD)
        {
            cout << 0 << endl;
            continue;
        }
        if(d==0)
        {
            cout << mypow(x, n) << endl;
            continue;
        }
        ll st = x * mypow(d, MOD - 2) % MOD, gt = st + n - 1; // gt < 2 * MOD
        ll ret = mypow(d, n) * dst.query(st, gt + 1) % MOD;
        cout << ret << endl;
    }
}

