ll modpow(ll a, int n) {
    if (n == 0) return 1LL;
    if (n % 2 == 1) return a * modpow(a, n-1) % MOD;
    ll h = modpow(a, n/2);
    return h * h % MOD;
}

ll modinv(ll a) { return modpow(a, MOD-2); }

ll fact[MOD], facti[MOD];
void init() {
    fact[0] = 1;
    facti[0] = modinv(fact[0]);
    for (int i = 1; i < MOD+10; ++i) {
        fact[i] = i * fact[i-1] % MOD;
        facti[i] = modinv(fact[i]);
    }
}

ll solve(ll x, ll d, ll n) {
    if (d == 0) return modpow(x, n);
    ll y0 = x * modinv(d) % MOD;
    if (y0+n-1 >= MOD) return 0LL;
    return modpow(d, n) * fact[y0+n-1] % MOD * facti[y0-1] % MOD;
}

