        }
        if(n >= MOD || x == 0) {
            cout << 0 << endl;
            continue;
        }
        mint t = mpow(mint(d), MOD - 2LL) * mint(x);
        mint ans = mpow(mint(d), n);
        if(t.val == 0) {
            ans = 0;
        } else {
            if(t.val + n - 1 >= MOD) {
                ans = 0;
            } else {
                ans *= f[t.val + n - 1] * fi[t.val - 1];
            }
        }
        cout << ans.val << endl;
    }
}

