ll nod(ll a, ll b, ll x)
{
    if (a == 0)
    {
        X = 0, Y = -x;
        return 1;
    }
    if (b == 0)
    {
        X = x, Y = 0;
        return 1;
    }
    if (a < b)
    {
        ll d = nod(a, b % a, x);
        X += (b / a) * Y;
    }
    else
    {
        ll d = nod(a % b, b, x);
        Y += (a / b) * X;
    }
    return 1;
}

ll binpow(ll x, ll step)
{
    if (step == 0) return 1;
    if (step % 2 == 0)
    {
        ll a = binpow(x, step / 2);
        return a * a % MOD;
    }
    else return x * binpow(x, step - 1) % MOD;
}

