ll Mf[MOD+1];
void Mfi(){
    Mf[0]=Mf[1]=1;
    for(int i=2;i<MOD+1;i++)Mf[i]=(Mf[i-1]*i)%MOD;
}
ll Mp(ll a, ll b){
    if(b==0)return 1;
    else if(b%2==0)return Mp((a*a)%MOD, b/2);
    return (a*Mp(a, b-1))%MOD;
}
ll Mc(ll a, ll b){
    if(a<b)return 0;
    ll c = (Mf[a]*Mp(Mf[a-b], MOD-2))%MOD;
