#define MOD 1000003

long long bipow(long long n, long long m) {
    if (m == 0) return 1;
    if (m % 2 == 0) {
        n = (n * n) % MOD;
        return bipow(n, m / 2) % MOD;
    } else
        return (n * bipow(n, m - 1)) % MOD;
}

int main(){
    vector<long long> fac(MOD);
    fac[0] = 1;
    for(int i=1; i<MOD; i++)
        fac[i] = (fac[i-1] * i) % MOD;

    int Q;
    cin >> Q;
    for(int i=0; i<Q; i++){
        long long x, d, n;
        cin >> x >> d >> n;
        long long ans;
        if(d == 0) ans = bipow(x, n);
        else{
            long long y = (x * bipow(d, MOD-2)) % MOD;
            if(y == 0 || y + n - 1 >= MOD) ans = 0;
            else{
                long long tmp0 = bipow(d, n);
                long long tmp1 = fac[y+n-1];
                long long tmp2 = bipow(fac[y-1], MOD-2);
                ans = tmp0;
                ans = (ans * tmp1) % MOD;
                ans = (ans * tmp2) % MOD;
            }
        }
        cout << ans << endl;
    }
    return 0;
}

