                        continue;
                }
                accum = (accum * i) % mod;
                accumlist.pb(accum);
        }

        V<ll> accuminvlist;
        for (auto accum : accumlist) {
                if (accum == 0) {
                        accuminvlist.pb(1);
                        continue;
