const ll MOD = 1000003;
const long double EPS = 1e-10;
const int dyx[4][2] = {
    { 0, 1}, {-1, 0}, {0,-1}, {1, 0}
};

ll fact[MOD], rfact[MOD];

ll perm(ll n, ll r){
    return (fact[n] * rfact[r]) % MOD;
}

ll comb(ll n, ll r){
    return (perm(n, r) * rfact[n-r]) % MOD;
}

void init(ll n){
    fact[0] = fact[1] = 1;
    rfact[0] = rfact[1] = 1;
    for(int i=2;i<=n;++i) {
        fact[i] = (fact[i-1] * (ll)i) % MOD;
        rfact[i] = 1;
        ll k = MOD-2;
        ll a = fact[i];
        while(k > 0){
            if(k & 1){
                rfact[i] *= a;
                rfact[i] %= MOD;
            }
            a *= a;
            a %= MOD;
            k  >>= 1;
        }
    }
}

ll modpow(ll a, ll t) {
    ll ret = 1LL;
    while(t){
        if(t & 1LL){
            ret *= a;
            ret %= MOD;
        }
        a *= a;
        a %= MOD;
        t >>= 1;
    }
    return ret;
}

ll solve(ll x, ll d, ll n) {
    if(d == 0) return modpow(x, n);
    if(n >= MOD) return 0LL; // 項が MOD 個以上あったらy-1からy-1+nまでにMODの倍数がある
    ll y = (x * modpow(d, MOD-2)) % MOD;
    if((y-1+MOD)%MOD >= (y+n-1+MOD)%MOD) return 0LL;
    ll ret = (fact[(y+n-1+MOD)%MOD] * rfact[(y-1+MOD)%MOD]) % MOD;
    ret = (ret * modpow(d, n)) % MOD;
    return ret;
}

int main() {
    init(MOD-1);

    int q;
    cin >> q;
    ll x, d, n;
    while(q--) {
        cin >> x >> d >> n;
        cout << solve(x, d, n) << endl;
    }

}

