#define MOD   1000003LL

ll make_acum_mlt(ll acum_mlt[MOD+3LL], ll acum_mlt_inv[MOD+3LL])
{
    acum_mlt[0] = 1LL;
    acum_mlt_inv[0] = 1LL;

    srep (i, 1LL, MOD + 3LL) {
        acum_mlt[i] = acum_mlt[i-1] * i;
        acum_mlt[i] %= MOD;
        acum_mlt_inv[i] = mod_inv(acum_mlt[i], MOD);
    }

    debug_printf("---- acum_mlt\n"); debug_print(acum_mlt, 6);
}

void solve(ll acum_mlt[MOD+3LL], ll acum_mlt_inv[MOD+3LL],
           ll x, ll d, ll n)
{
    if (d == 0LL) {
        cout << mod_pow(x, n, MOD) << endl;
        return;
    }

    ll start = x * mod_inv(d, MOD);
    start %= MOD;

    if (start == 0LL) {
        cout << 0 << endl;
        return;
    }

    if (start + n - 1LL >= MOD) {
        cout << 0 << endl;
        return;
    }

    ll ans = acum_mlt[start+n-1LL];
    ans *= acum_mlt_inv[start-1LL];
    ans %= MOD;
    ans *= mod_pow(d, n, MOD);
    ans %= MOD;

    cout << ans << endl;
}

int _main()
{
    ll qcnt; llin(qcnt);
    V<t3> xdnlist; llinl3(xdnlist, qcnt);

    static ll acum_mlt[MOD+3LL];
    static ll acum_mlt_inv[MOD+3LL];
    make_acum_mlt(acum_mlt, acum_mlt_inv);

    for (auto xdn : xdnlist) {
        ll x = get<0>(xdn);
        ll d = get<1>(xdn);
        ll n = get<2>(xdn);
        solve(acum_mlt, acum_mlt_inv, x, d, n);
    }

    return 0;
}

