#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll mod=1000003;
ll f[mod];
ll w[mod];
ll pow(ll d,ll n)
{
    ll res=1;
    while(n)
    {
        if(n&1)
            res=res*d%mod;
        d=d*d%mod;
        n>>=1;
    }
    return res;
}
void init()
{
    f[0]=1;
    for(int i=1;i<mod;i++)
        f[i]=(i*f[i-1])%mod,w[i]=pow(f[i],mod-2);
