    ll x,d,n;
    while(q--)
    {
        scanf("%lld%lld%lld",&x,&d,&n);
        if(d==0)
        {
            printf("%lld\n",pow(x,n));
        }
        if(x+(n-1)>=mod)
            puts("0");
        else
        {
            x=x*pow(d,mod-2)%mod;
            ll ans=(f[x+n-1]*w[x-1])%mod;
            ans=(ans*pow(d,n))%mod;
            printf("%lld\n",ans);
        }
    }
    return 0;
}

