const int max_comb=1000010;
vector<ll> fac(max_comb+1); //n! (mod M)
vector<ll> ifac(max_comb+1); //k!^(-1) (mod M)

ll mpow(ll x, ll n){ //x^n(mod M)
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % MOD;
        x = x*x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll minv(ll x){
    return mpow( x, MOD-2 );
}

ll comb(int a, int b){     // C(a,b) = a! * b!^(-1) * (a-b)^(-1)
    if(a == 0 && b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b]* ifac[b] % MOD;
    return tmp * fac[a] % MOD;
}

ll perm(int a, int b){     // P(a,b) = a! * (a-b)!^(-1)
    if(b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b] % MOD;
    return tmp * fac[a] % MOD;
}

void pre_comb()
{
    fac[0] = 1;
    ifac[0] = 1;
    for(int i = 0; i<max_comb; i++){
        fac[i+1] = fac[i]*(i+1) % MOD; // n!(mod M)
        ifac[i+1] = ifac[i]*minv(i+1) % MOD; // k!^(-1) (mod M)
    }
    return;
}

int main(int argc, char* argv[])
{
    int Q;
    scanf("%d", &Q);

    pre_comb();
    int i;
    for(i=0; i<Q; i++) {
        int x, d, n;
        scanf("%d%d%d", &x, &d, &n);

        ll ans;
        if(d%MOD==0) {
            ans = mpow(x,n);
        }
        else {
            ll tmp = MOD - ((x%MOD) * minv(d))%MOD;
            ll tmp2 = tmp - n + 1;
            if(tmp2<=0) {
                ans=0;
            }
            else {
                ans = (perm(tmp, n) * mpow((MOD-d%MOD), n))%MOD;
            }
        }
        printf("%lld\n", ans);
    }

    return 0;
}

