const int mod = 1000003;

int f[mod], rf[mod];

int mul(int x, int y) {
    return 1LL * x * y % mod;
}

int power(int x, int y) {
    if (y == 0) {
        return 1;
    }
    if (y % 2 == 0) {
        return power(mul(x, x), y / 2);
    }
    return mul(x, power(x, y - 1));
}

int inv(int x) {
    return power(x, mod - 2);
}

void get_all_f() {
    f[0] = rf[0] = 1;
    for (int i = 1; i < mod; ++i) {
        f[i] = mul(f[i - 1], i);
    }
    rf[mod - 1] = inv(f[mod - 1]);
    for (int i = mod - 2; i >= 1; --i) {
        rf[i] = mul(rf[i + 1], i + 1);
    }
}

int q, x, d, n;

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
