        scanf("%d%d%d", &x, &d, &n);
        int res = power(d, n);
        int st = mul(x, inv(d));
        if (st + n - 1 >= mod) {
            res = 0;
        } else {
            res = mul(res, f[st + n - 1]);
            if (st) {
                res = mul(res, rf[st - 1]);
            }
        }
        printf("%d\n", res);
    }
    return 0;
}

