// define MOD before using this function
void mult(ll &a, ll b) {
    a *= b;
    if (a >= MOD) a %= MOD;
}

//Fast Exponentiation
ll fexp(ll base, ll exp, ll mod) {
    ll result = 1;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % mod;
        exp >>= 1;
        base = (base * base) % mod;
    }
    return result;
}

ll fact[MAX], invfact[MAX];

void pre() {
    fact[0] = 1;
    forl(i, 1, MAX, 1) {
        ll j = i * 1ll;
        while (j % MOD == 0) j /= MOD;
        fact[i] = fact[i - 1] * j;
        if (fact[i] >= MOD) fact[i] %= MOD;
    }
    invfact[MOD - 1] = fexp(fact[MOD - 1], MOD - 2, MOD);
    rforl(i, MOD - 2, -1, -1) {
        invfact[i] = invfact[i + 1] * (i + 1);
        if (invfact[i] >= MOD) invfact[i] %= MOD;
    }
}

int main() {
    pre();

	int Q; scanf("%d", &Q);
    while (Q--) {
        ll x, d, n; scanf("%lld%lld%lld", &x, &d, &n);
        if (d == 0) {
            ll ans = fexp(x, n, MOD);
            printf("%lld\n", ans);
            continue;
        }
        ll q = x * fexp(d, MOD - 2, MOD);
        if (q >= MOD) q %= MOD;

        ll ans = 1;
        ans = ans * fexp(d, n, MOD);
        if (ans >= MOD) ans %= MOD;

        if (q + n - 1 >= MOD) ans = 0;
        else {
            mult(ans, fact[q + n - 1]);
            mult(ans, invfact[q - 1]);
        }

        printf("%lld\n", ans);
    }

	return 0;
}

