template<int MOD>
class ModInt {
public:
    ModInt() :value(0) {}
    ModInt(long long val) :value((int)(val<0 ? MOD + val % MOD : val % MOD)) { }

    ModInt& operator+=(ModInt that) {
        value = value + that.value;
        if (value >= MOD)value -= MOD;
        return *this;
    }
    ModInt& operator-=(ModInt that) {
        value -= that.value;
        if (value<0)value += MOD;
        return *this;
    }
    ModInt& operator*=(ModInt that) {
        value = (int)((long long)value * that.value % MOD);
        return *this;
    }
    ModInt &operator/=(ModInt that) {
        return *this *= that.inverse();
    }
    ModInt operator+(ModInt that) const {
        return ModInt(*this) += that;
    }
    ModInt operator-(ModInt that) const {
        return ModInt(*this) -= that;
    }
    ModInt operator*(ModInt that) const {
        return ModInt(*this) *= that;
    }
    ModInt operator/(ModInt that) const {
        return ModInt(*this) /= that;
    }
    ModInt pow(long long k) const {
        ModInt n = *this, res = 1;
        while (k) {
            if (k & 1)res *= n;
            n *= n;
            k >>= 1;
        }
        return res;
    }
    ModInt inverse() const {
        long long a = value, b = MOD, u = 1, v = 0;
        while (b) {
            long long t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        return ModInt(u);
    }
    int toi() const { return value; }

private:
    int value;
};
const int MOD = 1000003;
typedef ModInt<MOD> mint;
ostream& operator<<(ostream& os, const mint& x) {
    os << x.toi();
    return os;
}

void solve() {
    vector<mint> fact(MOD);
    fact[0] = 1;
    FOR(i, 1, MOD)fact[i] = fact[i - 1] * i;

    int Q;
    cin >> Q;
    rep(ITER, Q) {
        int x, d, n;
        cin >> x >> d >> n;
        if (x == 0) {
            cout << 0 << endl;
        } else if (d == 0) {
            cout << mint(x).pow(n) << endl;
        } else {
            int a = (mint(x) / d).toi();
            if (a + (n - 1) >= MOD) {
                cout << 0 << endl;
            } else {
                mint ans = fact[a + (n - 1)] * mint(d).pow(n);
                if (a >= 2)ans /= fact[a - 1];
                cout << ans << endl;
            }
        }
    }
}

int main() {
