ll fact[mod+1];
ll modexp(ll a, ll b)
{
	a%=mod;
	if(a<=1)return a;
	if(b==0)return 1;
	if(b%2==0)
	{
		ll val=modexp(a,b/2);
		return (val*val)%mod;
	}
	return (a*modexp(a,b-1))%mod;
}

