		{
			cout<<0<<"\n";
			continue;
		}
		ll ans=modexp(d,n);
		ll val=(x*modexp(d,mod-2))%mod;
		if((val+1)>mod||(val+n-1)<mod)
		{
			ans=ans*(fact[(val+n-1)%mod]*(modexp(fact[(val-1)%mod],mod-2)))%mod;
