	if (e == 0) {
		return 1;
	}
	else if (e == 1) {
		return base;
	}
	else {
		auto r = power(base, e / 2);
		return (((r * r) % mod) * power(base, e % 2)) % mod;
	}
}
long long int inverse(const long long int base) {
	return power(base, static_cast<int>(mod) - 2);
}
