const long long MOD = 1000003LL;

template <std::uint_fast64_t Modulus> class modint {
  using u64 = std::uint_fast64_t;

public:
  u64 a;

  constexpr modint(const u64 x = 0) noexcept : a(x % Modulus) {}
  constexpr u64 &value() noexcept { return a; }
  constexpr const u64 &value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr modint &operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) {
      a -= Modulus;
    }
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if (a < rhs.a) {
      a += Modulus;
    }
    a -= rhs.a;
    return *this;
  }
  constexpr modint &operator*=(const modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr modint &operator/=(modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp % 2) {
        *this *= rhs;
      }
      rhs *= rhs;
      exp /= 2;
    }
    return *this;
  }
};

using mint = modint<MOD>;

mint beki(int N, mint x) {
    mint ret = 1;
    while (N > 0) {
        if (N&1) ret *= x;
        N >>= 1;
        x *= x;
    }
    return ret;
}

mint func(int N, mint x) {
    if (N==1) return x;
    int M = N/2;
    return func(N-M,x/2)*func(M,(x+1)/2);
}

void solve() {
    int x,d,n; cin >> x >> d >> n;
    if (d) {
        mint p = x;
        p /= d;
        int k = 1;
        int cnt = 0;
        while (2*k <= n) {
            k *= 2;
            cnt++;
        }
        cout << (func(n,p)*beki(n,d)*beki(cnt, beki(n,2))*beki(n-k,4)).a << ln;
    } else {
        cout << beki(n,x).a << ln; 
    }
}
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int Q; cin >> Q;
    while (Q--) {
        solve();
    }
}

