typedef long long ll;

const int mod = M;

ll mod_pow(ll a,ll x){
  ll res=1;
  while(x){
    if(x%2) res=res*a%mod;
    a=a*a%mod;
    x/=2;
  }
  return res;
}

ll inv(ll x){
  return mod_pow( x, mod - 2 );
}

int X[M], invX[M];

void init(){

  int num = 1;

  for(int i=1;i<M;i++){
    num *= i;
    num %= mod;
    X[i] = num;
  }

  for(int i=0;i<M;i++) invX[i] = inv( X[i] );

}

int cal(int x, int d, int n){

  if( d == 0 ) return mod_pow( x, n );

  int R = ( x * inv( d ) + ( n - 1 ) ) % mod;
  int L = ( x * inv( d ) - 1 + mod ) % mod;
  //int l = ( R - ( n - 1 ) - 1 );
  int l = ( x * inv( d ) - 1 );
  if( l <= 0 ) return 0;
  return ( ( X[R] * invX[L] ) % mod * mod_pow( d, n ) ) % mod;
}

