	modfact[0] = 1;
	for_(i,1,1000005) modfact[i] = (modfact[i-1] * i) % MOD;
	for_(q,0,Q) {
		int x, d, n;
		cin >> x >> d >> n;
		solve(x, d, n);
	}
}
