	i64 cur = x * rev(d)%mod;
	if (cur + n - 1 >= mod)
	{
		cout << "0\n";
		return;
	}
	i64 res = f[cur + n - 1] * rev(f[cur - 1]) % mod;
	//cout << f[cur + n - 1] << " " << rev(f[cur - 1]) << endl;
	res = (fast(d, n)%mod * res % mod)%mod;
	cout << res << endl;
