		if(!d) cout << pow2(x,n) << endl;
		else if(n >= MOD) cout << 0 << endl;
		else cout << fact[n] * nCr(MOD - x * mod_inv(d) % MOD,n) % MOD * pow2(MOD - d,n) % MOD << endl;
	}
}

