/*
d==0ならpw(x,n)を求めればいいからO(n logn)
d!=0ならn>=MODの時はx+(n-1)dが0になる時があるのでO(1)
d!=0&&n<MODの時は？愚直に計算したら結局O(Q MOD)で間に合わない
*/
int w[1234567];
int pw(int n,int k){
  if(k<0)return pw(n,k+MOD-1);
  int res=1;
  while(k){
    if(k&1)res*=n;res%=MOD;
    n*=n;n%=MOD;
    k>>=1;
  }
  return res;
}
int g(int a,int n){
  if(a+n-1>=MOD)return 0;
  return w[a+n-1]*pw(w[a-1],MOD-2)%MOD;
}
int f(int x,int d,int n){
  if(d==0)return pw(x,n);
  if(n>=MOD)return 0;
  int D=pw(d,MOD-2);
  int res=pw(d,n);
  res*=g(D*x%MOD,n);
  return res%MOD;
}

