    // 求める積は d^n * (x/d) * (x/d + 1) * ... * (x/d + (n-1))
    // つまり d^n * (x/d + (n-1))! / (x/d - 1)!
    long long xbyd = x * modinv(d, mod) %mod; // x/d (mod)
    if(xbyd==0) xbyd += mod;
    ans = modpow(d, n, mod) * factmod[xbyd + n -1] %mod * modinv(factmod[xbyd-1], mod) %mod;

    cout << ans << endl;
  }
}

