struct Problem {

	static const ULL M = 1000003;

	static ULL Power(ULL a, ULL i) {
		if (i == 0) return 1;
		ULL buf = Power(a, i >> 1);
		buf = buf * buf % M;
		if (i & 1) buf = buf * a % M;
		return buf;
	}

	vector<ULL> I;
	vector<ULL> F;
	vector<ULL> iF;

	ULL Solve2() {
		ULL x, d, n; cin >> x >> d >> n;
		if (n >= M) return 0;
		ULL dpn = Power(d, n);
		ULL a = I[d] * x % M;
		if (a + n - 1 >= M) return 0;
		ULL Fr = F[a + n - 1] * iF[a - 1] % M;
		return dpn * Fr % M;
	}

	void Solve() {
		I.resize(M); F.resize(M); iF.resize(M);
		I[1] = 1; for (UL i = 2; i < M; i++) I[i] = M - M / i * I[M % i] % M;
		F[0] = 1; for (UL i = 1; i < M; i++) F[i] = F[i - 1] * i % M;
		iF[0] = 1; for (UL i = 1; i < M; i++) iF[i] = iF[i - 1] * I[i] % M;

		UL Q; cin >> Q;
		rep(i, Q) {
			cout << Solve2() << endl;
		}
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
