	int ans=1;
	while(b){
		if(b&1)ans=1LL*ans*a%mod;
		a=1LL*a*a%mod;
		b>>=1;
	}
	return ans;
}
void init(int n){
	fac[0]=1;
	for(int i=1;i<=n;++i){
		fac[i]=1LL*fac[i-1]*i%mod;
	}
	finv[n]=qpow(fac[n],mod-2);
	for(int i=n-1;i>=0;--i){
		finv[i]=1LL*finv[i+1]*(i+1)%mod;
	}
