int Solve(int x,int d,int n){
	if(!x)return 0;
	if(!d)return qpow(x,n);
	x=1LL*x*qpow(d,mod-2)%mod;
	if(x+n-1>=mod)return 0;
	int ans=1LL*finv[x-1]*fac[x+n-1]%mod*qpow(d,n)%mod;
	return ans;
}
