const LL MOD = 1e6+3;

LL naive(LL x, LL d, LL n){
  LL res = 1;
  REP(i,n) res = res * (x + d * i) % MOD;
  return res;
}

LL powm(LL a, LL b){
  if(b == 0) return 1;
  return powm(a * a % MOD, b / 2) * (b%2==0?1:a) % MOD;
}

LL inv(LL a){
  return powm(a, MOD-2);
}

const int MAX = 2 * MOD;
LL fact[MAX];
LL facti[MAX];

LL ch(LL n, LL m){
  return fact[n] * facti[m] % MOD * facti[n-m] % MOD;
}


int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);


  fact[0] = 1;
  facti[0] = 1;
  FOR(i,1,MAX){
    fact[i] = fact[i-1] * i % MOD;
    facti[i] = inv(fact[i]);
  }

  int Q;
  cin >> Q;
  while(Q--){
    LL x, d, n;
    cin >> x >> d >> n;


    if(d == 0){
      cout << powm(x, n) << endl;
      continue;
    }
    if(n >= MOD || x == 0){
      cout << 0 << endl;
      continue;
    }

    LL m = x * inv(d) % MOD;
    LL ans = powm(d, n) * fact[m+n-1] % MOD * facti[m-1] % MOD;

    cout << ans << endl;
  }

  return 0;
}

