ll __pow(ll a, ll b) { return b ? (b & 1 ? a : 1) * __pow(a * a % mod, b / 2) % mod : 1; }

int main() {
    V<ll> fact(mod + 10, 1);
    for(ll i = 1; i < fact.size(); i++) fact[i] = i * fact[i - 1] % mod;

    ll Q;
    cin >> Q;
    while(Q--) {
        ll b, a, n;
        cin >> b >> a >> n;
        ll b_div_a = b * __pow(a, mod - 2) % mod;
        ll val = (n + b_div_a - 1) % mod;
        ll n_mod = n % mod;
        if(n / mod >= 1) {
            cout << 0 << endl;
            continue;
        }
        if(val - n_mod > 0) {
            ll ans = fact[val] * __pow(fact[val - n_mod], mod - 2);
            (ans *= __pow(fact[mod - 1], n / mod)) %= mod;
            (ans *= __pow(a, n)) %= mod;
            cout << ans << endl;
        } else {
            cout << 0 << endl;
        }
    }
    return 0;
}

