  int R = ( x * inv( d ) + ( n - 1 ) ) % mod;
  int L = ( x * inv( d ) - 1 + mod ) % mod;

  int l = ( R - ( n - 1 ) - 1 );
  if( l <= 0 ) return 0;

  return ( ( X[R] * invX[L] ) % mod * mod_pow( d, n ) ) % mod;
}

