int pw(int a, int p){
	int an = 1;
	while (p){
		if (p & 1)an = (ll)an * a % md;
		a = (ll)a * a % md;
		p >>= 1;
	}
	return an;
}

int go(int d, int n) { return (ll)fc[n] * pw(d, n) % md; }

int solve(){
	int x, d, n;
	scanf("%d%d%d", &x, &d, &n);
