	int ed = (x + (ll)d * (n - 1)) % md;
	if (ed == 0)return 0;
	int i = (ll)ed * pw(d, md - 2) % md;
	if (i < n)return 0;
	int an = (ll)go(d, i) * pw(go(d, i - n), md - 2) % md;
	return an;
}

