//------------------------------------------------------- 
struct Fact{
	vector<long> f;
	vector<long> rf;
	long pow(long N,long K){
		if(K == 0){
			return 1;
		}
		else if(K % 2 == 0){
			long t = pow(N,K/2);
			return t*t%mod;
		}
		else{
			return N*pow(N,K-1)%mod;
		}
	}
	Fact(int N):f(N+1),rf(N+1){
		for(int i=0;i<N+1;i++){
			if(i == 0){
				f[i] = 1;
			}
			else{
				f[i] = (f[i-1]*i)%mod;
			}
		}
		for(int i=N;i>=0;i--){
			if(i == N){
				rf[i] = pow(f[N],mod-2);
			}
			else{
				rf[i] = rf[i+1]*(i+1)%mod;
			}
		}
	}
	long GetFact(int N){
		return f[N];
	}
	long GetRFact(int N){
		return rf[N];
	}
	long GetPerm(int N,int R){
		return f[N] * rf[N-R] % mod;
	}
	long GetConv(int N,int R){
		return ((f[N]*rf[R])%mod*rf[N-R])%mod;
	}
	long GetRev(int N){
		if(N == 0){
			return 1;
		}
		else{
			return rf[N] * f[N-1] % mod;
		}
	}
};
pair<long,long> ExGcd(long a_,long b_){
	long a = a_;
	long b = b_;
	long a1 = 1;
	long a2 = 0;
	long b1 = 0;
	long b2 = 1;
	while(b){
		long c = a % b;
		long c1 = a1 - a / b * b1;
		long c2 = a2 - a / b * b2;
		if(c1 > 0){
			c2 += (c1 / b_) * a_;
			c1 = c1 % b_;
		}
		if(c2 > 0){
			c1 += (c2 / a_) * b_;
			c2 = c2 % a_;
		}
		a = b;
		b = c;
		a1 = b1;
		b1 = c1;
		a2 = b2;
		b2 = c2;
	}
	return {a1,a2};
}
long Pow(long a,long r){
	if(r == 0){
		return 1;
	}
	if(r % 2 == 0){
		long t = a * a % mod;
		return Pow(t,r/2);
	}
	return Pow(a,r-1) * a % mod;
}
void Calc(){
	int Q = rei();
	Fact F(1000002);
	for(int i=0;i<Q;i++){
		int x = rei();
		int d = rei();
		int n = rei();
		if(d == 0){
			cout << Pow(x,n) << "\n";
			continue;
		}
		if(n >= mod){
			cout << 0 << "\n";
			continue;
		}
		pair<long,long> g = ExGcd(d,mod);
		long r = (g.second+d)*x%d;
		r = (d-r)%d;
		long a = x + r*mod;
		a /= d;
		a %= mod;
		long b = a+n-1;
		if(b >= mod){
			cout << 0 << "\n";
			continue;
		}
		long ans = F.GetFact(b) * (a == 0 ? 1 : F.GetRFact(a-1)) % mod;
		ans *= Pow(d,n);
		ans %= mod;
		cout << ans << "\n";
	}

}
