constexpr int M = 1000003;

long long modexp(int x, long long e, int m) {
    long long ans = 1, p = x % m;
    while (e > 0) {
        if (e % 2 != 0) ans = (ans * p) % m;
        p = (p * p) % m;
        e >>= 1;
    }
    return ans;
}

int modinv(int a, int m) {
    int x = m, y = a, p = 1, q = 0, r = 0, s = 1;
    while (y != 0) {
        int u = x / y;
        int x0 = y; y = x - y * u; x = x0;
        int r0 = p - r * u, s0 = q - s * u;
        p = r; r = r0; q = s; s = s0;
    }
    return q < 0 ? q + m : q;
}

int main() {
    int q; cin >> q;
    int fact[M] = {};
    fact[0] = 1;
    for (int i = 1; i < M; i++) fact[i] = (long long)fact[i-1] * i % M;
    while (q--) {
        int x, d, n; cin >> x >> d >> n;
        if (d == 0) {
            cout << modexp(x, n, M) << endl;
        } else if (x == 0) {
            cout << "0\n";
        } else {
            int k = (long long)x * modinv(d, M) % M;
            if (k + n - 1 >= M) cout << 0 << endl;
            else
                cout << modexp(d, n, M) * fact[k+n-1] % M * modinv(fact[k-1], M) % M << endl;
        }
    }
}

