ll fac[MOD], inv_fac[MOD];

ll bp(ll a, ll p) {
    ll r = 1;
    while (p > 0) {
        if (p & 1)
            r = r * a % MOD;
        a = a * a % MOD;
        p >>= 1;
    }
    return r;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    fac[0] = inv_fac[0] = 1;

    for (int i = 1; i < MOD; i++) {
        fac[i] = fac[i - 1] * i % MOD;
        inv_fac[i] = bp(fac[i], MOD - 2);
    }

    int q;
    cin >> q;

    for (int i = 0; i < q; i++) {
        int x, d, n;
        cin >> x >> d >> n;

        if (d == 0) {
