            if (x == 0 || MOD <= x + n - 1) {
                cout << "0\n";
            }
            else {
                cout << fac[x + n - 1] * inv_fac[x - 1] % MOD * bp(d, n) % MOD << "\n";
            }
        }
    }

    return 0;
}

