ll pow(ll a, ll b) {
	ll ans = 1;
	while (b > 0) {
		if (b % 2 == 1) {
			ans *= a;
			ans %= MOD;
		}
		b /= 2;
		a *= a;
		a %= MOD;
	}
	return ans;
}

ll frac(ll n) {
	static VL memo(MOD + 1, 1);
	static ll now = 2;
	if (n >= MOD) { return 0; }
	if (n < now) { return memo[n]; }

	FOR(i, now, n + 1) {
		memo[i] = (memo[i - 1] * i) % MOD;
	}
	now = n + 1;
	return memo[n];
}

signed main() {
	ll q;
	cin >> q;
	REP(_, q) {
		ll x, d, n;
		cin >> x >> d >> n;

		ll ans = pow(d, n);

		ll d_p = pow(d, MOD - 2);
		ll t = (x * d_p) % MOD;

		ans *= frac(t + n - 1);
		ans %= MOD;

		ll tt_p = pow(frac(t - 1), MOD - 2);
		ans *= tt_p;
		ans %= MOD;

		cout << ans << endl;
	}
}

