long long factorial(long long i){ // 階乗
  if(i > 0)
    return i * factorial(i-1);
  else
    return 1;
}

// a^n mod
long long modpow(long long a, long long n, long long mod) {
  long long res = 1;
  while (n>0) {
    if(n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

// a^(-1) mod
long long modinv(long long a, long long mod) {
  return modpow(a, mod-2, mod);
}

int main() {
  long long Q;
  const long long mod = 1000003;

  cin >> Q;

  // あらかじめ必要な階乗(mod)を計算しておく
  vector<long long> factmod;
  factmod.push_back(1); // 0! = 1
  long long tmp = 1;
  for(int i=1; i<2*mod+10; i++) { // 1000003!(mod 1,000,003) まで計算しておく ちょっと多めに
    tmp = (tmp*i)%mod;
    factmod.push_back(tmp);
  }

  long long ans = 1;
  rep(i, Q) {
    long long x, d, n;
    cin >> x >> d >> n;

    if(d!=0) {
      // 求める積は d^n * (x/d) * (x/d + 1) * ... * (x/d + (n-1))
      // つまり d^n * (x/d + (n-1))! / (x/d - 1)!
      long long xbyd = x * modinv(d, mod) %mod; // x/d (mod)
      if(xbyd+n-1 > mod) {
        // x/d+n-1 が modより大きい時 (x/d + (n-1))! がゼロになる．
        ans = 0;
      } else {
		if(xbyd==0) xbyd += mod; // xbyd-1 が負になるのを防ぐ
        ans = modpow(d, n, mod) * factmod[xbyd+n-1] %mod * modinv(factmod[(xbyd-1)%mod], mod) %mod;
      }
    } else { // d = 0
      // 求める積は x^n
      ans = modpow(x, n, mod);
    }

    if(ans<0) ans += mod;
    cout << ans << endl;
  }
}

#include<iostream>
#include<cstdio>
using namespace std;
const int MOD=1000003;
int Q;
long long ksm(long long a,long long b)
{
	long long res=1;
	while(b)
	{
		if(b&1) res=res*a%MOD;
		a=a*a%MOD,b>>=1;
	}
	return res;
}
long long fac[MOD],inv[MOD];
void init(int n=1000002)
{
	fac[0]=1;
	for(int i=1;i<=n;i++)
		fac[i]=fac[i-1]*i%MOD;
	inv[n]=ksm(fac[n],MOD-2);
	for(int i=n;i>=1;i--)
		inv[i-1]=inv[i]*i%MOD;
	return;
}
void solve()
{
	int x,d,n;
	scanf("%d%d%d",&x,&d,&n);
	if(d==0)
	{
		printf("%lld\n",ksm(x,n));
		return;
	}
	x=x*ksm(d,MOD-2)%MOD;
	if(x==0||x+n-1>=MOD)
	{
		printf("0");
		return;
	}
	long long ans=fac[x+n-1]*inv[x-1]%MOD;
	printf("%lld\n",ans*ksm(d,n)%MOD);
	return;
}
int main()
{
	init();
	scanf("%d",&Q);
	while(Q--)
		solve();
	return 0;
}

