}

inline ll fastpow(ll bas, ll ex){
	register ll res = 1; bas %= MOD;
	for(; ex; ex >>= 1, bas = bas * bas % MOD) if(ex & 1) res = res * bas % MOD;
	return res;
}

int Q, fac[1000005] = {1, 1}, ifac[1000005] = {1, 1}, inv[1000005] = {1, 1};

int main(){
	getint(Q);
	for(register int i = 2; i < MOD; i++){
		fac[i] = fac[i - 1] * (ll)i % MOD;
		inv[i] = (MOD - MOD / i) * (ll)inv[MOD % i] % MOD;
		ifac[i] = ifac[i - 1] * (ll)inv[i] % MOD;
	}
	while(Q--){
		int x, d, n; getint(x), getint(d), getint(n);
		if(d == 0) printf("%lld\n", fastpow(x, n));
		else{
			x = x * (ll)inv[d] % MOD;
			if(x == 0 || x + n - 1 >= MOD) puts("0");
			else printf("%lld\n", fac[x + n - 1] * (ll)ifac[x - 1] % MOD * fastpow(d, n) % MOD);
		}
	}
