long long mypow(long long x,long long n,long long m){
	if(n==0) return 1;
	if(n%2==0) return mypow((x*x)%m,n/2,m);
	else return (x*mypow(x,n-1,m))%m;
} 

long long gcd(long long x,long long y){
	while(1){
		if(x<y) swap(x,y);
		if(x%y==0) break;
		x=x%y;
	}
	return y;
}

