	COMinit();
	cin >> q;
	for(i=1;i<=q;i++){
		cin >> x >> d >> n;
		g=gcd(x,d);
		x=x/g;
		d=d/g;
		con=((MOD-x)*inv[d])%MOD;
		if((n-1)>=con){
			cout << "0" << endl;
			continue;
		}
		con=(x*inv[d])%MOD;
		ans=(((fac[con+n-1]*inv[fac[con-1]])%MOD)*mypow(d,n,MOD))%MOD;
		ans=(ans*mypow(g,n,MOD))%MOD;
		cout << ans << endl;
	}
	return 0;
}

