#define MOD 1000000007
#define MAX 1000003
long long fac[MAX], finv[MAX], inv[MAX];
void COMinit(ll mod)
{
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++)
    {
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod % i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}
ll modpow(ll a, ll n, ll mod)
{
    ll res = 1;
    while (n > 0)
    {
        if (n & 1)
            res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}
int main()
{
    int q;
    cin >> q;
    COMinit(MAX);
    for (int i = 0; i < q; i++)
    {
        ll x, d, n;
        cin >> x >> d >> n;
        ll init = x * inv[d];
        init %= MAX;
        if(d==0){
            cout<<modpow(x,n,MAX)<<endl;
            continue;
        }
        if (init + n - 1 >= MAX||init==0)
        {
            cout << 0 << endl;
        }
        else
        {
            ll tmp = fac[init + n - 1] * finv[init - 1];
            tmp %= MAX;
            tmp *= modpow(d, n, MAX);
            tmp %= MAX;
            cout << tmp << endl;
        }
    }
}

