const int MOD = (int)1e6 + 3;

const int N = MOD;
ll fact[N];
ll inv_fact[N];

ll modPow(ll a, ll b) {
	if (b & 1) return a * modPow(a, b-1) % MOD;
	if (b == 0) return 1;
	return modPow(a*a % MOD, b / 2);
}

ll intProd(int a, int b) {
	if (a <= 0 || b >= MOD) return 0;
	return fact[b] * inv_fact[a-1] % MOD;
}

int main() {
	ios_base::sync_with_stdio(false);
