		invfact[i] = invfact[i - 1] * inv[i];
	}
}

template<class T>
T fastpow(T a, long long p){
	T tmp = a;
	T ret = 1;
	while(p){
		if(p & 1)ret *= tmp;
		p >>= 1;
		tmp = tmp * tmp;
	}
	return ret;
}

int main()
{
	int q;
	scanf("%d", &q);
	facinit();
	for(int i=0; i < q; i++){
		mint x,d,n;
		cin >> x >> d >> n;
		if(x.v == 0){
			cout << 0 << "\n";
			continue;
		}
		if(d.v == 0){
			cout << fastpow(x, n.v).v << "\n";
			continue;
		}
		mint s = x/d;
		if(s.v + n.v - 1>= MOD){
			cout << 0 << "\n";
			continue;
		}
		cout << (fastpow(d, n.v) * fact[s.v + n.v - 1] * invfact[s.v-1]).v << "\n";
	}
	return 0;
}

