using mint = ModInt<MOD>;

Combination<MOD> C(MOD - 1);

int main() {
    int Q;
    cin >> Q;
    for (int i = 0; i < Q; ++i) {
        int ix, id, in;
        cin >> ix >> id >> in;
        if (ix == 0 || in >= MOD) {
            cout << 0 << endl;
            continue;
        }

        mint x = mint(ix), d = mint(id), n = mint(in);
        if (id == 0) {
            cout << (x ^ n) << endl;
            continue;
        }

        mint k = x / d;
        if (k.val + n.val - 1 >= MOD) {
            cout << 0 << endl;
            continue;
        }

        cout << C.fact(k.val + n.val - 1) / C.fact(k.val - 1) * (d ^ n) << endl;
    }
    return 0;
}

