const i64 mod = 1000003;
i64 q;
i64 ipow(i64 a, i64 b) {
  return (b & 1 ? a : 1) * (b > 1 ? ipow(a * a % mod, b >> 1) : 1) % mod;
}

i64 inv(i64 x) {
  return ipow(x, mod - 2);
}

i64 fact_memo[1000007];
i64 fact(i64 x) {
  if (x > mod) return 0;
  if (fact_memo[x] > 0) return fact_memo[x];
  return fact_memo[x] = x > 0 ? x * fact(x - 1) % mod : 1;
}

