long long int mypow(long long int base, long long int times) {
	if (times == 1)
		return base;
	if (times == 0)
		return 1;
	long long int t = mypow(base, times / 2);
	if (times % 2 == 0)
		return t * t % mod;
	else
		return t * t * base % mod;
}

