long kaijo(long num) {
	long ans = 1;
	for (int i = 1; i <= num; i++) {
		ans *= i;
	}
	return ans;
}

int judge(long x, long n) {
	int flag = 0;
	for (int i = x; i < x + n - 1; i++) {
		if (i % 1000003 == 0) {
			flag = 1;
			break;
		}
	}
	return flag;
}

int main(void) {
	long q;
	cin >> q;
	vector<long> ans(q);

	for (int i = 0; i < q; i++) {
		long long x, d, n;
		cin >> x >> d >> n;

		if (d == 1) {
			int F = judge(x, n);
			if (F == 1) {
				ans[i] = 0;
			}
			else {
				ans[i] = kaijo(x + n - 1) / kaijo(x - 1);
			}
		}
		else if (d == 0) {
			ans[i] = pow(x, n);
		}
		else {
			long M = kaijo(d / x + n - 1) / kaijo(d / x - 1);
			ans[i] = M * pow(d, n);
		}
	}

	for (int i = 0; i < q; i++) {
		cout << ans[i] << " " << flush;
	}
	cout << endl;
	return 0;
}

