ll mpow(ll x, ll n){ //x^n(mod division) ←普通にpow(x,n)では溢れてしまうため，随時mod計算
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % mod;
        x = x*x % mod;
        n = n >> 1;
    }
    return ans;
}

ll inv_mod(ll a){return mpow(a,mod-2);}

class Fuctorical{
private:
    vector<ll> fac;
public:

    Fuctorical(ll N){
        fac.push_back(1);
        for(int i=0;i<N;i++) fac.push_back(fac[i]*(i+1)%mod);
    }

    ll fact(ll a){return fac[a];}
    ll ifact(ll a){return inv_mod(fac[a]);}

    ll cmb(ll a,ll b){
        if(a==0&&b==0) return 1;
        if(a<b||a<0) return 0;
        ll tmp =ifact(a-b)*ifact(b)%mod;
        return tmp*fac[a]%mod;
    }
};

int gcd(int x,int y){return y ? gcd(y,x%y) : x;};//xとyの最大公約数

int main(){
    Fuctorical get(mod);
    int Q;
    cin>>Q;
    for(int i=0;i<Q;i++){
        ll x,d,n;
        cin>>x>>d>>n;
        ll first =x*inv_mod(d)%mod;
        ll a=get.fact(first+n-1)*get.ifact(first-1)%mod;
        cout<<a*mpow(d,n)%mod<<endl;
    }
}

