// a^b O(log b)
template <typename T>
T mypow(T a, T b)
{
    if (b == 0)
        return 1;
    T tmp = mypow(a, b / 2);
    if (b % 2)
        return (((tmp * tmp) % MOD) * a) % MOD;
    else
        return (tmp * tmp) % MOD;
}

struct RangeProductQuery
{
    using type = ll;
    static type id() { return 1; }
    static type op(const type &l, const type &r) { return l * r % MOD; }
};

template <typename M>
class DisjointSparseTable
{
    using T = typename M::type;
    std::vector<std::vector<T>> memo;

public:
    DisjointSparseTable(const std::vector<T> &v)
    {
        int b = 0;
        while ((1 << b) <= static_cast<int>(v.size()))
            b++;
        memo.resize(b, std::vector<T>(static_cast<int>(v.size()), M::id()));
        for (int i = 0; i < static_cast<int>(v.size()); i++)
            memo[0][i] = v[i];
        for (int i = 1; i < b; i++)
        {
            int st = 1 << i;
            for (int j = 0; j < static_cast<int>(v.size()); j += st << 1)
            {
                int t = std::min(j + st, static_cast<int>(v.size()));
                memo[i][t - 1] = v[t - 1];
                for (int k = t - 2; k >= j; k--)
                    memo[i][k] = M::op(v[k], memo[i][k + 1]);
                if (static_cast<int>(v.size()) <= t)
                    break;
                memo[i][t] = v[t];
                int r = min(t + st, static_cast<int>(v.size()));
                for (int k = t + 1; k < r; k++)
                    memo[i][k] = M::op(memo[i][k - 1], v[k]);
            }
        }
    }

    // [a, b) の op 結果
    T query(int l, int r)
    {
        if (l >= --r)
            return memo[0][l];
        int b = 31 - __builtin_clz(l ^ r);
        return M::op(memo[b][l], memo[b][r]);
    }
};

template <typename M>
class SegmentTree
{
    using T = typename M::type;
    int n;
    std::vector<T> node;

  public:
    // v を基に初期化
    SegmentTree(const std::vector<T> &v)
    {
        // n は v.size() 以上の最小の2冪
        n = 1;
        while (n < int(v.size()))
            n *= 2;
        node.resize(2 * n, M::id());

        // i の子 -> 2*i+1, 2*i+2 , 親 -> (i-1)/2
        for (int i = 0; i < int(v.size()); i++)
            node[i + n] = v[i];
        for (int i = n - 1; i >= 0; i--)
            node[i] = M::op(node[2 * i], node[2 * i + 1]);
    }
    // Monoid::id 初期化
    SegmentTree(int _n)
    {
        // n は v.size() 以上の最小の2冪
        n = 1;
        while (n < _n)
            n *= 2;
        node.resize(2 * n, M::id());
    }
    // x 番目を val に更新
    void update(int x, T val)
    {
        x += n;
        node[x] = val;
        while (x >>= 1)
        {
            node[x] = M::op(node[2 * x], node[2 * x + 1]);
        }
    }
    // v[x] を M::op(v[x], val) に更新
    void operation(int x, T val)
    {
        x += n;
        node[x] = M::op(node[x], val);
        while (x >>= 1)
        {
            node[x] = M::op(node[2 * x], node[2 * x + 1]);
        }
    }
    // [a, b) の op
    T query(int l, int r)
    {
        l += n;
        r += n;
        T retl = M::id(), retr = M::id();
        while (l < r)
        {
            if (l & 1)
                retl = M::op(retl, node[l++]);
            if (r & 1)
                retr = M::op(node[--r], retr);
            l >>= 1;
            r >>= 1;
        }
        return M::op(retl, retr);
    }
};

