constexpr ll MOD = (ll)((1E+6)+3);

class Modulo{
  private:
    ll MAX = MOD;
    vll fac_v, finv_v, inv_v;
  public:

    void Modulo_setting(ll MAX_){
      MAX = MAX_;

      fac_v.resize(MAX);
      finv_v.resize(MAX);
      inv_v.resize(MAX);

      fac_v[0] = fac_v[1] = 1;
      finv_v[0] = finv_v[1] = 1;
      inv_v[1] = 1;
      for(int i=2; i<MAX; ++i){
        //i!
        fac_v[i] = (fac_v[i-1]*i)%MOD;
        //i^{-1}
        inv_v[i] = MOD-(inv_v[MOD%i]*(MOD/i))%MOD;
        //(i!)^{-1}
        finv_v[i] = (finv_v[i-1]*inv_v[i])%MOD;
      }
    };

    Modulo(ll MAX_){
      Modulo_setting(MAX_);
      return;
    };

    Modulo(void){
      Modulo_setting(MOD);
      return;
    };

    ~Modulo(void){
      return;
    };

    ll inv(ll n){
      if(n<0) return 0;
      if(n%MOD>=MAX) return 0;
      return inv_v[n%MOD];
    };

    ll fac(ll n){
      if(n<0) return 0;
      if(n%MOD>=MAX) return 0;
      return fac_v[n];
    };

    ll inv_fac(ll n){
      if(n<0) return 0;
      if(n%MOD>=MAX) return 0;
      return finv_v[n];
    };

    ll Comb(ll n, ll k){
      if(n<k) return 0;
      if(n<0 || k<0) return 0;
      return fac_v[n]*(finv_v[k]*finv_v[n-k]%MOD)%MOD;
    };
};

ll calc1(ll x, ll n){
  //x^n
  ll ans = 1;
  while(n>0){
    if(n%2==1){
      ans *= x;
      ans %= MOD;
    }
    n/=2;
    x *= x;
    x %= MOD;
  }
  return ans%MOD;
}

