LL data[MAX+2];

long long int pow_mod(long long int p_a,long long int p_n,long long int p_p=MAX){
	//p_a^p_n mod p_p
	long long int p_b=1,p_t=1;
	for(;p_b<=p_n;p_b<<=1);
	for(p_b>>=1;p_b>0;p_b>>=1){
		p_t*=p_t;
		if(p_t>=p_p)p_t%=p_p;
		if(p_n&p_b)p_t*=p_a;
		if(p_t>=p_p)p_t%=p_p;
	}
	return p_t;
}

LL divi(LL a,LL b){//a/b
	LL s=a*pow_mod(b,MAX-2)%MAX;
	return s;
}

LL calc(LL a,LL b){//aCb
	a--;
	b+=a;
	if(b>=MAX || a<0)return 0;
	return divi(data[b],data[a]);
}

