template <int mod>
struct ModInt {
    int x;

    ModInt() : x(0) {}

    ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

    ModInt &operator+=(const ModInt &p) {
        if((x += p.x) >= mod) x -= mod;
        return *this;
    }

    ModInt &operator-=(const ModInt &p) {
        if((x += mod - p.x) >= mod) x -= mod;
        return *this;
    }

    ModInt &operator*=(const ModInt &p) {
        x = (int) (1LL * x * p.x % mod);
        return *this;
    }

    ModInt &operator/=(const ModInt &p) {
        *this *= p.inverse();
        return *this;
    }

    ModInt &operator++() {
        if((++x) >= mod) x -= mod;
        return *this;
    }

    ModInt operator++(int) {
        ModInt tmp(*this);
        operator++();
        return tmp;
    }

    ModInt &operator--() {
        if((x += mod - 1) >= mod) x -= mod;
        return *this;
    }

    ModInt operator--(int) {
        ModInt tmp(*this);
        operator--();
        return tmp;
    }

    ModInt operator-() const { return ModInt(-x); }

    ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

    ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

    ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

    ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

    bool operator==(const ModInt &p) const { return x == p.x; }

    bool operator!=(const ModInt &p) const { return x != p.x; }

    ModInt inverse() const {
        int a = x, b = mod, u = 1, v = 0, t;
        while (b > 0) {
            t = a / b;
            swap(a -= t * b, b);
            swap(u -= t * v, v);
        }
        return ModInt(u);
    }

    ModInt pow(int64_t n) const {
        ModInt res(1), mul(x);
        while (n > 0) {
            if(n & 1) res *= mul;
            mul *= mul;
            n >>= 1;
        }
        return res;
    }

    friend ostream &operator<<(ostream &os, const ModInt &p) {
        return os << p.x;
    }

    friend istream &operator>>(istream &is, ModInt &a) {
        int64_t t;
        is >> t;
        a = ModInt< mod >(t);
        return (is);
    }

    static int get_mod() { return mod; }
};
using Mint = ModInt<Mod>;

vector<Mint> fac, finv;

void init_combi(){
    if (!fac.empty()) return;
    const int sz = Mod - 1;
    fac.resize(sz + 1);
    fac[0] = 1;
    for (int i = 1; i <= sz; ++i) fac[i] = fac[i - 1] * i;
    finv.resize(sz + 1);
    finv[sz] = fac[sz].inverse();
    for (int i = sz - 1; i >= 0; --i) finv[i] = finv[i + 1] * (i + 1);
}

Mint combi(ll n, ll k){
    init_combi();
    return fac[n] * finv[k] * finv[n - k];
}

int main(void) {
    init_combi();
    ll q;
    cin >> q;
    while(q--){
        ll x, d, n;
        cin >> x >> d >> n;
        Mint a = x;
        if(d == 0){
            co(a * n);
            continue;
        }
        a /= d;
        x = a.x;
        if (x == 0 || Mod - x <= n) co(0);
        else
            co(fac[x + n - 1] * finv[x - 1] * Mint(d).pow(n));
    }

    return 0;
}

