ll power(ll x,ll k){
  ll ret=1;
  while(k>0){
    if(k&1) (ret*=x) %= M;
    (x*=x) %= M;
    k >>= 1;
  }
  return ret;
}

int fact[M+10];
int ifact[M+10];

main(){
  fact[0]=1;
  FOR(i,1,M+1){
    fact[i]=fact[i-1]*i;
    fact[i]%=M;
    ifact[i]=power(fact[i],M-2);
  }

  int q;
  cin>>q;
  while(q--){
    int x,d,n;
    cin>>x>>d>>n;
    if(d==0){
      cout<<power(x,n)<<endl;
