ll modpow(ll x, ll n) {
    if(n==0){
        return 1;
    }else if(n%2==0){
        ll h = modpow(x,n/2);
        return h * h % MOD;
    } else {
        return x * modpow(x,n-1) % MOD;
    }
}

int main() {
  int Q; cin >> Q;
  ll x, d, n;
  vector<ll> X, D, N;
  rep(i,Q){
    cin >> x >> d >> n;
    X.push_back(x);
    D.push_back(d);
    N.push_back(n);
  }
  vector<ll> kaijo;
  kaijo.push_back(1);
  reps(i,MOD){
    kaijo.push_back((kaijo[i-1]*i)% MOD);
  }

  rep(i,Q){
    x = X[i]; d = D[i]; n = N[i];
    if(d==0){
      cout << modpow(x,n) << endl;
    }else{
      ll a = (x * modpow(d,MOD-2))%MOD;
      ll b = (x * modpow(d,MOD-2) + n - 1)%MOD;
      if((a >= b)||(a == 0)){
        cout << 0 << endl;
      }else{
        cout << (((kaijo[b] * modpow(kaijo[a-1],MOD-2)) % MOD) * modpow(d,n)) % MOD << endl;
      }
    }
  }
  return 0;
}

