    // setError("err.txt");
    FACT[0] = 1;
    For(i, 1, MOD) FACT[i] = mulMod(FACT[i - 1], ll(i), MOD);
    INV[MOD - 1] = mulInvPrime(FACT[MOD - 1], MOD);
    REV(i, MOD - 2) INV[i] = mulMod(INV[i + 1], ll(i + 1), MOD);
    read(Q);
    FOR(i, Q) {
        ll x, d, n;
        read(x, d, n);
        if (x == 0) writeln(0);
        else if (d == 0) writeln(powMod(x, n, MOD));
        else {
            x = divModPrime(x, d, MOD);
            if (x + n - 1 >= MOD) writeln(0);
            else writeln(mulMod(mulMod(FACT[x + n - 1], INV[x - 1], MOD), powMod(d, n, MOD), MOD));
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define mod 1000003
inline int quickpow(int base,int ind)
{
	base%=mod;
	int ans=1;
	while(ind>0)
	{
		if(ind&1)ans=ans*1ll*base%mod;
		ind>>=1;
		base=base*1ll*base%mod;
	}
	return ans;
}
inline int inv(int x)
{
	return quickpow(x,mod-2);
}
const int maxn=1e6+500;
const int N=1000002;
int fact[maxn*2],invfac[maxn];
inline int calc(int a,int b,int c)
{
//	cout<<13*1ll*inv(b)%mod<<endl;
	int iv=inv(b);
	int fst=a*1ll*iv%mod;
	if(fst==0)return 0;
	fst--;
	int lst=(a+(c-1)*1ll*b%mod)%mod*1ll*iv%mod;
//	cout<<iv<<" "<<fst<<" "<<lst<<endl;
//	cout<<fact[lst]<<" "<<invfac[fst]<<" "<<quickpow(b,c)<<endl;
	return fact[lst]*1ll*invfac[fst]%mod*1ll*quickpow(b,c)%mod;
}
int main()
{
//	cout<<93*1ll*inv(16)%mod<<endl;
	int Q,x,n,d;
	scanf("%d",&Q);
//	cout<<C<<endl;
	fact[0]=1;
	for(int i=1;i<=N;i++)
	{
		fact[i]=fact[i-1]*1ll*i%mod;
	}
	invfac[N]=inv(fact[N]);
	for(int i=N-1;i>=0;i--)
		invfac[i]=invfac[i+1]*1ll*(i+1)%mod;
	while(Q--)
	{
		scanf("%d%d%d",&x,&d,&n);
		if(d==0)
		{
			printf("%d\n",quickpow(x,n));
			continue;
		}
		if(n>=mod)
		{
			printf("0\n");
			continue;
		}
		printf("%d\n",calc(x,d,n));
	}
	return 0;
}

