const int mod=1000003;
const int pl[8]={0, 6, 9, 14, 16, 17, 18, 19};

int pow1000001(int n){
  long pow2[25];
  pow2[0]=n;
  for(int i=1; i<25; i++)pow2[i]=(pow2[i-1]*pow2[i-1])%mod;
  long ret=1;
  for(int i=0; i<8; i++){
    ret*=pow2[pl[i]];
    ret%=mod;
  }
  return ret;
}

long pow(int d, int n){
  long pow2[35];
  pow2[0]=d;
  for(int i=1; i<35; i++)pow2[i]=(pow2[i-1]*pow2[i-1])%mod;
  vector<int>bn;
  while(n>0){
    bn.push_back(n%2);
    n/=2;
  }
  long ret=1;
  for(int i=0; i<bn.size(); i++){
    if(bn[i]){
      ret*=pow2[i];
      ret%=mod;
    }
  }
  return ret;
}

int main(){
  vector<long>inv(mod, -1);
  for(int i=1; i<mod; i++)inv[i]=pow1000001(i);
  vector<long>fact(3*mod, 1);
  for(int i=1; i<3*mod; i++)fact[i]=(fact[i-1]*i)%mod;
  int q;
  cin >> q;
  for(int t=0; t<q; t++){
    long x, d, n;
    cin >> x >> d >> n;
    if(n>=1000003){
      cout << 0 << endl;
      break;
    }
    int m=(x*inv[d])%mod;
    cout << (pow(d, n)*((fact[m+n-1]*inv[fact[m-1]])%mod))%mod << endl;
  }
  return 0;
}

