const int MAX = 3000003;
const int mod = 1000003;

long long fac[MAX]; //i!%mod=fac[i]
long long finv[MAX]; //pow(i!,-1)%mod=finv[i]
long long inv[MAX]; //pow(i,-1)%mod=inv[i]

// テーブルを作る前処理
void cominit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}

long long modpow(long long a,long long b)
{
	if (b==0LL)
	{
		return 1LL;
	}
	long long ans=modpow(a,b/2LL);
	ans*=ans;
	ans%=mod;
	if (b%2LL==1LL)
	{
		ans*=a;
		ans%=mod;
	}
	return ans;
}

int main(int argc, char const *argv[])
{
	cominit();
	int q;
	cin>>q;
	long long x[q],d[q],n[q];
	for (int i = 0; i < q; ++i)
	{
		cin>>x[i]>>d[i]>>n[i];
	}
	for (int i = 0; i < q; ++i)
	{
		if (d[i]==0)
		{
			cout<<modpow(x[i],n[i])<<endl;
			continue;
		}
		if (n[i]>=mod)
		{
			cout<<"0\n";
			continue;
		}
		long long ans=fac[(x[i]*inv[d[i]]+n[i]-1)%mod]*finv[(x[i]*inv[d[i]]-1)%mod]%mod;
		ans*=modpow(d[i],n[i]);
		ans%=mod;
		cout<<ans<<endl;
	}
	return 0;
}

