using namespace std;

struct mint{
    static const long long MOD = 1000003;

    long long v;

    mint() : v(0) {}
    mint(long long x){
        x = x % MOD;
        if(x < 0){ x += MOD; }
        v = x;
    }
    mint& operator+=(mint a){
        v += a.v;
        if(v >= MOD){ v -= MOD; }
        return *this;
    }
    mint& operator*=(mint a){
        v *= a.v;
        v %= MOD;
        return *this;
    }
    mint& operator/=(mint a){
        return (*this) *= a.inv();
    }

    mint operator*(mint a){
        return mint(v) *= a;
    }

    mint operator+(mint a){
        return mint(v) += a;
    }

    mint pow(long long k){
        mint res(1),tmp(v);
        while(k){
            if(k&1) res *= tmp;
            tmp *= tmp;
            k >>= 1;
        }
        return res;
    }
    mint inv(){return pow(MOD - 2); }

    static mint comb(long long n, int k){
        mint res(1);
        for(int i = 0; i < k; ++i){
            res *= mint(n - i);
            res /= mint(i + 1);
        }
        return res;
    }

    bool operator<(const mint &a) const {
        return v < a.v;
    };
};

mint solve(long long x, long long d, long long n){
    if(x == 0){ return 0; }
    if(d == 0){ return mint(x).pow(n); }
    if(n >= mint::MOD){ return 0; }
    mint ret(x);
    mint mx(x);
    mint md(d);
    for(long long i = 1; i <= (n - 1); ++i){
        ret *= mx + mint(i) * md;
        if(ret.v == 0){ return 0; }
    }
    return ret;
}

int main(){
    int q;
    cin >> q;
    for(int i = 0; i < q; ++i){
        long long x, d, n;
        cin >> x >> d >> n;
        printf("%lld\n", solve(x, d, n).v);
    }
    return 0;
}

