#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1e6+3;
ll getPow(ll a,ll p){
  ll ret = 1,cp = a;
  while(p){
    if(p&1) ret = (ret*cp)%MOD;
    p >>= 1;
    cp = (cp*cp)%MOD;
  }
  return ret;
}
ll getInverse(ll i){
  return getPow(i,MOD-2)%MOD;
}
int main(){
  ios::sync_with_stdio(0);
  cin.tie(0);
  ll idx,q,x,d,n;
  cin >> q;
  vector<tuple<ll,ll,ll,ll>> vt(q);
  for(ll i = 0; i < q; ++i){
    cin >> x >> d >> n;
    vt[i] = make_tuple(x,d,n,i);
  }
  sort(begin(vt),end(vt));
  vector<ll> ret(q);
  ll preX = -1, preD = -1, preN = -1, preNN = -1, preAns = -1;
  for(auto& p : vt){
    tie(x,d,n,idx) = p;
    if(d == 0) ret[idx] = getPow(x,n);
    else if(n > MOD) ret[idx] = 0;
    else if(preX == x and preD == d){
      if(n > preNN) ret[idx] = 0;
      else{
        ll xd = (x+(preN-1)*d)%MOD;
        ret[idx] = preAns;
        for(ll i = preN; i < n; ++i){
          xd += d;
          ret[idx] = (ret[idx]*xd)%MOD;
        }
      }
    }
    else{
      ll N = ((MOD-x)*getInverse(d))%MOD;
      preNN = N;
      if(n > N) ret[idx] = 0;
      else{
        ll xd = x;
        ret[idx] = x;
        for(ll i = 1; i < n; ++i){
          xd += d;
          ret[idx] = (ret[idx]*xd)%MOD;
        }
      }
    }
    preX = x;
    preD = d;
    preN = n;
    preAns = ret[idx];
  }
  for(ll i = 0; i < q; ++i) cout << ret[i] << '\n';
  return 0;
}

