constexpr long long int mod = 1000003;
long long int power(const long long int base, const int e) {
	if (e == 0) {
		return 1;
	}
	else if (e == 1) {
		return base;
	}
	else {
		auto r = power(base, e / 2);
		return (((r * r) % mod) * power(base, e % 2)) % mod;
	}
}
long long int inverse(const long long int base) {
	return power(base, static_cast<int>(mod) - 2);
}
int main() {
	std::vector<long long int> factorio(1000003, 1);
	for (auto i = 1; i < 1000003; ++i) {
		factorio[i] = (factorio[i - 1] * i) % mod;
	}
	int q; std::cin >> q;
	for (auto i = 0; i < q; ++i) {
		int x, d, n; std::cin >> x >> d >> n;
		if (n % mod == 0) {
			if ((n / mod) % 2 == 0) {
				std::cout << 1 << std::endl;
			}
			else {
				std::cout << mod - 1 << std::endl;
			}
		}
		auto odd = (n / mod) % 2 == 1;
		auto from = static_cast<int>((x * inverse(d)) % mod);
		auto to = static_cast<int>(((n % mod) + from - 1));
		long long int upper, lower;
		if (to > mod) {
			std::cout << 0 << std::endl;
		}
		else {
			upper = factorio[to];
			lower = 1;
			if (from > 0) {
				lower = inverse(factorio[from - 1]);
				auto r = ((upper * lower) % mod) * power(d, static_cast<int>(n % mod)) % mod;
				if (odd) {
					std::cout << (mod - r) << std::endl;
				}
				else {
					std::cout << r << std::endl;
				}
			}
			else {
				std::cout << 0 << std::endl;
			}
		}
	}
}

