mint solve(mint x,mint d,int n)
{
    if(d==0)
    {
        return x.pow(n);
    }
    x /= d;
    if(x.x+n - 1 >= mod)
    {
        return 0;
    }
    else if(x != 0)
    {
        return d.pow(n)*mint::factorial(x.x+n-1)/mint::factorial(x.x-1);
    }
    else return 0;

}
