typedef long long i64;
const int P=1e6+3;

int inv[2*P];

int pwr(int x,int a){
	int s=1;
	while(a){
		if(a&1)s=(i64)s*x%P;
		x=(i64)x*x%P;
		a>>=1;
	}
	return s;
}

int main()
{
	int T,i,n,d,x,y;
	scanf("%d",&T);
	inv[0]=1;
	for(i=1;i<P;i++)
		inv[i]=(i64)inv[i-1]*i%P;
	while(T--){
		scanf("%d%d%d",&x,&d,&n);
		if(d==0){
			printf("%d\n",pwr(d,n));
			continue;
		}
		y=(i64)x*pwr(d,P-2)%P;
		if(y+n>P){
			printf("0\n");
			continue;
		}
		printf("%d\n",(i64)inv[y+n-1]*pwr(inv[y-1],P-2)%P*pwr(d,n)%P);
	}
	return 0;
}

