const int mod = 1000003;
int A[1000100];

inline int ksm(int x, int p) {
	int ret = 1;
	while (p) {
		if (p & 1) ret = ret * 1ll * x % mod;
		p >>= 1; x = x * 1ll * x % mod;
	}
	return ret;
}

void work() {
	A[0] = 1;
	rep(i, 1, mod) A[i] = A[i - 1] * 1ll * i % mod;
	int tc = read();
	while (tc--) {
		int x = read(), d = read(), n = read();
