		int ans = ksm(d, n);
		if (x + n - 1 >= mod) {
			puts("0");
			continue;
		}
		ans = ans * 1ll * A[x + n - 1] % mod * ksm(A[x - 1], mod - 2) % mod;
		printf("%d\n", ans);
	}
}

