/* constant */

const int MOD = 1000003;
const int MAX_K = MOD * 2;

/* typedef */

typedef long long ll;

/* global variables */

int fracs[MAX_K + 1], invfs[MAX_K + 1];

/* subroutines */

ll powmod(ll a, int n) {  // a^n % MOD
  ll pm = 1;
  while (n > 0) {
    if (n & 1) pm = (pm * a) % MOD;
    a = (a * a) % MOD;
    n >>= 1;
  }
  return pm;
}

/* main */

int main() {
  fracs[0] = invfs[0] = 1;
  for (int i = 1; i <= MAX_K; i++) {
    fracs[i] = (ll)fracs[i - 1] * i % MOD;
    invfs[i] = powmod(fracs[i], MOD - 2);
  }

  int q;
  scanf("%d", &q);

  while (q--) {
    int x, d, n;
    scanf("%d%d%d", &x, &d, &n);

    int sum = 0;
    if (d == 0) sum = powmod(x, n);
    else {
      int y = (ll)x * powmod(d, MOD - 2) % MOD;
      sum = fracs[y + n - 1];
      if (y > 0) sum = (ll)sum * invfs[y - 1] % MOD;
      sum = (ll)sum * powmod(d, n) % MOD;
    }

    printf("%d\n", sum);
  }
  return 0;
}

