//!    88   88   88  88.  .88  88  88    88    !//
//!    dP   dP   dP  '88888P8  dP  dP    dP    !//
//!============================================!//
int main()
{
    constexpr uint MOD = 1000003;
    using mint = ModInt<MOD>;
    struct Monoid
    {
        using ValType = mint;
        ValType operator()(const ValType& a, const ValType& b) const { return a * b; }
        static ValType id() { return mint(1); }
    };
    std::vector<mint> v(2 * MOD);
    for (int i = 0; i < 2 * MOD; i++) { v[i] = i; }
    SegTree<Monoid> seg(v.begin(), v.end());
    const int Q = read<int>();
    for (int q = 0; q < Q; q++) {
        mint x, d;
