            continue;
        }

        auto k = (Mod(M - x) / d).n;

        if (k <= n - 1) {
            cout << 0 << endl;
            continue;
        }

        auto a = fact[n - 1 - k + M] / fact[-1 - k + M];

        a *= Mod(d).pow(n);

        cout << a.n << endl;
    }


}

