		modint<MOD> mx = x,md = d;
		if(!d) printf("%d\n",mx.pow(n));
		else if(n >= MOD) puts("0");
		else printf("%d\n",comb.fact[n] * comb.nCr(-mx / md,n) * (-md).pow(n));
	}
}

