Int mod_pow(Int x,Int y){
  Int res = 1;
  while(y){
    if(y % 2) res *= x, res %= mod;
    x = x * x % mod;
    y /= 2;
  }
  return res;
}

Int fac(Int n){
  static vector<Int> f;
  if(f.empty()){
    f.resize(2000000);
    f[0] = 1;
    for(Int i=1;i<(Int)f.size();i++) f[i] = f[i-1] * i % mod;
  }
  return f[n];
}

int inv(int x){return mod_pow(x, mod - 2);}

Int calc(Int x, Int d, Int n, int f = 0, int f2 = 0){
  if(x == 0) return 0;
  if(d == 0) return mint(x).pow(n).v;

  // pr(x, d, n);
  Int dn  = mod_pow(d, n) % mod;
  Int L = x * inv(d) % mod;
  Int R = (x * inv(d) + n - 1) % mod; //[L , R];
  Int l = fac(mint(L-1).v);
  Int r = fac(R);
  Int t = r * inv(l) % mod;
  if(L > R) return 0;
  if(f) pr(dn, L, R, l, r, t);
  if(f2) assert(L <= R);
  return dn * t % mod;
}
Int calc2(Int x,Int d,Int n){
  Int res = 1;
  for(Int i=0;i<n;i++) res *= (x + d * i) % mod, res %= mod;
  return res;
}

