ll fact[nMax], fact_inv[nMax], inv[nMax];
ll calcFact() {
    fact[0] = fact[1] = 1;
    fact_inv[0] = fact_inv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < nMax; i++) {
        fact[i] = fact[i-1] * i % MOD;
