constexpr int64_t mod{1'000'003};
Combination<mod> combi(mod);

int64_t pow(int64_t a, int64_t b)
{
	ModInt<mod> ret(1), tmp(a);
	while (b)
	{
		if (b & 1) ret *= tmp;
		tmp *= tmp;
		b >>= 1;
	}
	return (int64_t)ret;
}

int64_t solve()
{
	int64_t x, d, n;
	scanf("%lld%lld%lld", &x, &d, &n);
	if (x == 0) return 0ll;
	if (d == 0) return pow(x, n);
	ModInt<mod> xd_inv(ModInt<mod>(mod - x) / ModInt<mod>(d));
	if ((int64_t)xd_inv <= n - 1) return 0ll;
	// 0 < x < mod, d > 0, n-1 <-x/d < mod
	return ModInt<mod>(combi.getPerm(xd_inv, n)) * pow(mod - d, n);
}

