lint ipow(lint x, lint p){
	lint ret = 1, piv = x;
	while(p){
		if(p & 1) ret = ret * piv % mod;
		piv = piv * piv % mod;
		p >>= 1;
	}
	return ret % mod;
}

lint query(int s, int e){
	int zeroCnt = (e + mod) / mod - (s - 1 + mod) / mod;
	if(zeroCnt) return 0;
	s %= mod;
	e %= mod;
	return fact[e] * invf[s - 1] % mod;
}

