		int64_t x, d, n; cin >> x >> d >> n;

		if (d == 0) {
			cout << pow_rem(x, n, kRem) << endl;
			continue;
		}

		int64_t val = pow_rem(d, n, kRem);
		int64_t s = divide_rem(x, d, kRem);
		if (kRem <= s + n - 1) {
			cout << 0 << endl;
			continue;
		}

		val *= table[s + n - 1];
		val %= kRem;
		val = divide_rem(val, table[s - 1], kRem);

		cout << val << endl;
	}

	return 0;
}

