const int mod = 1e6 + 3;
ll fac[1100000];
ll rev_fac[1100000];

ll ksm(ll x, ll n) {
    ll res = 1;
    while (n) {
        if (n & 1) {
            res = res * x % mod;
        }
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

ll get_rev(ll x) {
    return ksm(x, mod - 2);
}

void init() {
    fac[0] = 1;
    for (int i = 1; i <= 1000010; ++i) {
        fac[i] = (fac[i - 1] * i) % mod;
    }
    rev_fac[1000002] = get_rev(fac[1000002]);
    for (int i = 1000001; i >= 0; --i) {
        rev_fac[i] = rev_fac[i + 1] * (i + 1) % mod;
    }
}

ll solve(ll x, ll d, ll n) {
    if (d == 0) {
        return ksm(x, n);
    }else {
        ll xd = (x * get_rev(d)) % mod;
        if (xd + (n - 1) >= mod) return 0;
        xd = (fac[xd + n - 1] * rev_fac[xd - 1]) % mod;
        ll rev = ksm(d, n);
        return (xd * rev) % mod;
    }
}

