ll ex_gcd(ll a,ll b,ll &x,ll&y){
    if(a==0 && b==0)return -1;
    if(b == 0){
        x = 1;y = 0;
        return a;
    }
    ll d = ex_gcd(b,a%b,y,x);
    y -= a/b*x;
    return d;
}
ll liEu(ll a,ll b, ll c, ll &x, ll &y){
    ll d = ex_gcd(a, b, x, y);
    if(c % d != 0)return 0;
    ll k = c / d;
    //cout<<".x:"<<x<<endl;
    //cout<<"k:"<<k<<endl;
    x *= k;
    y *= k;
    return 1;
}
