ll power(ll a, ll p){
    ll x = 1, n = p;
    while (n != 0){
        if (n % 2 == 1){
            x = (x * a) % MOD;
            n -= 1;
        }
        else{
            a = (a * a) % MOD;
            n /= 2;
        }
    }
    return x;
}

