ll modpow(long long N, long long P) {
    if(P==0) return 1;
    if(P % 2 == 0) {
        ll t = modpow(N, P / 2);
        return (t * t) % MOD;
    }
    return (N * modpow(N, P - 1)) % MOD;
}

void solve() {
    const ll MAX = 4e6;
    ll Q;
    cin >> Q;
    vll fac(MAX), inv(MAX);
    ll n = 1;
    FOR(i, 1, MAX) {
        fac[i] = n;
        n = n * (i + 1);
        n %= MOD;
    }

    n = 1;
    n = modpow(n, MOD-2);
    FOR(i, 1, MAX) {
        inv[i] = n;
        n = n * modpow(i+1, MOD-2);
        n %= MOD;
    }
    REP(i, Q) {
        ll x, d, n;
        cin >> x >> d >> n;
        if(d == 0) {
            out(modpow(x, n));
        }else {
            ll xd = (x * modpow(d, MOD - 2)) % MOD;
            if(n > MOD) 
                out(0);
            else
                out((fac[xd+n-1]*inv[xd-1])%MOD*(modpow(d, n) %MOD)%MOD);
        }
    }
}

