    for (int i = 2; i < mod; i++) {
        fact[i] = fact[i - 1] * i;
    }
    while (q--) {
        int x, d, n;
        cin >> x >> d >> n;
        mint mx = x, md = d, mn = n;
        if (d == 0) {
            cout << (mx ^ mn) << endl;
