            SDWORD lInput_xd = divMod(lInput_x, lInput_d);
            SDWORD lProduct = getContinuousProduct(lInput_xd, lInput_n);

            SDWORD lDPow = powMod(lInput_d, lInput_n);

            SDWORD lAns = mulMod(lDPow, lProduct);
            printf("%d\n", lAns);
        }
    }

    return 0;
}

