void Solve(){
  ll q;
    cin>>q;
  ll Mod=1000003;
  vll table(Mod);
  vll retable(Mod);
  vll num(Mod);
  num[1]=1;//inv
  FOR(i,2,Mod){
    num[i]=Mod-inv[Mod%i]*(Mod/i)%Mod;
  }

  table[0]=1;
  table[1]=1;
  FOR(i,2,Mod){
    table[i]=1;
    table[i]*=table[i-1]*i;
    table[i]%=Mod;
  }

  retable[0]=1;
  retable[1]=1;
  FOR(i,2,Mod){
    retable[i]=1;
    retable[i]*=modpow(i,Mod-2,Mod);
    retable[i]*=retable[i-1]*num[i];
    retable[i]%=Mod;
  }

  FOR(i,0,q){
    ll ans=1;
    ll x,d,n;
      cin>>x>>d>>n;

    if(n>=Mod){
      cout<<0<<endl;
      continue;
    }

    if(d==0){
      cout<<modpow(x,n,Mod)<<endl;
      continue;
    }

    ll dm=modpow(d,Mod-2,Mod);   

    if((x*dm+n-1)%Mod<=n-1){
      cout<<0<<endl;
      continue;
    }

    ans*=table[(x*dm+n-1)%Mod];
    ans*=retable[(x*dm-1+Mod)%Mod];
    ans%=Mod;
    ans*=modpow(d,n,Mod);
    ans%=Mod;
    cout<<ans<<endl;
  }
}

