constexpr ll MOD = 1e6+3;

struct Zp {
	ll x;
	Zp(ll a = 0) {
		if (a < 0) a = a%MOD + MOD;
		else if (a >= MOD*2) a %= MOD;
		else if (a >= MOD) a -= MOD;
		x = a;
	}
	Zp operator+(Zp r) const{ return x+r.x; }
	Zp operator-(Zp r) const{ return x-r.x+MOD; }
	Zp operator*(Zp r) const{ return x*r.x; }
	Zp operator/(Zp r) const{return x*r.inv().x;}
	Zp operator-()     const{ return MOD-x; }
	Zp inv() const { return pow(MOD-2); }
	Zp pow(ll e) const {
		Zp t = 1, m = *this;
		while (e) {
			if (e & 1) t = t*m;
			e >>= 1; m = m*m;
		}
		return t;
	}
	#define OP(c) Zp& operator c##=(Zp r){ return *this=*this c r; }
	OP(+)OP(-)OP(*)OP(/)
	void print() { cerr << x; }
};

vector<Zp> fact;

void precompute() {
	fact.resize(MOD+1);
	fact[0] = 1;
	rep(i, 1, MOD+1) fact[i] = fact[i-1] * i;
}

Zp solve(int x, int d, int n) {
	if (d == 0) return Zp(x).pow(n);
	Zp k = Zp(x) / d;
	if (k.x+n-1 >= MOD) return 0;
	Zp ret = fact[k.x+n-1];
	if (k.x > 0) ret /= fact[k.x-1];
	ret *= Zp(d).pow(n);
	return ret;
}

void run() {
	precompute();
	int q; cin >> q;
	while (q--) {
		int x, d, n; cin >> x >> d >> n;
		cout << solve(x, d, n).x << '\n';
	}
}

