int fac[N], ifac[N];

int main(void) {
	fac[0] = 1;
	rep (i, mo - 1) fac[i] = mul(fac[i - 1], i);
	ifac[mo - 1] = power(fac[mo - 1]);
	for (int i = mo - 2; i >= 0; i--)
		ifac[i] = mul(ifac[i + 1], i + 1);
