using namespace std;

const long long MOD=1000003;

template<typename T>
T modinv(T a,T m=MOD){
    T b=m,u=1,v=0;
    while(b!=0){
        T t=a/b;
        a-=t*b;
        std::swap(a,b);
        u-=t*v;
        std::swap(u,v);
    }
    u%=m;
    if(u<0)u+=m;
    return u;
}

template<typename T>
T modpow(T a,T n,T mod=MOD){//(a^n)%MOD
    T ret=1;
    while(n>0){
        if((n&1)!=0){//n%2==1
            ret=ret*a%mod;
        }
        a=a*a%mod;
        n=n/2;
    }
    return ret;
}

int main(){
    int q;
    cin>>q;
    vector<long long> factorial(MOD,1ll);
    for (long long i = 1; i < MOD; ++i) {
        factorial[i]=(factorial[i-1]*i)%MOD;
    }
    for (int T = 0; T < q; ++T) {
        long long x,d,n;
        cin>>x>>d>>n;
        if(d==0){
            cout<<modpow(x,n)<<endl;
        }
        else
        {
            long long invd=modinv(d);
            long long a=(x*invd)%MOD;
            long long shi=factorial[(a-1+MOD)%MOD];
            long long ue=factorial[(a+n-1+MOD)%MOD];
            shi=modinv(shi);
            long long seki=(ue*shi)%MOD;
            long long ans=(modpow(d,n)*seki)%MOD;
            cout<<ans<<endl;
        }
    }
    return 0;
}

