            // (3) の場合。
            // x を x/d の mod で置き換えて(2)の計算をし、最後に d^n を掛ける。
            x = x * mod_pow(d, mod-2, mod) % mod;
            cout << mod_pow(d, n, mod)*calc(x, n, mod) % mod << endl;
        }
    }
}

