pll operator*(const pll &a, const pll &b){
    ll x = a.first * b.first;
    ll y = a.second + b.second;
    while(x>0 && x%MOD==0){
        x /= MOD;
        y++;
    }
    return pll(x%MOD,y);
}

pll fact[3*MOD];
pll ifact[3*MOD];
pll modpow(pll a,ll b){
    pll r=pll(1,0);
    while(b){
        if(b&1)r=r*a;
        a=a*a;
        b>>=1;
    }
    return r;
}
pll modinv(pll a){
    pll ret = modpow(pll(a.first,0),MOD-2);
    ret.second = -a.second;
    return ret;
}

