//			printf("? %d : %d\n",r,Cfac[r].num);
			MNUM ans=Cfac[r]*(l? Cinv[l-1]:1)*QPow(d,r-l+1);
			printf("%d\n",ans.num);
		}
	}
	return 0;
}

