const int MAX = 2000010;
const int MOD = 1000003;

ll fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++) {
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

ll COM (int n, int k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll modpow (ll a, ll n) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % MOD;
        a = a * a % MOD;
        n >>= 1;
    }
    return res;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    COMinit();

    ll Q;
    cin >> Q;
    while (Q--) {
        ll x, d, n;
        cin >> x >> d >> n;
        ll ans;
        if (d == 0) ans = x * n % MOD;
        else {
            ll first = (MOD - 1 + x * inv[d]) % MOD;
            if (first == 0 || first / MOD != (first + n) / MOD) ans = 0;
            else {
                ans =  fac[first + n] * finv[first] % MOD;
                ans *= modpow(d, n);
                ans %= MOD;
            }
        }
        cout << ans << "\n";
    }
}

