  auto f = [&](modint x, modint y) {
    return x * y;
  };
  SegmentTree< modint > seg(mod, f, modint(1));
  for(int i = 0; i < mod; i++) {
    seg.set(i, i == 0 ? 1 : i);
  }
  seg.build();

  while(Q--) {
    modint X, D;
    int N;
    cin >> X >> D >> N;
    modint v = -X / D;
    int L = v.x - (N - 1);
    int R = v.x;

    modint mul;
    if(L <= 0) {

      int real = -L;
      int loop = real / mod;

      if(loop > 0) {
        mul = seg.query(0, mod) * loop;
      } else {
        mul = 1;
      }
      if(real % mod != 0) {
        mul *= seg.query((mod - real) % mod, mod);
      }
      mul *= seg.query(0, R + 1);
    } else {
      mul = seg.query(L, R + 1);
    }

    mul *= (-D).pow(N);
    cout << mul << endl;
  }
}

