struct mint {
    int x;
    mint() : x(0) {}
    mint(int a) {
        x = a % MOD;
        if (x < 0) x += MOD;
    }
    mint &operator+=(mint that) {
        x = (x + that.x) % MOD;
        return *this;
    }
    mint &operator-=(mint that) {
        x = (x + MOD - that.x) % MOD;
        return *this;
    }
    mint &operator*=(mint that) {
        x = (int) x * that.x % MOD;
        return *this;
    }
    mint &operator/=(mint that) { return *this *= that.inverse(); }
    mint operator-() { return mint(-this->x); }
    friend ostream &operator<<(ostream &out, mint m) { return out << m.x; }
    mint inverse() {
        int a = x, b = MOD, u = 1, v = 0;
        while (b) {
            int t = a / b;
            a -= t * b;
            u -= t * v;
            swap(a, b);
            swap(u, v);
        }
        return mint(u);
    }
