ll POW(ll n, ll m, ll p){
    ll res = 1, x = n;
    for(ll i = m; i > 0; i >>= 1){
        if(i & 1){
            res *= x;
            res %= p;
        }
        x *= x;
        x %= p;
    }
    return res;
}


int main(){
    const ll mod = 1000003;
    vector<ll> R(mod);
    R[0] = R[1] = 1;
    for(ll i = 2; i < mod; i++){
        R[i] = R[i - 1] * i;
        R[i] %= mod; 
    }

    int q;
    scanf("%d", &q);
    vector<pair<ll, pair<ll, pair<ll, int>>>> v(q);
    for(int i = 0; i < q; i++){
        scanf("%lld %lld %lld", &v[i].second.first, &v[i].first, &v[i].second.second.first);
        v[i].second.second.second = i;
    }
    sort(v.begin(), v.end());
    vector<ll> ans(q);
    vector<pair<ll, ll>> memo(mod, {-1, -1});
    for(int i = 0; i < q; i++){
        ll x = v[i].second.first, d = v[i].first, n = v[i].second.second.first;
        int idx = v[i].second.second.second;
        if(x == 0 || n >= mod){
            ans[idx] = 0;
            continue;
        }
        if(d == 0){
            ans[idx] = POW(x, n, mod);
            continue;
        }
        if(d == 1){
            if(x + n - 1 >= mod){
                ans[idx] = 0;
            }
            else{
                ans[idx] = R[x + n - 1] / R[x - 1];
            }
            continue;
        }

        ll t1 = (mod - x) % d, t2 = ((d - t1) + 1) % d, t3 = (x + t2 * mod) / d + 1;
        if(t3 <= n){
            ans[idx] = 0;
            continue;
        }

        if(memo[x].second == d){
            ans[idx] = memo[x].first;
            continue;
        }

        ll xx = x;
        for(ll j = 1; j < n; j++){
            xx *= (x + d * j);
            xx %= mod;
        }
        memo[x] = {xx, d};
        ans[idx] = xx;
    }

    for(int i = 0; i < q; i++){
        printf("%lld\n", ans[i]);
    }
}

