namespace AtCoder {
	using Input = std::vector<std::string>;
	using Num = std::vector<int>;

	Input input(void) {
		Input result;
		{
			std::string buf = "", row = "";
			std::getline(std::cin, buf);
			for (unsigned int i = 0; i < buf.size(); i++) {
				if (' ' == buf[i]) {
					result.push_back(row);
					row = "";
				} else {
					row += buf[i];
				}
			}
			result.push_back(row);
		}
		return result;
	}

	Num replaceToInteger(Input original = { "" }) {
		Num result;
		for (unsigned int i = 0; i < original.size(); i++) {
			result.push_back(atoi(original[i].c_str()));
		}
		return result;
	}
}

int main(void) {

	AtCoder::Num s = AtCoder::replaceToInteger(AtCoder::input());

	int q = 0;
	q = s[0];

	AtCoder::Num result;

	for (int loop = 0; loop < q; loop++) {
		int x = 0, d = 0, n = 0;
		AtCoder::Num buf = AtCoder::replaceToInteger(AtCoder::input());
		x = buf[0], d = buf[1], n = buf[2];

		int k = (d % 1000003);

		double mid = 1;
		for (int ii = 0; ii < n; ii++) {
			double t_buf = fmod((x + (ii * k)) , (1000003));
			double r_buf = fmod(mid , (1000003));
			mid = fmod((t_buf * r_buf) , (1000003));
		}
		result.push_back(mid);
	}

	for (int r : result) {
		printf("%d\n", r);
	}

	return 0;
}

