inline ll get_pow(ll base, int pow)
{
	ll ret = 1;

	while (pow)
	{
		if (pow & 1) ret = (ret*base) % mod;
		base = (base*base)%mod;
		pow >>= 1;
	}

	return ret;
}

inline ll get_inv(ll num)
{
	return get_pow(num, mod - 2);
}

inline ll mod_mul(ll a, ll b)
{
	return (a*b) % mod;
}

void init()
{
	for (int i = 1; i < mod; ++i) fact[i] = (fact[i - 1] * i) % mod;
	fact_inv[mod - 1] = get_inv(fact[mod - 1]);
	for (int i = mod - 2; i >= 1; --i) fact_inv[i] = (fact_inv[i + 1] * (i + 1)) % mod;
}

int main()
{
	init();

	int Q;

	scanf("%d", &Q);

	for (int i = 0; i < Q; ++i)
	{
		ll x, d, n;

		scanf("%lld %lld %lld", &x, &d, &n);

		if (d == 0) printf("%lld\n", get_pow(x, n));
		else
		{
			if (n >= mod) printf("0\n");
			else
			{
				ll k = mod_mul(mod - x, get_inv(d));

				if (n-1 >= k) printf("0\n");
				else
				{
					ll temp = mod_mul(mod_mul(get_pow(d, n), fact[k]), fact_inv[k - n]);
					if (n & 1) temp = mod - temp;
					printf("%lld\n", temp);
				}
			}
		}
	}

	return 0;
}

