#define MAX_D   (1000002)
static SDWORD s_alFactoryTable[(MAX_D + 1) * 2 + 1];

static SDWORD getContinuousProduct(
    SDWORD lStart,
    SDWORD lNum)
{
    if (0 == (lStart % DIVISOR)) {
        return 0;
    }
    if (((SQWORD)lStart / DIVISOR) != (((SQWORD)lStart + (SQWORD)lNum - 1LL) / DIVISOR)) {
        return 0;
    }

    SDWORD lRet = divMod(s_alFactoryTable[min(lStart + lNum - 1, (SDWORD)ArrayLength(s_alFactoryTable) - 1)], 
                        s_alFactoryTable[min(lStart - 1, (SDWORD)ArrayLength(s_alFactoryTable) - 1)]);
    return lRet;
}


