//a*x+b*y=1
//a>b>0
//b*y+(a-a/b*b)*x=1
//a*x+b*(y-a/b*x)=1
//-b<x<b -(a-a/b*b)<y<a-a/b*b
//-a=-(a-a/b*b)-a/b*b<y-a/b*x<a-a/b*b+a/b*b=a
int extgcd(int a, int b, int &x, int &y) {
    if (b == 1) {
        x = 0; y = 1;
    } else {
        int q = a / b;
        int r = a % b;
        extgcd(b, r, y, x);
        y -= q * x;
    }
}
//P*x+n*y=1
//0<n<P
ll inv(int n) {
    int x, y;
    extgcd(P, n, x, y);
    if (y < 0) y += P;
    return y;
}

