const int M = 1'000'003;
using mint = ModInt<M>;

mint gamma(mint x) {
    return mint::getFact(x.x - 1);
}

mint solve(int x, int d, int n) {
    if (d == 0) return mint::pow(x, n);
    if (x % d == 0) {
        int c = x / d;
        int d = x / d + n - 1;
        if (c / M != d / M) return mint(0);
    }
    mint ret = mint::pow(d, n);
    ret *= gamma(mint(x) / d + n);
    ret /= gamma(mint(x) / d);
    return ret;
}

signed main() {

    SS(int, Q);
    while (Q--) {
        SS(int, x, d, n);
        print(solve(x, d, n));
    }

}

