#define MOD 1000003
#define INF 0x3f3f3f3f
#define INFL 0x3f3f3f3f3f3f3f3f
using namespace std;
typedef long long ll;
typedef pair<int,int>P;

ll ppow(ll a,ll b){
	a%=MOD;
	ll res=1;
	while(b){
		if(b&1)res=(res*a)%MOD;
		a=(a*a)%MOD;
		b>>=1;
	}
	return res;
}
class Fact{
	vector<ll>fact;
	vector<ll>inv;
public:
	Fact(){}
	Fact(int n){
		n=n*2+10;
		fact=inv=vector<ll>(n);
		fact[0]=inv[0]=1;
		for(int i=1;i<n;i++){
			fact[i]=(fact[i-1]*i)%MOD;
			inv[i]=ppow(fact[i],MOD-2);
		}
	}
	ll get(int n){
		return fact[n];
	}
	ll nPr(int n,int r){
		return fact[n]*inv[n-r]%MOD;
	}
	ll nCr(int n,int r){
		return nPr(n,r)*inv[r]%MOD;
	}
	ll nrP(int n,int r){
		return nPr(n+r,n);
	}
	ll nrC(int n,int r){
		return nCr(n+r,n);
	}
};
int main(){
	Fact fac(1000000);
	int q;cin>>q;
	rep(i,q){
		ll x,d,n;scanf("%lld%lld%lld",&x,&d,&n);
		if(x==0){
			puts("0");
			continue;
		}
		if(d==0){
			printf("%lld\n",ppow(x,n));
			continue;
		}
		ll ans=ppow(d,n)*fac.get((x*ppow(d,MOD-2)+n+MOD-1)%MOD)%MOD*ppow(fac.get((x*ppow(d,MOD-2)+MOD-1)%MOD),MOD-2)%MOD;
		printf("%lld\n",ans);
	}
}

