}
modint cmb(int n,int r){
    if(n<0||r<0||n<r) return 0;
    return fct(n)*ifct(r)*ifct(n-r);
}

template<class T,class U>
T pw(T n,U m){
    if(m==0) return 1;
    else if(m%2==0) return pw(n*n,m/2);
    else return n*pw(n,m-1);
}

