#include "bits/stdc++.h"

using namespace std;

using ll = long long;
constexpr ll MOD = 1000003;

// a^b O(log b)
template <typename T>
T mypow(T a, T b)
{
    if (b == 0)
        return 1;
    T tmp = mypow(a, b / 2);
    if (b % 2)
        return (((tmp * tmp) % MOD) * a) % MOD;
    else
        return (tmp * tmp) % MOD;
}

struct RangeProductQuery
{
    using type = ll;
    static type id() { return 1; }
    static type op(const type &l, const type &r) { return l * r % MOD; }
};

template <typename M>
class SegmentTree
{
    using T = typename M::type;
    int n;
    std::vector<T> node;

  public:
    // v を基に初期化
    SegmentTree(const std::vector<T> &v)
    {
        // n は v.size() 以上の最小の2冪
        n = 1;
        while (n < int(v.size()))
            n *= 2;
        node.resize(2 * n, M::id());

        // i の子 -> 2*i+1, 2*i+2 , 親 -> (i-1)/2
        for (int i = 0; i < int(v.size()); i++)
            node[i + n] = v[i];
        for (int i = n - 1; i >= 0; i--)
            node[i] = M::op(node[2 * i], node[2 * i + 1]);
    }
    // Monoid::id 初期化
    SegmentTree(int _n)
    {
        // n は v.size() 以上の最小の2冪
        n = 1;
        while (n < _n)
            n *= 2;
        node.resize(2 * n, M::id());
    }
    // x 番目を val に更新
    void update(int x, T val)
    {
        x += n;
        node[x] = val;
        while (x >>= 1)
        {
            node[x] = M::op(node[2 * x], node[2 * x + 1]);
        }
    }
    // v[x] を M::op(v[x], val) に更新
    void operation(int x, T val)
    {
        x += n;
        node[x] = M::op(node[x], val);
        while (x >>= 1)
        {
            node[x] = M::op(node[2 * x], node[2 * x + 1]);
        }
    }
    // [a, b) の op
    T query(int l, int r)
    {
        l += n;
        r += n;
        T retl = M::id(), retr = M::id();
        while (l < r)
        {
            if (l & 1)
                retl = M::op(retl, node[l++]);
            if (r & 1)
                retr = M::op(node[--r], retr);
            l >>= 1;
            r >>= 1;
        }
        return M::op(retl, retr);
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int q;
    cin >> q;
    vector<ll> v(2222222);
    for (int i = 0; i < 2222222; i++)
        v[i] = i % MOD;
    SegmentTree<RangeProductQuery> dst(v);
    while (q--)
    {
        // x, x+d, ..., ... x+(n-1)d の積mod
        ll x, d, n;
        cin >> x >> d >> n;
        if (d == 0)
        {
            cout << mypow(x, n) << endl;
            continue;
        }
        if (n >= MOD)
        {
            cout << 0 << endl;
            continue;
        }
        ll st = x * mypow(d, MOD - 2) % MOD, gt = st + n - 1; // gt < 2 * MOD
        ll ret = mypow(d, n) * dst.query(st, gt + 1) % MOD;
        cout << ret << endl;
    }
}

