    int q;
    cin >> q;

    ll fac[1123456];
    fac[0] = 1;
    fac[1] = 1;
    for (int i = 2; i <= MOD; i++)
    {
        fac[i] = fac[i - 1] * i % MOD;
    }

    V res;
    REP(i, q)
    {
        ll x, d, n;
        cin >> x >> d >> n;

        if (d == 0)
        {
            res.push_back(fastPow(x, n));
            continue;
