        ll s = modDiv(x, d);
        ll t = (s + n - 1) % MOD;

        if (s % MOD == 0 || t % MOD == 0 || (s / MOD != t / MOD))
        {
            res.push_back(0);
            continue;
        }

        ll r = modDiv(fac[t], fac[s - 1]) * fastPow(d, n) % MOD;

        res.push_back(r);
    }

    for (int i : res)
        cout << i << endl;

    return 0;
}

