const ll mod=1e6+3;

ll d1[1001000],d2[1001000];

ll mult(ll n,ll m){//n^m%modを求める
    if(m==1){
        return n%mod;
    }else if(m%2==0){//オーバーフロー防止のためにn^(m/2)*n^(m/2)を考える
        ll t=mult(n,m/2);
        return (t*t)%mod;
    }else{//奇数の時はn^(m-1)*nを考える
        ll t=mult(n,m-1);
        return (t*n)%mod;
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int q;
    cin>>q;
    d1[0]=1;
    d2[0]=1;
    FOR(i,1,1000011){
      d1[i]=d1[i-1]*i;
      d1[i]%=mod;
      d2[i]=mult(d1[i],mod-2);
    }
    rep(i,q){
      ll x,d,n;
      cin>>x>>d>>n;
      if(d==0){
        cout<<mult(x,n)<<endl;
        continue;
      }
      ll ans=mult(d,n);
      ll a=x*mult(d,mod-2);
      a%=mod;
      ll b=a-1;
      (a+=n-1)%=mod;
      if(a/mod-b/mod>=1) ans=0;
      else{
        (ans*=d1[a])%=mod;
        if(b!=0) (ans*=d2[b])%=mod;
      }
      cout<<ans<<endl;
    }
}

