ll fac[1100000];
ll rev_fac[1100000];

ll my_pow(ll x,ll n)
{
    if (n==0) return 1;
    ll ans = my_pow(x,n/2);
    ans = ans*ans%P;
    if (n%2==1) ans = (ans*x)%P;
    return ans;
}


ll get_rev(ll x)
{
    return my_pow(x,P-2);
}


void init()
{
    fac[0] = 1;
    for(int i=1; i<=1000010; ++i)
        fac[i] = (fac[i-1]*i)%P;
