const lint mod = 1000003;

lint powmod(long x, long n){
  lint ret = 1;
  while(n > 0){
    if(n&1) ret *= x, ret %= mod, n -= 1;
    else x *= x, x %= mod, n >>= 1;
  }
  return ret;
}

vector<lint> fact;
vector<lint> revfact;

void setfact(int n){
  fact.resize(n+1); revfact.resize(n+1);
  fact[0] = 1;
  rep(i, n) fact[i+1] = fact[i] * (i+1) % mod;

  revfact[n-1] = powmod(fact[n-1], mod-2);
  for(int i=n-2; i>=0; i--) revfact[i] = revfact[i+1] * (i+1) % mod;
}

int main(){
    setfact(mod);
    int q;
    scanf("%d", &q);
    rep(i, q){
        int x, d, n;
        scanf("%d%d%d", &x, &d, &n);
        if(!d){
            printf("%lld\n", powmod(x, n));
            continue;
        }
        int y = x * powmod(d, mod-2) % mod;
        if(!y || y+n-1 >= mod){
            printf("0\n");
            continue;
        }
        printf("%lld\n", powmod(d, n) * fact[y+n-1] % mod * revfact[y-1] % mod);
    }
}

