const lint MOD = 1000003;

long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a / b * x;
    return d;
}

inline lint mod(lint a, lint m) {
    return (a % m + m) % m;
}

lint modinv(lint a, lint m) {
    lint x, y;
    extGCD(a, m, x, y);
    return mod(x, m);
}

lint modPow(lint x, lint k) {
	lint ret = 1;	
	while (k > 0) {
		if (k & 1) modMul(ret, x, MOD);
		modMul(x, x, MOD);
		k >>= 1;
	}
	return ret;
}

lint modfact[1000005];

void solve(lint x, lint d, int n) {
	lint dn = modPow(d, n);	
	lint base = x * modinv(d, MOD) % MOD;
	lint ans = modfact[(base + n - 1) % MOD];
	if (base > 0) ans *= modinv(modfact[base - 1], MOD);
//	for_(i,0,n) {
//		lint ai = (base + i) % MOD;
//		modMul(ans, ai, MOD);
//	}
	modMul(ans, dn, MOD);
	cout << ans << endl;
}

int main() {
	int Q;
	cin >> Q;
	modfact[0] = 1;
	for_(i,1,1000005) modfact[i] = (modfact[i-1] * i) % MOD;
	for_(q,0,Q) {
		int x, d, n;
		cin >> x >> d >> n;
		solve(x, d, n);
	}
}
