constexpr int M = 1000003;
int fact[M + 5], ifact[M + 5];
int mod_pow(int x, int n){
    int res = 1;
    while(n){
        if(n & 1)   res = (int)((ll)res * x % M);
        x = (int)((ll)x * x % M);
        n >>= 1;
    }
    return res;
}

