    for(int i = 1; i < M; ++i)  fact[i] = (int)((ll)fact[i - 1] * i % M);
    ifact[M - 1] = mod_pow(M - 1, M - 2);
    for(int i = M - 1; i > 0; --i)  ifact[i - 1] = (int)((ll)ifact[i] * i % M);
    int Q;
    cin >> Q;
