    if(debug == 0) cin>>x>>d>>n;
    else x = rand()%(mod+1), d = rand()%(mod+1), n = rand()%10000 + 1;

    Int ans = calc(x, d, n);
    if(debug){
      Int ans2 = calc2(x, d, n);
      if(ans != ans2) pr(x, d, n, ans, ans2), calc(x, d, n, 1);
      if(ans != ans2) calc2(x, d, n, 1);
      assert(ans == ans2);
