  return 0;
}

#include <bits/stdc++.h>
#define BASE 1000003
using namespace std;

long mod_fact[BASE];
long mod_inv_fact[BASE];

long mod_pow(long x, int k) {
    long ret = 1;
    while (k > 0) {
        if (k & 1) {
            ret = (ret * x) % BASE;
        }
        k >>= 1;
        x = (x * x) % BASE;
    }
    return ret;
}

inline long mod_inv(long x) {
    return mod_pow(x, BASE - 2);
}

void init() {
    mod_fact[0] = mod_inv_fact[0] = 1;
    for (int i = 1; i < BASE; i++) {
        mod_fact[i] = (mod_fact[i - 1] * i) % BASE;
        mod_inv_fact[i] = mod_inv(mod_fact[i]);
    }
}

long solve() {
    long x, d, n;
    cin >> x >> d >> n;
    if (d == 0) {
        return mod_pow(x, n);
    }
    if (n >= BASE) {
        return 0;
    }
    x = (x * mod_inv(d)) % BASE;
    if (x == 0 || x > (x + n - 1) % BASE) {
        return 0;
    }
    return (mod_pow(d, n) * ((mod_fact[x + n - 1] * mod_inv_fact[x - 1]) % BASE)) % BASE;
}

int main() {
    int q;
    cin >> q;
    init();
    for (int i = 0; i < q; i++) {
        cout << solve() << endl;
    }
    return 0;
}

