class Combination{
    long long int maxn;
    long long int mod;
    std::vector<long long int> factorial;
    std::vector<long long int> inverse;

    public:

    Combination(long long int n,long long int m):maxn(n),mod(m){
        factorial.push_back(1);
        inverse.push_back(1);

        for(long long int i = 1; i <= n; i++){
            factorial.push_back((factorial.back()*i)%mod);
            inverse.push_back([&](long long int x,long long int n) -> long long int{
                long long int ret = 1;
                while(n > 0){
                    if(n&1)ret = (ret*x)%mod;
                    x = (x*x)%mod;
                    n >>= 1;
                }
                return ret;
            }(factorial.back(),mod-2));
        }
    }

    long long int getFactorial(int idx){
        if(idx > maxn || idx < 0)return -1;
        return factorial[idx];
    }

    long long int getInverse(int idx){
        if(idx > maxn || idx < 0)return -1;
        return inverse[idx];
    }

    long long int comb(long long int n,long long int r){
        return (((factorial[n]*inverse[n-r])%mod)*inverse[r])%mod;
    }
};

ll mypow(ll x,ll n){
    ll ret = 1;
    while(n > 0){
        if(n&1){
            ret = (ret*x)%MOD;
        }
        x = (x*x)%MOD;
        n >>= 1;
    }
    return ret;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll q;
    cin >> q;

    vector<ll> x(q),d(q),n(q);
    for(int i = 0; i < q; i++){
        cin >> x[i] >> d[i] >> n[i];
    }

    Combination cb(1000002,1000003);

    for(int i = 0; i < q; i++){
        ll a = (x[i]*mypow(d[i],MOD-2))%MOD;
        if(a + n[i] - 1 >= MOD){
            cout << 0 << endl;
            continue;
        }else if(x[i] == 0){
            cout << 0 << endl;
            continue;
        }else if(d[i] == 0){
            cout << mypow(x[i],n[i]) << endl;
            continue;
        }
        ll ans = cb.getFactorial(a + n[i] - 1);
        ans *= cb.getInverse(a - 1);
        ans %= MOD;
        ans *= mypow(d[i],n[i]);
        ans %= MOD;
        cout << ans << endl;
    }

    return 0;
}

