            int64_t end = (start + n - 1) % MOD;
            if(n >= MOD || start == 0 || start > end){
                ans = 0;
            }else{
                ans = fact[end] * fact_inv[start-1] % MOD;
            }
            mul(ans, power_mod(d, n));
