using lint = long long;
using namespace std;
using pi = pair<int, int>;
const int mod = 1e6 + 3;

lint fact[mod + 69];
lint invf[mod + 69];

lint ipow(lint x, lint p){
	lint ret = 1, piv = x;
	while(p){
		if(p & 1) ret = ret * piv % mod;
		piv = piv * piv % mod;
		p >>= 1;
	}
	return ret;
}

lint query(int s, int e){
	int zeroCnt = (e + mod) / mod - (s - 1 + mod) / mod;
	if(zeroCnt == 1) return 0;
	s %= mod;
	e %= mod;
	return fact[e] * invf[s - 1] % mod;
}

int main(){
	fact[0] = invf[0] = 1;
	for(int i=1; i<mod; i++){
		fact[i] = fact[i-1] * i % mod;
		invf[i] = ipow(fact[i], mod - 2);
	}
	int q;
	scanf("%d",&q);
	while(q--){
		int x, d, n;
		scanf("%d %d %d",&x,&d,&n);
		if(d == 0){
			printf("%lld\n", ipow(x, n));
			continue;
		}
		lint quer = x * ipow(d, mod - 2) % mod;
		printf("%lld\n", query(quer, quer + n - 1) * ipow(d, n) % mod);
	}
}

