const int M = 1'000'003;
using mint = ModInt<M>;

mint solve(int x, int d, int n) {
    if (d == 0) return mint::pow(x, n);
    mint ret = mint::pow(d, n);
    mint s = mint(x) / d;
    int ss = s.x;
    int l = ss - 1;
    int r = ss - 1 + n;
    if (l / M != r / M) return mint(0);
    ret *= mint::getFact(r);
    ret *= mint::getFinv(l);
    return ret;
}

