        ll ans = mult(d,n);
        ll s = x*mult(d,inf-2)%inf;
        ll e = 0;
        (ans *= mod_fact((s+n-1)%inf,inf,e))%=inf;
        e = 0;
        (ans *= mult(mod_fact((s-1+inf)%inf,inf,e),inf-2))%=inf;
        cout << ans << endl;
    }    
}

