const int MOD = 1000003;

int fact[MOD * 2];

int fastPow(int num, int pwr) {
    int ret = 1;
    while (pwr) {
        if (pwr & 1)
            ret = ((long long)ret * num) % MOD;
        num = ((long long)num * num) % MOD;
        pwr >>= 1;
    }
    return ret;
}

int solve(int x, int d, int n) {
    // x * (x + d) * (x + 2d) * (x + 3d) * (x + 4d) * (x + 5d) * ... * (x + (n-1)d) =
    // d(x/d) * d(x/d + 1) * d(x/d + 2) * ... * d(x/d + n - 1) = 
    // d^n * (x/d)^nr! (https://en.wikipedia.org/wiki/Arithmetic_progression)

    if (n >= MOD)
        return 0;
    if (x == 0)
        return 0;

    int xd = ((long long)x * fastPow(d, MOD - 2)) % MOD;
    int rf = ((long long)fact[xd + n - 1] * fastPow(fact[(xd - 1 + MOD) % MOD], MOD - 2)) % MOD;
    return ((long long)fastPow(d, n) * rf) % MOD;
}

int dummy(int x, int d, int n) {
    int ans = 1;
    for (int i = 0; i < n; i++) {
        ans = ((long long)ans * x) % MOD;
        x = (x + d) % MOD;
    }
    return ans;
}

