long long int POW(long long int K, long long int p) {
	if (p == 0) { return K; }

	if (p == 1) { return K; }

	if ((p % 2) == 1) { return (POW(K, p - 1)*K) % MOD; }

	long long int tmp = POW(K, p / 2);

	return (tmp*tmp) % MOD;
}

long long int INV(long long int K) {
	return POW(K, MOD - 2);
}


