#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MAX = 1000003;
const ll MOD = 1000003;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

long long pow_mod(long long x, long long n) {
    long long a = 1, x2n = x;
    x2n %= MOD;
    while (n!=0) {
        if (n&1==1) {
            a *= x2n;
            a %= MOD;
        }
        x2n *= x2n;
        x2n %= MOD;
        n >>= 1;
    }
    return a;
}

ll mod_inv(ll a, ll m) {
    ll b = m, x = 1, y = 0, s, t;
    while ( b != 0 ) {
        s = y;
        y = x - ( a / b ) * y;
        x = s;
        t = b;
        b = a % b;
        a = t;
    }
    return (x % m + m) % m;
}

int main() {
    int Q;
    cin >> Q;
    COMinit();
    for ( int i = 0; i < Q; i++ ) {
        ll x,d,n;
        cin >> x >> d >> n;
        ll ans = 0;
        ll xd = x * mod_inv(d, MOD) % MOD;
        if ( xd == 0 || MOD <= xd + n - 1) {
            ans = 0;
        } else if ( d == 0 ) {
            ans = pow_mod(x, n);
        } else {
            ll r = fac[(xd + n - 1 + MOD) % MOD] * finv[(xd - 1 + MOD) % MOD] % MOD;
            ans = r * pow_mod(d, n) % MOD;
        }
        cout << ans << '\n';
    }
    return 0;
}

