	t1 *= t1;
	t1 %= MOD;
	if(b%2) t1 *= a;
	t1 %= MOD;
	return t1;
}

void solve(){
	fact[0]=invfact[0]=1;
	forsn(i,1,MOD){
		fact[i]=(fact[i-1]*i)%MOD;
		invfact[i] =mpow(fact[i],MOD-2);
	}
	ll q;
	cin >> q;
	forn(i,q){
		ll x,d,n;
		cin >> x >> d >> n;
		if(d==0){
			cout << mpow(x,n) << ln;
		}
		else if(n>=MOD){
			cout << 0 << ln;
		}
		else{
			ll nx = (x*mpow(d,MOD-2));
			nx %= MOD;
			ll factor = mpow(d,n);
			// ll ans = 0;
			ll ans = factor*((fact[(nx+n-1)%MOD])*(nx==0 ? 0 : invfact[nx-1])%MOD)%MOD;
			// if(nx == 0) ans = 0;
			cout << ans << ln; 
		}
	}
}


