  ll X=(x*gyaku(d))%mod;
  if(X+n-1>=mod||X-1<=0) return 0;
  ans*=frac[(X+n-1)%mod];
  ans%=mod;
  ans*=gfrac[(X+mod-1)%mod];
  ans%=mod;
  return ans;
}
