void Solve(){
  ll q;
    cin>>q;
  ll Mod=1000003;
  vll table(Mod);
  vll retable(Mod);

  table[1]=1;
  FOR(i,2,Mod){
    table[i]=1;
    table[i]*=table[i-1]*i;
    table[i]%=Mod;
  }

  retable[1]=1;
  FOR(i,2,Mod){
    retable[i]=1;
    retable[i]*=modpow(i,Mod-2,Mod);
    retable[i]*=retable[i-1];
    retable[i]%=Mod;
  }

  FOR(i,0,q){
