    ans*=table[(x*dm+n-1)%Mod];
    ans*=retable[(x*dm-1)%Mod];
    ans%=Mod;
    ans*=modpow(d,n,Mod);
    ans%=Mod;
    cout<<ans<<endl;
  }
}

