void pre_comb(void){
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for(int i=2; i<MAX; i++){
		fac[i] = fac[i-1] * i % mod;
		inv[i] = mod - inv[mod%i] * (mod/i) % mod;
		finv[i] = finv[i-1] * inv[i] % mod;
	}
}

long long comb(int n, int k){
	if(n < k) return 0;
	if(n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}

long long modpow(long long x, int y){
	if(x % mod == 0) return 0;
	if(y == 0) return 1;
	if(y % 2 == 0){
		return (modpow(x, y/2) * modpow(x, y/2)) % mod;
	}else{
		return (x * modpow(x, y-1) % mod);
	}
}

