unordered_map<ll,ll> power,inv;
ll getPow(ll a,ll p){
  ll key = (a<<20) + p;
  if(!power.count(key)){
    ll cp = a;
    power[key] = 1;
    while(p){
      if(p&1) power[key] = (power[key]*cp)%MOD;
      p >>= 1;
      cp = (cp*cp)%MOD;
    }
  }
  return power[key];
}
ll getInverse(ll i){
  if(!inv.count(i)) inv[i] = getPow(i,MOD-2)%MOD;
  return inv[i];
}
int main(){
  ios::sync_with_stdio(0);
  cin.tie(0);
  ll idx,q,x,d,n;
