  }
  sort(begin(vt),end(vt));
  vector<ll> ret(q);
  ll preX = -1, preD = -1, preN = -1, preNN = -1, preAns = -1;
  for(auto& p : vt){
    tie(x,d,n,idx) = p;
    if(x == 0) ret[idx] = 0;
