ll fastPow(ll x, ll n)
{
    ll res = 1;
    while (n > 0)
    {
        if (n & 1)
            res = res * x % MOD;
        x = x * x % MOD;
        n >>= 1;
    }
    return res;
}

ll modDiv(ll a, ll b)
{
    return a * fastPow(b, MOD - 2) % MOD;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int q;
    cin >> q;

    ll fac[1123456];
    fac[0] = 1;
    fac[1] = 1;
    for (int i = 2; i <= MOD; i++)
    {
        fac[i] = fac[i - 1] * i % MOD;
    }

    V res;
    REP(i, q)
    {
        ll x, d, n;
        cin >> x >> d >> n;

        if (d == 0)
        {
            res.push_back(fastPow(x, n));
            continue;
        }

        ll s = modDiv(x, d);
        ll t = (s + n - 1);

        if (s % MOD == 0 || t % MOD == 0 || (s / MOD != t / MOD))
        {
            res.push_back(0);
            continue;
        }

        if (t > MOD)
            assert(false);
        ll r = modDiv(fac[t % MOD], fac[s - 1]) * fastPow(d, n) % MOD;

        res.push_back(r);
    }

    for (int i : res)
        cout << i << endl;

    return 0;
}

