const static int mod = 1000003;

template<typename T, T M>
struct modint {
  T a;
  constexpr modint(const T x = 0): a((x%M+M)%M){}
  constexpr modint pow(T r) const {
    modint ans(1), aa(a);
    while(r) { if(r & 1) ans *= aa; aa *= aa; r >>= 1; }
    return ans;
  }

  constexpr modint& operator+=(const modint r) { a += r.a; if(a >= M) a -= M; return *this; }
  constexpr modint& operator-=(const modint r) { a -= r.a; if(a < 0) a += M; return *this; }
  constexpr modint& operator*=(const modint r) { a = a * r.a % M; return *this; }
  constexpr modint& operator/=(const modint r) { return (*this) *= r.pow(M-2); }
  constexpr modint operator+(const modint r) const { return modint(a) += r; }
  constexpr modint operator-(const modint r) const { return modint(a) -= r; }
  constexpr modint operator*(const modint r) const { return modint(a) *= r; }
  constexpr modint operator/(const modint r) const { return modint(a) /= r; }
  constexpr bool operator!=(const modint r) const { return a != r.a; }
};

typedef modint<long long, mod> mi;

template<typename T>
constexpr vector<pair<T, T>> const build_factorial(int N) {
  vector<pair<T, T>> f(N);
  f[0].first = T(1);
  for(int i = 1; i < N; i++)
    f[i].first = f[i - 1].first * T(i);
  f[N - 1].second = T(1) / f[N - 1].first;
  for(int i = N - 2; i >= 0; --i)
    f[i].second = f[i + 1].second * T(i + 1);
  return move(f);
}

int main() {
  long long q, x, d, n;
  cin >> q;
  vector<pair<mi, mi>> f = build_factorial<mi>(mod);

  auto solve = [&](const long long& x, const long long& n) {
    return x == 0 || x + n - 1 >= mod ? mi(0) : f[x + n - 1].first * f[x - 1].second;
  };

  while(q--) {
    cin >> x >> d >> n;
    cout << (d ? solve((mi(x) / mi(d)).a, n) * mi(d).pow(n) : mi(x).pow(n)).a << endl;
  }
}

