        if (d == 0) {
            std::cout << pow(x, n, mod) << std::endl;
            continue;
        }
        auto t = x * inverse(d, mod) % mod;
        if (t + n - 1 >= mod || t == 0) std::cout << 0 << std::endl;
        else std::cout << fact[t + n - 1] * inv[t - 1] % mod * pow(d, n, mod) % mod << std::endl;
    }

    return 0;
}

