int main() {
  Makestk(MOD);

  ll q,x,d,n,y;
  ll ans=1LL;
  cin>>q;
  REP(i,q){
    cin>>x>>d>>n;
    y=moddiv(x,d);
    //y～y+n-1までリダクション掛け算
    ll loop=(y+n-1)/MOD;
    if (loop!=0){
      cout<<0<<endl;
      continue;
    }

    ll red=Reduc1(y,y+n);
    ans=red*expmod(d,n)%MOD;
    cout<<ans<<endl;
  }

  return 0;
}

