const long long MOD = 1e6 + 3;

long long mod_pow(long long a, long long b){
  long long ret = 1;
  while(b){
    if(b & 1) ret = ret * a % MOD;
    a = a * a % MOD;  b >>= 1;
  }
  return ret;
}

long long mod_inv(long long a){
  return mod_pow(a, MOD - 2);
}

long long Q, X, D, N;
long long F[MOD], INVF[MOD];
long long ans;

int main(void){
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr), cout.tie(nullptr);

  F[0] = 1;
  for(int i = 1 ; i < MOD ; i++) F[i] = F[i - 1] * i % MOD;

  INVF[MOD - 1] = MOD - 1;
  for(int i = MOD - 1 ; i >= 1 ; i--) INVF[i - 1] = INVF[i] * i % MOD;
  debug(INVF[1]);
  cin >> Q;
  while(Q--){
    cin >> X >> D >> N;

    X = X * mod_inv(D) % MOD;

    if(X + N  - 1 >= MOD || X == 0) ans = 0;
    else {
      ans = F[X + N - 1] * INVF[X - 1] % MOD;
      ans = ans * mod_pow(D, N) % MOD;
    }

    cout << ans << '\n';
  }
  return 0;
}

