long long factorial(long long i){ // 階乗
  if(i > 0)
    return i * factorial(i-1);
  else
    return 1;
}

// a^n mod
long long modpow(long long a, long long n, long long mod) {
  long long res = 1;
  while (n>0) {
    if(n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

// a^(-1) mod
long long modinv(long long a, long long mod) {
  return modpow(a, mod-2, mod);
}

int main() {
  long long Q;
  const long long mod = 1000003;

  cin >> Q;

  // あらかじめ必要な階乗(mod)を計算しておく
  vector<long long> factmod;
  factmod.push_back(1); // 0! = 1
  long long tmp = 1;
  for(int i=1; i<mod+10; i++) { // 1000003!(mod 1,000,003) まで計算しておく ちょっと多めに
    tmp = (tmp*i)%mod;
    factmod.push_back(tmp);
  }

  long long ans = 1;
  rep(i, Q) {
    long long x, d, n;
    cin >> x >> d >> n;

    if(d!=0) {
      // 求める積は d^n * (x/d) * (x/d + 1) * ... * (x/d + (n-1))
      // つまり d^n * (x/d + (n-1))! / (x/d - 1)!
      long long xbyd = x * modinv(d, mod) %mod; // x/d (mod)
      if(xbyd==0) xbyd += mod;
      ans = modpow(d, n, mod) * factmod[((xbyd+n)%mod-1)%mod] %mod * modinv(factmod[(xbyd-1)%mod], mod) %mod;

    } else {
      // 求める積は x^n
      ans = modpow(x, n, mod)%mod;
    }

    if(ans<0) ans += mod;
    cout << ans << endl;
  }
}

