		scanf("%d%d%d",&x,&d,&n);
		if(d==0){
			printf("%d\n",QPow(x,n).num);
			continue;
		}
		MNUM tmp=QPow(d,MOD-2)*x;
		long long l=tmp.num,r=tmp.num+n-1;
		if(r>=MOD) printf("0\n");
		else{
			MNUM ans=Cfac[r]*(l? Cinv[l-1]:0)*QPow(d,r-l+1);
			printf("%d\n",ans.num);
		}
	}
	return 0;
}

