    cin >> x >> d >> n;
    Mod lm = Mod(x) / d - 1;
    ll l = (ll)lm;
    ll r = l+n;
    ll answer = (ll)(Mod::fact(r) / Mod::fact(l) / ((Mod(1)/d) ^ n));
    cout << answer << endl;
  }
  return 0;
}

