#define fix(num) (int((num%MOD+MOD)%MOD))

struct MNUM{
	int num;
	MNUM(){}
	MNUM(int _num):num(_num){}
	MNUM operator +(const MNUM B)const{return fix(1ll*num+B.num);}
	MNUM operator -(const MNUM B)const{return fix(1ll*num-B.num);}
	MNUM operator *(const MNUM B)const{return fix(1ll*num*B.num);}
	MNUM operator +=(const MNUM B){return *this=(*this)+B;}
	MNUM operator -=(const MNUM B){return *this=(*this)-B;}
	MNUM operator *=(const MNUM B){return *this=(*this)*B;}
}Cfac[MOD+3],Cinv[MOD+3];

int q,n,x,d;

MNUM QPow(MNUM und,int cur){
	MNUM resu(1);
	while(cur){
		if(cur&1) resu*=und;
		und*=und;
		cur>>=1;
	}
	return resu;
}
void Init(){
	Cfac[0]=1;for(int i=1;i<MOD;i++) Cfac[i]=Cfac[i-1]*i;
	Cinv[MOD-1]=QPow(Cfac[MOD-1],MOD-2);for(int i=MOD-2;i>=0;i--) Cinv[i]=Cinv[i+1]*(i+1);
}
int main(){
	Init();
	scanf("%d",&q);
