		long long l=tmp.num,r=tmp.num+n-1;
		if(r>=MOD) printf("0\n");
		else{
			MNUM ans=Cfac[r]*(l? Cinv[l-1]:0)*QPow(d,r-l+1);
			printf("%d\n",ans.num);
		}
	}
	return 0;
}

