const int MAX = MOD+5;
mint fact[MAX], invfact[MAX], inv[MAX];

void facinit() {
	fact[0] = fact[1] = 1;	
	invfact[0] = invfact[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++){
		fact[i] = fact[i - 1] * i;
		inv[i] = - inv[MOD%i] * (MOD / i);
		invfact[i] = invfact[i - 1] * inv[i];
	}
}

template<class T>
T fastpow(T a, long long p){
	T tmp = a;
	T ret = 1;
	while(p){
		if(p & 1)ret *= tmp;
		p >>= 1;
		tmp = tmp * tmp;
	}
	return ret;
}

int main()
{
	int q;
	scanf("%d", &q);
	facinit();
	for(int i=0; i < q; i++){
		mint x,d,n;
		cin >> x >> d >> n;
		if(d.v == 0){
			cout << fastpow(x, n.v).v << endl;
		}
		mint f = MOD - x.v;
		f /= d;
		if(f.v <= n.v){
			cout << 0 << "\n";
			continue;
		}
		mint s = x/d;
		if(s.v + n.v >= MOD){
			cout << 0 << "\n";
			continue;
		}
		cout << (fastpow(d, n.v) * fact[s.v + n.v - 1] * invfact[s.v-1]).v << "\n";
	}
	return 0;
}

