template <ll mod>
struct ModCombination{
    ll N;
    vector<ll> fact,inv,finv;

    ModCombination(ll n):N(n){
        fact.assign(n+1, 1);
        inv.assign(n+1, 1);
        finv.assign(n+1,1);
        for(int i=1;i<n;i++){
            fact[i+1] = fact[i]*(i+1)%mod;
            inv[i+1] = inv[mod%(i+1)]*(mod-mod/(i+1))%mod;
            finv[i+1] = finv[i]*inv[i+1]%mod;
        }
    }

    ll Comb(ll n,ll k){
        if(k<0||n<k)return 0;
        return (fact[n]*finv[k]%mod)*finv[n-k]%mod;
    }
};

ll mod_pow(ll x,ll e){
  return e? e&1? x*mod_pow(x,e-1)%MOD:mod_pow(x*x%MOD,e/2):1;
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  ModCombination<MOD> c(MOD-1);
  ll Q;cin>>Q;
  for(ll q=0;q<Q;q++){
    ll x,d,n;cin>>x>>d>>n;
