const int Z = 1e6+3;

int fp(int a, int x) {
    if (x == 0) {
        return 1;
    }
    if (x % 2 == 1) {
        return 1ll * a * fp(a, x - 1) % Z;
    }
    int t = fp(a, x / 2);
    return 1ll * t * t % Z;
}

int inv(int a) {
    return fp(a, Z - 2);
}

int main() {
    int fac[Z];
    fac[0] = 1;
    for (int i = 1; i < Z; i++) {
        fac[i] = 1ll * fac[i-1] * i % Z;
    }

    int q;
    cin >> q;

    while (q--) {
        int x, d, n;
        cin >> x >> d >> n;

        int ans;
        if (d == 0) {
            ans = fp(x, n);
        } else {
            int k = 1ll * (Z - x) * inv(d) % Z;
            ans = k < n ? 0 : 1ll * fp(d, n) * fac[Z-k+n-1] % Z * inv(fac[Z-k-1]) % Z;
        }

        cout << ans << endl;
    }

    return 0;
}

