const lint MOD = 1000003;

long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a / b * x;
    return d;
}

inline lint mod(lint a, lint m) {
    return (a % m + m) % m;
}

lint modinv(lint a, lint m) {
    lint x, y;
    extGCD(a, m, x, y);
    return mod(x, m);
}

lint modPow(lint x, lint k) {
	lint ret = 1;	
	while (k > 0) {
		if (k & 1) modMul(ret, x, MOD);
		modMul(x, x, MOD);
		k >>= 1;
	}
	return ret;
}

const int MAX_I = 1000005;
