lint invfact[MAX_I];

void solve(lint x, lint d, lint n) {
	if (d == 0) {
		cout << modPow(x, n) << endl;
		return;
	}
	lint dn = modPow(d, n);	
	lint base = (x * modinv(d, MOD)) % MOD;
	if (x % MOD == 0 || base == 0 || base + n - 1 >= MOD) {
		cout << 0 << endl;
		return;
	}
	lint ans = modfact[base + n - 1];
	modMul(ans, invfact[base - 1], MOD);
//	for_(i,0,n) {
//		lint ai = (base + i) % MOD;
//		modMul(ans, ai, MOD);
//	}
	modMul(ans, dn, MOD);
	cout << ans << endl;
}

