template <class T>
T pow(T x, T n, T mod) {
    T ret = 1;
    while(n > 0) {
        if ((n & 1) == 1) ret = (ret * x) % mod;
        x = (x * x) % mod;
        n >>= 1;
    }
    return ret;
}

template <class T>
T inverse(T x, T p) { return pow(x, p - 2, p); }

void init_factorial(int n, long long mod) {
    fact = new long long[n + 1];
    inv = new long long[n + 1];
    fact[0] = 1;
    for (long long i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
    inv[n] = inverse(fact[n], mod);
    for (long long i = n; i > 0; i--) inv[i - 1] = inv[i] * i % mod;
}

int main() {
    int q;
    constexpr i64 mod = 1000003;
    std::cin >> q;
    init_factorial(mod - 1, mod);
    while (q--) {
        i64 x, d, n;
        std::cin >> x >> d >> n;
        if (d == 0) {
            std::cout << pow(x, n % mod, mod) << std::endl;
            continue;
        }
        auto t = x * inverse(d, mod) % mod;
        if (t + n - 1 >= mod || x == 0) std::cout << 0 << std::endl;
        else std::cout << fact[t + n - 1] * inv[t - 1] % mod * pow(d, n % mod, mod) % mod << std::endl;
    }

    return 0;
}

