LL mod = 1000003;

LL mod_inv(LL a, LL md = 1000003) {
	LL b = md, u = 1, v = 0;
	while (b) {
		LL t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= md;
	if (u < 0) u += md;
	return u;
}

LL power(LL a, LL b, LL md = 1000003) {
	assert(b >= 0);
	LL res = 1;
	while (b) {
		if (b & 1) res = res * a % md;
		a = a * a % md;
		b >>= 1;
	}
	return res;
}

