const ll mod=1000003;

ll ksm(ll a,ll b){
    ll ans=1ll;
    while(b){
        if(b&1) ans=ans*a%mod;
        b>>=1;
        a=a*a%mod;
    }
    return ans;
}


const int maxn=2e6+70;
ll fac[maxn],inv[maxn],finv[maxn];
void init(){
    inv[0]=inv[1]=fac[0]=fac[1]=finv[0]=finv[1]=1;
    for(int i=2;i<maxn;i++) {
        fac[i]=1ll*fac[i-1]*i%mod;
        inv[i]=mod-inv[mod%i]*(mod/i)%mod;
        finv[i]=finv[i-1]*inv[i]%mod;
    }
}

void solved(int x,int d,int n){
    if(d==0) {
        cout<<ksm(x*1ll,n*1ll)<<endl;
        return ;
    }
    ll zx=1ll*x*inv[d]%mod;
    if(zx+n-1>=mod) {
        cout<<0<<endl;
        return ;
    }
    ll ret=ksm(d*1ll,n);
    ret=ret*fac[zx+n-1]%mod;
    ret=ret*finv[zx-1]%mod;
    cout<<ret<<endl;
    return ;
}

int main (){
    init();
    int Q;scanf("%d",&Q);
    int x,d,n;
    while(Q--) {
        scanf("%d %d %d",&x,&d,&n);
        solved(x,d,n);
    }
    return 0;
}

