struct mint {
    ll x;
    mint(ll x = 0) : x(x % MOD) {}
    mint& operator += (const mint a) {
        if ( (x += a.x) >= MOD) { x -= MOD; }
        return *this;
    }
    mint& operator -= (const mint a) {
        if ( (x += MOD - a.x) >= MOD) { x -= MOD; }
        return *this;
    }
    mint& operator *= (const mint a) {
        (x *= a.x) %= MOD;
        return *this;
    }
    mint operator + (const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator - (const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator * (const mint a) const {
        mint res(*this);
        return res *= a;
    }
};

// x の y 乗を求める O(log MOD)
ll modpow(ll x, ll y) {
    if (y == 0) return 1;
    ll res = modpow(x, y / 2);
    return res * res % MOD * (y & 1 ? x : 1) % MOD;
}
// x の逆元を求める O(logMOD)
ll modinv(ll x) { return modpow(x, MOD - 2); }
mint modinv(mint x) { return modpow(x.x, MOD - 2); }

ll Q;

vector<mint> fact;    // 階乗 i!

ll solve(ll x, ll d, ll n) {
    // 等差数列の積は d^n * ( (x/d + n - 1)! / (x/d - 1)! ) である
    mint x_d = mint(x) * mint(modinv(d));

    // d が 0 のときは例外 -> x^n になる
    if(d == 0) { return modpow(x, n); }

    // 剰余の関係上 MAX_X! 以上の階乗は 0 になる
    if((x_d + n - 1).x >= MOD) { return 0; }

    mint ret = modpow(d, n);
    ret *= fact[ (x_d + n - 1).x ];
    ret *= modinv(fact[ (x_d - 1).x ]);

    return ret.x;
}

