    	ll dn = powLL(d, n);
    	ll invx = x * inv[d] % mod;
    	ll res = dn * fac[invx+n-1] % mod;
    	res *= finv[(invx-1+mod)%mod];
    	res %= mod;
    	cout << res << endl;
    }
    return 0;
}

