const int M = 1000 * 1000 + 3;
int mod(int n) {
    return (n % M + M) % M;
}   
int fp(int a, int p) {
    int ans = 1, cur = a;
    for (int i = 0; (1 << i) <= p; ++i) {
        if ((p >> i) & 1) ans = mod(ans * cur);
        cur = mod(cur * cur);
    }   
    return ans;
}   
int dv(int a, int b) {
    return mod(a * fp(b, M - 2));
}   
int p[M];
int get(int l, int len) {
    int r = l + len - 1;
    if (r >= M) return 0;
    else return dv(p[r], p[l - 1]);
}
