		a = (ll)a * a % md;
		p >>= 1;
	}
	return an;
}

int go(int d, int n) { return (ll)fc[n] * pw(d, n) % md; }

int solve(){
	int x, d, n;
	scanf("%d%d%d", &x, &d, &n);
	if (x == 0)return 0;
	if (d == 0)return pw(x, n);
	if (n >= md)return 0;
	int ed = (x + (ll)d * (n - 1)) % md;
	if (ed == 0)return 0;
	int i = (ll)ed * pw(d, md - 2) % md;
	if (i < n)return 0;
	int an = (ll)go(d, i) * pw(go(d, i - n), md - 2) % md;
	return an;
}

int main(){
	fc[0] = 1;
	f(i, 1, md)fc[i] = (ll)fc[i - 1] * i % md;
	int q;
	scanf("%d", &q);
	while (q--)printf("%d\n", solve());
}

