ll MAX = 1e6+3;
ll MOD = MAX;
vector<ll> inv(MAX);
vector<ll> prod(MAX);

int calcInv() {
    inv[0] = -1;
    inv[1] = 1;
    for (ll i = 2; i < MAX; i++) {
        inv[i] = (inv[MOD % i] * (MOD / i)) % MOD;
        inv[i] = (-1 * inv[i] + MOD) % MOD;
    }
    return 0;
}

int calcProd() {
    prod[0] = -1;
    prod[1] = 1;
    for (ll i = 2; i < MAX; i++) {
        prod[i] = (prod[i - 1] * i) % MOD;
    }
    return 0;
}

ll calcExp(int a, int m) {
    ll i = 0;
    ll ans = 1;
    ll temp = a;
    while ( m > 0 ) {
        if ( m % 2 == 1 ) ans = (ans * temp) % MOD;
        temp = (temp * temp) % MOD;
        m /= 2;
    }

    return ans;
}

int main() {

