template<ll mod>
class Fp {
public:
	ll val;

private:
	inline void calc_mod(ll& v) {
		if (v >= mod)v -= mod;
	}
public:
	Fp(){}
	Fp(ll v) :val(v%mod) {
		if (val < 0)val += mod;
	}

	Fp operator+=(const Fp &in) {
		val += in.val;
		calc_mod(val);
		return *this;
	}

	Fp operator+(const Fp &in) const{
		return Fp(*this) += in;
	}

	Fp &operator-=(const Fp &in) {
		val -= in.val;
		calc_mod(val);
		if (val < 0)val += mod;
		return *this;
	}

	Fp operator-(const Fp &in) const{
		return Fp(*this) -= in;
	}

	Fp& operator*=(const Fp& in) {
		val = val * in.val % mod;
		return *this;
	}

	Fp operator*(const Fp &in) const{
		return (Fp(*this) *= in);
	}

	Fp& operator/=(const Fp& in) {
		*this *= modpow(in, mod - 2);
		return *this;
	}

	Fp operator/(const Fp& in) const{
		return (*this)*modpow(in, mod - 2);
	}

	bool operator==(const Fp&in)const {
		return val == in.val;
	}

	bool operator!=(const Fp&in)const {
		return val != in.val;
	}

	friend Fp modpow(const Fp& in, ll n){
		if (n == 0)return 1;
		if (n & 1) {
			return in*modpow(in*in, n / 2);
		}
		else {
			return modpow(in*in, n / 2);
		}
	}
};
using modll = Fp<mod>;

class Factorial {
public:
	vector<modll> fact, finv;
	Factorial(ll n) :fact(n, modll(1)), finv(n, modll(1)) {
		for (int i = 2; i < n; i++) {
			modll tmp(i);
			fact[i] = fact[i - 1] * tmp;
			finv[i] = finv[i-1] / tmp;
		}
	}

	modll com(const ll& n, const ll& k) {
		if (n < k || n < 0 || k < 0)return modll(0);
		return fact[n] * finv[k] * finv[n - k];
	}
};


int main() {
	cin >> Q;
	Factorial f(mod);
	for (int i = 0; i < Q; i++) {
		ll _x, _d, n;
		cin >> _x >> _d >> n;
		modll x(_x), d(_d);
		x /= d;
		if (d.val == 0) {
			cout << modpow(x, n).val << endl;
			return 0;
		}

		if (mod <= x.val + n - 1||x.val==0) {
			cout << 0 << endl;
		}
		else {
			modll res = modpow(d, n);
			res *= f.fact[x.val + n - 1];
			res *= f.finv[x.val - 1];
			cout << res.val << endl;
		}
	}
}

