using Rat=Rational;

std::vector<int>fac(1100000);

Rational solve(Rational x0, Rational x1, int d, int n) {
	if (d == 0) {
		return pow(Rational(x0), n);
	}
	if (d == 1) {
		if (x0 > x1 || x0 == 0) {
			return 0;
		}
		return Rational(fac[x1]) / Rational(fac[x0 - Rational(1)]);
	}
	return solve(Rational(x0) / Rational(d), Rational(x1) / Rational(d), 1, n) * pow(Rational(d), n);
}

int ans(int x, int d, int n) {
	int res = 1;
	for (int i = 0; i < n; ++i) {
		int tmp = x + i * d;
		res *= tmp;
		modify(res);
	}
	return res;
}

