	vector<long long> fact(MOD);
	fact[0] = 1;
	for (i = 1; i < MOD; i++) fact[i] = (fact[i - 1] * i) % MOD;

	cin >> qq;
	while (qq--) {
		cin >> x >> d >> n;

		if (d == 0) {
			// calculate x ^ n
			ans = 1;
			xx = x;
			for (i = 0; i < 50; i++) {
				if ((1LL << i) & n) ans = (ans * xx) % MOD;
				xx = (xx * xx) % MOD;
			}
		}
		else {
			xd = division(x, d, MOD);
			if (xd + n - 1 >= MOD)
				ans = 0;
			else {
				if (xd == 0) ans = division(fact[xd + n - 1], 1, MOD);
				else ans = division(fact[xd + n - 1], fact[xd - 1], MOD);

				// calculate d ^ n
				q = 1;
				dd = d;
				for (i = 0; i < 50; i++) {
					if ((1LL << i) & n) q = (q * dd) % MOD;
					dd = (dd * dd) % MOD;
				}
				ans = (ans * q) % MOD;
			}
		}

