void Solve(){
  ll q;
    cin>>q;
  ll Mod=1000003;
  vll table(Mod);
  vll retable(Mod);

  table[1]=1;
  FOR(i,2,Mod){
    table[i]=1;
    table[i]*=table[i-1]*i;
    table[i]%=Mod;
  }

  retable[1]=1;
  FOR(i,2,Mod){
    retable[i]=1;
    retable[i]*=modpow(i,Mod-2,Mod);
    retable[i]*=retable[i-1];
    retable[i]%=Mod;
  }

  FOR(i,0,q){
    ll ans=1;
    ll x,d,n;
      cin>>x>>d>>n;

    if(n>=Mod){
      cout<<0<<endl;
      continue;
    }

    if(d==0){
      cout<<modpow(x,n,Mod)<<endl;
      continue;
    }

    ll dm=modpow(d,Mod-2,Mod);   

    ans*=table[(x*dm+n-1)%Mod];
    ans%=Mod;
    if((x*dm+n-1)%Mod<n-1){
      ans*=table[Mod];
      ans%=Mod;

      ans*=retable[Mod-n-1-(x*dm+n-1)%Mod];
      ans%=Mod;
    }

    ans*=retable[(x*dm-1+Mod)%Mod];
    ans%=Mod;

    ans*=modpow(d,n,Mod);
    ans%=Mod;
    cout<<ans<<endl;
  }
}

