		}
		x /= d;
		if (x.value+n.value-1 > MOD)
		{
			cout << 0 << endl;
			continue;
		}
		Int ans = acc[(x.value+n.value-1)%MOD] / acc[x.value-1] * pow(d, n.value);
		cout << ans << '\n';
	}
}

