int expmod(int a, int b, int mod) {
	int rlt = 1;
	for (a %= mod; b; a = 1ll * a * a % mod, b >>= 1) if (b & 1) rlt = 1ll * rlt * a % mod;
	return rlt;
}

const int mod = 1000003;

int n, x, d;
#define N 1000003
int fac[N], rfac[N], ri[N];
void init() {
	fac[0] = 1;
	for (int i = 1; i < N; i ++) fac[i] = 1ll * fac[i-1] * i % mod;
	rfac[0] = rfac[1] = 1, ri[1] = 1;
   	for(int i = 2; i < N; i ++){
      		int t = mod / i;
      		ri[i] = (1ll * t * (mod - ri[mod % i])) % mod;
      		rfac[i] = (1ll * rfac[i-1] * ri[i]) % mod;
   	}
}


int main() {
	init();
	int q;
	scanf("%d", &q);
	while (q --) {
		scanf("%d%d%d", &x, &d, &n);
		int ans;
		if (d == 0) ans = expmod(x, n, mod);
		else {
			int now = 1ll * x * expmod(d, mod - 2, mod) % mod;
			if (mod <= now + n - 1) ans = 0;
			else {
				ans = 1ll * fac[now+n-1] * rfac[now-1] % mod * expmod(d, n, mod) % mod;
			}
		}
		printf("%d\n", ans);
	}
	return 0;
}

