// 5*10^10なので流石にきつい
int main(){
    int q;
    scanf("%d", &q);

    while(q-- > 0){
        ll x, d;
        int n;
        scanf("%lld %lld %d", &x, &d, &n);
        if(n >= 1000003){
            printf("0\n");
            continue;
        }
        int l = n/2-1, r = n/2+1;
        ll cnt = 1;
        ll piv = x + d*(n/2);
        piv %= mod;
        ll ans = piv, acc = piv*piv;
        while(l >= 0 && r <= n-1){
            ll tmp = cnt*cnt%mod*d%mod*d%mod;
            ans = ans * ((piv*piv-tmp+mod)%mod) % mod;
            l--, r++, cnt++;
            if(ans == 0)    break;
        }
        ll tmp = cnt*d%mod;
        if(l == 0)      ans = ans*((piv-tmp+mod)%mod)%mod;
        if(r == n-1)    ans = ans*((piv+tmp)%mod)%mod;
        printf("%lld\n", ans);
    }
    return 0;
}

