    if (n >= 1000003) {
      cout << 0 << endl;
      continue;
    }
    if (d == 0) {
      cout << mod_pow(x, n) << endl;
      continue;
    }
    ll xl = (x + (n - 1) * d);
    ll k1 = x * mod_inverse(d) % MOD;
    ll k2 = xl * mod_inverse(d) % MOD;
    if (k1 > k2 || k1 == 0 || k2 == 0) {
      cout << 0 << endl;
      continue;
    }
    ll ans = fact[k2] * rfact[k1 - 1] % MOD;
    ans = ans * mod_pow(d, k2 - k1 + 1) % MOD;
    cout << (ans + MOD) % MOD << endl;
  }
}

