using namespace std;
typedef long long ll;

int Q;

ll inf = 1000003;
ll fact[1000010] = {0};
ll inv[1000010] = {0};

ll mult(ll n, ll m){
	if(m==1) return n%inf;
	else if(m%2==0){
		ll t = mult(n,m/2);
		return (t*t)%inf;
	}else{
		ll t = mult(n,m-1);
		return (t*n)%inf;
	}
}

void factorial(ll N){
	for(ll i=0;i<=N;i++){
		if(i==0){
			fact[i] = 1;
			inv[i] = 1;
		}
		else{
			fact[i] = (i*fact[i-1])%inf;
			inv[i] = mult(fact[i],inf-2);
		}
	}
}

ll mod_fact(ll n,ll p,ll& e){
    e = 0;
    if(n==0) return 1;
    ll res = mod_fact(n/p,p,e);
    e += n/p;
    if(n/p%2!=0) return res*(p-fact[n%p])%p;
    else return res*fact[n%p]%p;
}

int main(){
    cin >> Q;
    factorial(inf);
    ll x,d,n;
    for(int i=0;i<Q;i++){
        cin >> x >> d >> n;
        ll ans = mult(d,n);
        if(d==0){
            cout << mult(x,n) << endl;
            continue;
        }
        ll s = x*mult(d,inf-2)%inf;
        ll r = s+n-1,l = s-1;
        if(r/inf-l/inf>=1) ans = 0;
        else{
            (ans *= fact[r%inf])%=inf;
            if(l!=0) (ans *= inv[l])%=inf;
        }
        cout << ans << endl;
    }    
}

