template<typename T>
T power(T a,long long k){
    if(k==0)return T(1);
    T sqrta=power(a,k/2);
    return sqrta*sqrta%p*((k%2==0)?1:a)%p;
}
long long ext_gcd(long long a,long long b,long long &x,long long &y){
    if(b==0){x=1;y=0;return a;}
    long long q=a/b, g=ext_gcd(b,a-q*b,x,y), z=x-q*y;
    x=y; y=z;
    return g;
}
long long inv(long long value){
    long long x,y;
    ext_gcd(value,p,x,y);
    return (x+p)%p;
}
