ll powll(ll x, ll y){
    x %= mod;
    ll res = 1LL;
    while(y){
        if (y & 1LL)
            res *= x;
        res %= mod;
        x = (x*x) % mod;
        y >>= 1LL;
    }
    return res;
}

ll divll(ll x, ll y){
    x %= mod;
    return (x * powll(y,mod-2)) % mod;
}

ll nPr(ll n, ll r){
    if (n < r || r < 0) return 0;
    return mul(fact[n], invf[n-r]);
}

ll nCr(ll n, ll r){
    if (n < r || r < 0) return 0;
    return mul(mul(fact[n], invf[r]), invf[n-r]);
}

ll calc(ll x, ll d, ll n){
    if (d == 0) return powll(x, n);
    if (x == 0) return 0;
    if (n >= mod) return 0;
    ll s = divll(x, d);
    ll t = divll(x + (n - 1) * d, d);
    if (s > t) return 0;
    ll ret = powll(d, n);
    ret = (ret * nPr(t, t - s + 1)) % mod;
    return ret;
}

