const int MAXN = (1 << 21);
const int mod = 1000003;

int pw(int x, int p)
{
	int r = 1;
	while(p)
	{
		if(p & 1) r = r * 1ll * x % mod;
		x = x * 1ll * x % mod;
		p >>= 1;
	}

	return r;
}

int inv(int x) { return pw(x, mod - 2); }

struct node
{
	int p;

	node() {p = 1;}
	node(int val)
	{
		p = val;
	}
};

node temp, broken;

node merge(node l, node r)
{
	temp.p = l.p * 1ll * r.p % mod;
	return temp;
}

struct segment_tree
{
	node tr[4 * MAXN];

	void init(int l, int r, int idx)
	{
		if(l == r)
		{
			tr[idx] = node(l % mod);
			return;
		}

		int mid = (l + r) >> 1;
		init(l, mid, 2 * idx + 1);
		init(mid + 1, r, 2 * idx + 2);

		tr[idx] = merge(tr[2 * idx + 1], tr[2 * idx + 2]);
	}

	node query(int qL, int qR, int l, int r, int idx)
	{
		if(l > qR || r < qL)
			return broken;

		if(qL <= l && r <= qR)
			return tr[idx];

		int mid = (l + r) >> 1;
		return merge(query(qL, qR, l, mid, 2 * idx + 1), query(qL, qR, mid + 1, r, 2 * idx + 2));
	}
};

segment_tree t;

void prepare()
{
	t.init(0, 2 * mod + 42, 0);
}

int x, d, n; 

void read()
{
	cin >> x >> d >> n;
}

void solve()
{
	if(d == 0)
	{
		cout << pw(x, n) << endl;
		return;
	}

	if(n >= mod)
	{
		cout << 0 << endl;
		return;
	}

	int ans = pw(d, n), dd = inv(d);
	int st = x * 1ll * dd % mod;
	ans = ans * 1ll * t.query(st, st + n - 1, 0, 2 * mod + 42, 0).p % mod;
	cout << ans << endl;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	prepare();

	int T;
	cin >> T;
	while(T--)
	{
		read();
		solve();
	}

	return 0;
}

