//Factorial Mod
vector<long long> FactorialMod(long long N, long long mod) {
    vector<long long> res(N + 1, 1);
    for (long long i = 1; i <= N; ++i) res[i] = (res[i - 1] * i) % mod;
    return res;
}


//Pow_Mod O(log(n))
long long Pow_Mod(long long x, long long n, long long mod) {
    long long res = 1;
    for (; n > 0; n >>= 1, (x *= x) %= mod) if (n & 1) (res *= x) %= mod;
    return res;
}

//Inv_Mod O(log(mod))
long long Inv_Mod(long long x, long long mod){
	return Pow_Mod(x,mod-2,mod); 
}

int main() {
	SPEED
	ll mod = 1000003;
	auto F = FactorialMod(2*mod,mod);

	int Q; cin >> Q;
	while(Q--) {
		ll x,d,n;
		cin >> x >> d >> n;
		if(d==0){
			cout << Pow_Mod(x,n,mod) << endl;
			continue;
		}
		ll ans = 1, y = (x*Inv_Mod(d,mod))%mod;
		if(y+n-1>=mod || x==0){
			cout << 0 << endl;
			continue;
		}
		(ans *= F[y+n-1]) %= mod;
		(ans *= Inv_Mod(F[y-1],mod)) %= mod;
		(ans *= Pow_Mod(d,n,mod)) %= mod;
		cout << ans << endl;		
	}
	return 0;
}

