inline int add(int a, int b, int mod = MOD) {
  a += b;
  if (a >= mod) a -= mod;
  return a;
}
inline int sub(int a, int b, int mod = MOD) {
  a -= b;
  if (a < 0) a += mod;
  return a;
}
inline int mul(int a, int b, int mod = MOD) {
  return int((long long) a * b % mod);
}
inline int mpow(int base, long long ex, int mod = MOD) {
  int res = 1;
  while (ex > 0) {
    if (ex & 1) res = mul(res, base, mod);
    base = mul(base, base, mod);
    ex >>= 1;
  }
  return res;
}
inline int inv(int a, int mod = MOD) {
  return mpow(a, mod - 2, mod);
}
int32_t main() {

  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  vector<int> fac(MOD);
  fac[0] = 1;
  for (int i = 1; i < MOD; ++i) {
    fac[i] = mul(i, fac[i - 1]);
  }
  int q; cin >> q;
  while (q--) {
    int x, d, n, ans;
    cin >> x >> d >> n;
    if (x == 0) {
      cout << 0 << '\n';
      continue;
    }
    if (d == 0) {
      cout << mpow(x, n, MOD) << '\n';
      continue;
    }
    int b = MOD - x;
    int lim = mul(b, inv(d));
    if (n > lim) {
      ans = 0;
    } else {
      ans = mpow(d, n, MOD);
      int a = mul(x, inv(d));
      if (a + n - 1 < MOD) {
        ans = mul(ans, fac[a + n - 1]);
        ans = mul(ans, inv(fac[a - 1]));
      } else {
        ans = 0;
      }
    }
    cout << ans << '\n';
  }

  return 0;
}

