void setkj() {
	kj[0] = 1;
	for (int i = 1; i <= mod; i++)kj[i] = kj[i - 1] * i%mod;
	kji[0] = kji[1] = 1;
	for (int i = 2; i < mod; i++) {
		kji[i] = mod - (kji[mod%i] * (mod / i)) % mod;
