static SDWORD getContinuousProduct(
    SDWORD lStart,
    SDWORD lNum)
{
    if (0 == (lStart % DIVISOR)) {
        return 0;
    }
    if ((lStart / DIVISOR) != ((lStart + lNum - 1) / DIVISOR)) {
        return 0;
    }

    SDWORD lRet = divMod(s_alFactoryTable[lStart + lNum - 1], s_alFactoryTable[lStart - 1]);
    return lRet;
}


