//Math/ModInt
template<long long mod = 1000000007>
struct modint{
	long long a;

	constexpr modint() : a(0){}
	constexpr modint(long long t){
		a = t % mod;
		if(a < 0) a += mod;
	}

	constexpr operator long long() const{ return a; }

	constexpr bool operator==(const modint &x) const{ return a == x.a; }
	constexpr bool operator!=(const modint &x) const{ return a != x.a; }

	constexpr modint operator-() const{ return modint(a ? (mod - a) : 0); }
	constexpr modint operator~() const{ return pow(mod - 2); }

	constexpr modint operator+(const modint &x) const{ return modint(*this) += x; }
	constexpr modint operator-(const modint &x) const{ return modint(*this) -= x; }
	constexpr modint operator*(const modint &x) const{ return modint(*this) *= x; }
	constexpr modint operator/(const modint &x) const{ return modint(*this) /= x; }

	constexpr modint &operator+=(const modint &x){
		a += x.a;
		if(a >= mod) a -= mod;
		return *this;
	}
	constexpr modint &operator-=(const modint &x){
		a -= x.a;
		if(a < 0) a += mod;
		return *this;
	}
	constexpr modint &operator*=(const modint &x){
		a = a * x.a % mod;
		return *this;
	}
	constexpr modint &operator/=(const modint &x){
		a = a * (~x).a % mod; 
		return *this;
	}

	constexpr modint &operator++(){ return (*this) += 1; }
	constexpr modint &operator--(){ return (*this) -= 1; }
	constexpr modint &operator++(int){
		modint tmp = *this;
		(*this) += 1;
		return tmp;
	}
	constexpr modint &operator--(int){
		modint tmp = *this;
		(*this) -= 1;
		return tmp;
	}

	friend ostream &operator<<(ostream &os,const modint &x){
		return os << x.a;
	}
	friend istream &operator>>(istream &is,modint &x){
		long long t;
		is >> t;
		x = modint(t);
		return is;
	}

	constexpr modint pow(long long x) const{
		modint ret = 1,tmp = a;
		for(;x;tmp *= tmp,x >>= 1){
			if(x & 1) ret *= tmp;
		}
		return ret;
	}
};

//Math/Combination
template<class T>
struct Combination{
	vector<T> fact,factinv;
	Combination(int n) : fact(n + 1),factinv(n + 1){
		fact[0] = 1;
		for(int i = 1;i <= n;i++) fact[i] = fact[i - 1] * T(i);
		factinv[n] = ~fact[n];
		for(int i = n;i >= 1;i--) factinv[i - 1] = factinv[i] * T(i);
	}
	T nCr(int n,int r){
		if(r < 0 || n < r) return 0;
		return fact[n] * factinv[r] * factinv[n - r];
	}
};

const int MOD = 1000003;

signed main(){
	int q;
	scanf("%d",&q);
	Combination<modint<MOD>> comb(MOD - 1);
	for(int i = 0;i < q;i++){
		int x,d,n,a;
		scanf("%d %d %d",&x,&d,&n);
		modint<MOD> mx = x,md = d;
		a = mx / md;
		if(!d) printf("%d\n",mx.pow(n));
		else if(n >= MOD || a > (a + n - 1) % MOD) puts("0");
		else printf("%d\n",comb.fact[a + n - 1] * comb.factinv[a - 1] * md.pow(n));
	}
}

