typedef long long ll;
const ll mod = 1000003;

ll fact[mod] = { 1, };
ll fact_inv[mod] = { 1, };

inline ll get_pow(ll base, int pow)
{
	ll ret = 1;

	while (pow)
	{
		if (pow & 1) ret = (ret*base) % mod;
		base = (base*base)%mod;
		pow >>= 1;
	}

	return ret;
}

inline ll get_inv(ll num)
{
	return get_pow(num, mod - 2);
}

inline ll mod_mul(ll a, ll b)
{
	return (a*b) % mod;
}

void init()
{
	for (int i = 1; i < mod; ++i) fact[i] = (fact[i - 1] * i) % mod;
	fact_inv[mod - 1] = get_inv(fact[mod - 1]);
	for (int i = mod - 2; i >= 1; --i) fact_inv[i] = (fact_inv[i + 1] * (i + 1)) % mod;
}

int main()
{
	init();

	int Q;

	scanf("%d", &Q);

	for (int i = 0; i < Q; ++i)
	{
		int x, d, n;

