		if (d%mod == 0) printf("%lld\n", get_pow(x, n));
		else
		{
			if (n >= mod) printf("0\n");
			else
			{
				ll k = mod_mul(mod - x, get_inv(d));

				if (n >= k) printf("0\n");
				else
				{
					ll temp = mod_mul(mod_mul(get_pow(d, n), fact[k]), fact_inv[k - n]);
					if (n & 1) temp = mod - temp;
					printf("%lld\n", temp);
				}
			}
		}
	}

	return 0;
}

