ll modpow(ll a, ll n){
  if(n == 0) return 1;
  if(n % 2 == 0) return modpow((a * a) % mod, n/2);
  return (a * modpow(a, n-1) % mod);
}

ll ext_gcd(ll a, ll b, ll &x, ll &y){ // ax+by=gcd(a,b)なるx,y,gcdを返す
  if(b == 0){
    x = 1; y = 0; return a;
  }
  ll q = a / b;
  ll g = ext_gcd(b, a-q*b, x, y);
  ll z = x - q * y;
  x = y; y = z;
  return g;
}

ll invmod(ll a, ll m){ // a^-1(mod m)を返す
  ll x, y;
  ext_gcd(a,m,x,y);
  x %= m;
  if(x < 0) x += m;
  return x;
}

