      }
    }
    else {
      ll num = (x*inv(d))%MOD;
      ll dn = 1, nn = d;
      rep(i,30) {
        if (n&(1<<i)) { dn *= nn; dn %= MOD; }
        nn *= nn; nn %= MOD;
      }
