        cin >> v[i].second.first >> v[i].first >> v[i].second.second.first;
        v[i].second.second.second = i;
    }
    sort(v.begin(), v.end());
    vector<ll> ans(q);
    vector<pair<ll, ll>> memo(mod);
    REP(i, q){
        ll x = v[i].second.first, d = v[i].first, n = v[i].second.second.first, idx = v[i].second.second.second;
        if(x == 0){
            ans[idx] = 0;
            continue;
        }
        if(n >= mod){
            ans[idx] = 0;
            continue;
        }
        if(d == 0){
            ans[idx] = POW(x, n, mod);
            continue;
        }
        if(d == 1){
            if(x + n - 1 >= mod){
                ans[idx] = 0;
                continue;
            }
            ans[idx] = R[x + n - 1] / R[x - 1];
            continue;
        }

        ll t1 = (mod - x) % d, t2 = ((d - t1) + 1) % d, t3 = (x + t2 * mod) / d + 1;
        if(t3 <= n){
            ans[idx] = 0;
            continue;
        }

        if(memo[x].second == x){
            ans[idx] = memo[x].first;
            continue;
        }

        ll xx = x;
        for(ll j = 1; j < n; j++){
            xx *= (x + d * j);
            xx %= mod;
        }
        memo[x] = {xx, x};
        ans[idx] = xx;
    }

    REP(i, q){
        cout << ans[i] << endl;
    }
}

