typedef long long lint;
typedef tuple<int, int, int> T;

const lint MOD = (lint)1e6 + 3;
vector<lint> fact, fact_inv, inv;

T ExtendedGcd(int a, int b){
    if(b==0) return T(1, 0, a);
    int x, y, g; tie(x, y, g) = ExtendedGcd(b, a % b);
    return T(y, x-a/b*y, g);
}

void mod_add(lint &a, lint b){
    a = (a+b) % MOD;
}

void mod_sub(lint &a, lint b){
    a = ((a-b)%MOD+MOD) % MOD;
}

lint mod_pow(lint n, lint x){
    lint res = 1;
    while(x){
        if(x&1) res = res * n % MOD;
        x >>= 1; n = n * n % MOD;
    }
    return res;
}

void createFactInvMod(int n){
    fact.resize((unsigned int)n+1); fact_inv.resize((unsigned int)n+1);
    fact[0] = 1;
    for(int i=1;i<=n;i++) fact[i] = fact[i-1] * i % MOD;
    fact_inv[n] = mod_pow(fact[n], MOD-2);
    for(int i=n-1;0<=i;i--) fact_inv[i] = fact_inv[i+1] * (i+1) % MOD;
}

void createInvMod(int n){
    inv.resize((unsigned int)n+1);
    createFactInvMod(n);
    inv[0] = 0;
    for(int i=1;i<=n;i++) inv[i] = fact[i-1] * fact_inv[i] % MOD;
}

lint solve(lint x, lint n){
    if(MOD<x+n || x==0) return 0;
    return fact[x+n-1] * fact_inv[x-1] % MOD;
}

int main(){
    ios::sync_with_stdio(false), cin.tie(nullptr);
    int Q; cin >> Q;
    createInvMod(MOD-1);
    while(Q--){
        lint x, d, n; cin >> x >> d >> n;
        if(d==0) cout << mod_pow(x, n) << endl;
        else {
            lint y = x * inv[d] % MOD;
            printf("%lld\n", solve(y, n)*mod_pow(d, n)%MOD);
        }
    }
    return 0;
}

