long long mod_pow(ll a,ll b){
	long long ret = 1;
	long long c = a;
	for(int i = 0;i <= 60;i++){
		if(b & (1LL << i))ret = (ret * c) % MOD;
		c = (c * c) % MOD;
	}
	return ret;
}

//ａをbで割る
long long mod_div(long long a,long long b){
	long long tmp = MOD - 2,c = b,ret = 1;
	while(tmp > 0){
		if(tmp & 1){
			ret *= c;ret %= MOD;
		}
		c *= c;c %= MOD;tmp >>= 1;
	}
	return a*ret%MOD;
}

ll fact[1111111];

ll func(ll x, ll n){
	if(n > MOD)return 0;

	ll l = max(0LL, x - 1);
	ll r = (x + n - 1) % MOD;
	if(l > r)return 0;
	else return mod_div(fact[r], fact[l]);
}

