const long long MOD=1000003;

template<typename T>
T modinv(T a,T m=1000003){
    T b=m,u=1,v=0;
    while(b!=0){
        T t=a/b;
        a-=t*b;
        std::swap(a,b);
        u-=t*v;
        std::swap(u,v);
    }
    u%=m;
    if(u<0)u+=m;
    return u;
}

template<typename T>
T modpow(T a,T n,T mod=1000003){//(a^n)%MOD
    T ret=1;
    while(n>0){
        if((n&1)!=0){//n%2==1
            ret=ret*a%mod;
        }
        a=a*a%mod;
        n=n/2;
    }
    return ret;
}

int main(){
    int q;
    cin>>q;
    vector<long long> factorial(MOD,1);
    for (int i = 1; i < MOD; ++i) {
        factorial[i]=factorial[i-1]*i%MOD;
    }
    for (int T = 0; T < q; ++T) {
        long long x,d,n;
        cin>>x>>d>>n;
        long long invd=modinv(d);
        long long a=x*invd%MOD;
        long long shi=factorial[a-1];
        long long ue=factorial[(a+n)%MOD-1];
        shi=modinv(shi);
        long long seki=ue*shi%MOD;
        long long ans=modpow(d,n)*seki%MOD;
        cout<<ans<<endl;
    }
    return 0;
}

