ll modi(ll a,ll m){
  ll b=m,u=1,v=0;
  while(b){
    ll t=a/b;
    a-=t*b;
    swap(a,b);
    u-=t*v;
    swap(u,v);
  }
  u%=m;
  if(u<0) u+=m;
  return u;
}
ll modp(ll a,ll b,ll m){
  if(b==0) return 1;
  if(b%2) return modp(a,b-1,m)*a%m;
  return modp(a,b/2,m)*modp(a,b/2,m)%m;
}
