  vector<fp> fact, finv;
  std::tie(fact, finv) = build_factorial<fp>(mod);

  auto solve = [&](i64 x, i64 n) {
    if(x == 0 || x + n - 1 >= mod) return fp(0);
    return fact[x + n - 1] * finv[x - 1];
  };

  while(Q--) {
    i64 x, d, n;
    cin >> x >> d >> n;
    if(d == 0) {
      cout << fp(x).pow(n) << endl;
    }
    else {
      cout << solve((fp(x)/fp(d)).value(), n) * fp(d).pow(n) << endl;
    }
  }
}

