int Log2u(int num){
  //自分含むより高い次にくる2^NとなるNを返す
  int rsznum=num-1;
  int beki=0;
  for(int i=0;i<32;i++){
    if (rsznum==0){
      beki=i;
      break;
    }
    rsznum/=2;
  }
  return beki;
}


ll Makestk_f0(ll a1,ll a2){
  return a1*a2%MOD;//●●●●●●●●●●●●●●●●●●●●●●●
}

void Makestk(ll num){
  int beki=Log2u(num)+1;
  int rsznum=1<<beki;
  stk.resize(rsznum);
  //初期値設定●●●●●●●●●●●●●●●●●●●●●●●
  for(int i=0;i<num;i++){
    stk[i]=(ll)i;
  }
  //初期値0埋め●●●●●●●●●●●●●●●●●●●●●●●
  for(int i=num;i<rsznum/2;i++){
    stk[i]=1LL;
  }

  //2こ1にまとめていく。1レイヤーごと半分になっていく
  //初期レイヤー含めずあとbeki個必要
  int ofst=rsznum/2;
  int ofstp=0;//1個まえのofst
  for(int j=beki-2;j>=0;j--){
    int bk1=1<<j;
    for(int i=0;i<bk1;i++){
      stk[ofst+i]=Makestk_f0(stk[ofstp+i*2],stk[ofstp+i*2+1]);
    }
    ofstp=ofst;
    ofst+=bk1;
  }
}

//stk前半データに対し0～n-1までのリダクション施行した結果を返す
ll Reduc0(int n){
  int nn=n;
  ll ans=1LL;//●●●●●●●●●●●●●●●●●●●●●●●
  int sz=stk.size()/2;
  int ofst=0;
  int beki=Log2u(sz);
  for(;nn>0;nn>>=1){
    if (nn%2==1){
        ans=Makestk_f0(ans,stk[ofst+nn-1]);
    }
    ofst+=1<<beki;
    beki--;
  }
  return ans;
}

//stk前半データに対しl～r-1までのリダクション施行した結果を返す
ll Reduc1(int l,int r){
  int nn=r;
  int mm=l;
  ll ans=1LL;//●●●●●●●●●●●●●●●●●●●●●●●
  int sz=stk.size()/2;
  int ofst=0;
  int beki=Log2u(sz);
  int i=0;
  for(int i=0;(nn+mm)>0;i++){
    if (nn%2==1){
        if (nn-1>=mm){
          ans=Makestk_f0(ans,stk[ofst+nn-1]);
          nn--;
        }
    }

    if (mm%2==1){
        if (mm<nn){
          ans=Makestk_f0(ans,stk[ofst+mm]);
          mm++;
        }
    }

    nn>>=1;
    mm>>=1;
    ofst+=1<<(beki-i);
  }
  return ans;
}
