    ios_base::sync_with_stdio(false);
    cin.tie(0);

    vector<mint> accum(mod + 1, 0);
    accum[0] = 1;
    for (int i = 0; i < mod; ++i) {
        accum[i + 1] = accum[i] * (i + 1);
    }

    li q;
    cin >> q;
    for (int i = 0; i < q; ++i) {
        li x, d, n;
        cin >> x >> d >> n;

        if (d == 0) {
            cout << mint(x).pow(n).x << endl;
