        mint z = y + n - 1;

        if (z.x < y.x || y.x == 0) {
            cout << 0 << endl;
            continue;
        }

        cout << (accum[z.x] / accum[y.x - 1] * mint(d).pow(n)).x << endl;
    }
    return 0;
}

