		if (d == 0) {
			ans = mod_pow(x, n);
			cout << ans << endl;
			continue;
		}
		ll tmp = x * mod_inv(d) % mod;

		ans = fact[tmp + n - 1] * mod_inv(fact[tmp - 1]) % mod;
		ans = ans * mod_pow(d, n) % mod;
		cout << ans << endl;

	}

	return;

}

