const int MOD = 1000003;
using ME = IntMod<MOD>;

int Q;
int sub(int x, int d, int n) {
	if (x == 0) return 0;
	if (d == 0) {
		return ME(x).Pow(n).Get_value();
	}

	int e = (ME(x) / ME(d)).Get_value();

	int k = (e - 1) / MOD;
	int numer = e + n - 1 - k * MOD;
	int denom = e - 1 - k * MOD;
	if (numer >= MOD) return 0;
	return (ME::Fact(numer) / ME::Fact(denom) * ME(d).Pow(n)).Get_value();
}

