using namespace std;

long long fac_dic[1000010], fac_inv_dic[1000010], inv_d[1000010];


long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

// a^{-1} mod を計算する
long long modinv(long long a, long long mod) {
    return modpow(a, mod - 2, mod);
}

void yield_fac(){
    fac_dic[0]=1;
    fac_dic[1]=1;
    fac_inv_dic[0]=0;
    fac_inv_dic[1]=1;
    inv_d[0]=1;
    inv_d[1]=1;
    for(int i=2;i<1000010;i++){
        fac_dic[i]=(fac_dic[i-1]*i)%MOD;
        fac_inv_dic[i]=modinv(fac_dic[i], MOD);
        inv_d[i]=modinv(i,MOD);
    }
}

void solve(long long tmpx, long long tmpd, long long tmpn){
    long long ans=0;
    long long xd = (tmpx * inv_d[tmpd])%MOD;
    if(tmpd==0){
        ans=modpow(tmpx, tmpn, MOD);
    }
    else{
        if(xd<= 1000003 && xd <= xd+tmpn-1){
            ans=0;
        }
        else{
            ans=(((modpow(tmpd, tmpn, MOD)*fac_dic[(xd+tmpn-1)])%MOD)*fac_inv_dic[xd-1])%MOD;
        }
    }
    cout << ans << endl;
}


int main(){
    int q;
    cin >> q;
    yield_fac();
    for(int i=0;i<q;i++){
        long long tmpx, tmpd, tmpn;
        cin >> tmpx >> tmpd >> tmpn;
        solve(tmpx, tmpd, tmpn);
    }
}

