            if(tmp+n-1 >= 1000003) {
                cout << 0 << "\n";
            } else {
                mint co = combi(tmp+n-1, n);
                mint pw = mint(d).pow(n);
                cout << co * pw << "\n";
            }
        }
    }

    return 0;
}

