    return res;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int q;
    cin >> q;

    vector<ll> f(MOD, 1);
    for (int i = 1; i < MOD; i++) f[i] = f[i - 1] * i % MOD;

    for (int i = 0; i < q; i++) {
        ll x, d, n;
        cin >> x >> d >> n;
        if (n == 1) {
            cout << x % MOD << endl;
            continue;
        } else if (d == 0) {
            cout << modpow(x, n) % MOD << endl;
            continue;
        }

        ll hoge = x * modpow(d, MOD - 2) % MOD;
        ll foo = hoge + n - 1;
        if (hoge == 0 || foo - hoge >= MOD) {
            cout << 0 << endl;
        } else {
            foo %= MOD;
            if (foo == 0 || foo < hoge) cout << 0 << endl;
            else {
                cout << f[foo] * modpow(f[hoge - 1], MOD - 2) % MOD * modpow(d, n) % MOD << endl;
            } 
        }
    }
    return 0;
}

