int main() {
    int Q;
    cin >> Q;
    for (int qi : range(Q)) {
        unused_var(qi);
        int x, d, n;
        cin >> x >> d >> n;
        if (n >= mod) {
            cout << 0 << endl;
        }
        else {
            ModInt dx = ModInt(x) / d;
            if (*dx == 0 || (*dx) + n - 1 >= mod) {
                cout << 0 << endl;
            }
            else {
                cout << *(factorial::permutation((*dx) + n - 1, n)
                          * pow(ModInt(d), n))
                     << endl;
            }
        }
    }
    return 0;
}

