typedef long long ll;

const ll MOD = 1000003;

ll kuri2(ll base,ll kata)
{
	ll ret=1;
	if(kata==0)
		return ret;
	else if(kata&1){
		ret*=base;
		ret%=MOD;
	}
	ret*=kuri2(base*base%MOD,(kata>>1));
	ret%=MOD;
	return ret;
}

//階乗を高速に求める
ll recfact(ll start,ll n)
{
	ll i;
	//16以下は普通に求める
	if(n<=16){
		ll r=start;
		for(i=1;i<n;i++)
		{
			r*=(start+i);
			r%=MOD;
		}
		if(r<0)
			r+=MOD;
		return r;
	}
	i=n/2;
	return recfact(start,i)*recfact((start+i)%MOD,n-i)%MOD;
}

