ll solve(int x, int d, int n){
    if (d == 0) return POW(x, n);

    ll y = DIV(x, d);
    ll ans = 1;
    for (int i=0; i<n; ++i) {
        if (y == 0) return 0;
        (ans *= y) %= MOD;
        (y += 1) %= MOD;
    }
    ans = MUL(ans, POW(d, n));
    return ans;
}

