ll power(ll x,ll y)
{
    ll res=1;

    while(y>0)
    {
        if(y&1)
            res=res*x;
        res%=m;
        y=y>>1;
        x=x*x;
        x%=m;
    } 
    return res; 
}
ll inv(ll x)
{
    return power(x,m-2);
}
