    while (q--) {
        int x, d, n;
        cin >> x >> d >> n;

        int k = 1ll * (Z - x) * inv(d) % Z;
        int ans = k < n ? 0 : 1ll * fp(d, n) * fac[Z-k+n-1] % Z * inv(fac[Z-k-1]) % Z;
        cout << ans << endl;
    }

    return 0;
}

