const long long MOD = 1000003;

long long fac[MOD + 10];
long long ifac[MOD + 10];
long long inv[MOD + 10];

long long exp(int x, int k) {
    if(k == 0) return 1;
    long long tmp = exp(x, k/2);
    if(k % 2 == 1) return x * tmp % MOD * tmp % MOD;
    return tmp * tmp % MOD;
}

long long solve(int x, int d, int n) {
    if (d == 0) return exp(x, n);

    // pre-check
    long long v = MOD - x;
    long long tt = v * inv[d] % MOD;
    if (tt <= n) return 0;

    long long xd = (long long)x * inv[d] % MOD;
    long long tp = (xd + n - 1) % MOD;
    long long bt = ((xd - 1) % MOD + MOD) % MOD;
    return fac[tp] * ifac[bt] % MOD * exp(d, n) % MOD;
}

long long brute(int x, int d, int n) {
    long long tmp = 1;
    long long nn = x;
    while(n--) {
        tmp *= nn;
        tmp %= MOD;
        nn += d;
    }
    return tmp;
}

void test() {
    int cnt = 100;
    while(cnt--) {
        int x, d, n;
        x = rand() % MOD;
        d = rand() % MOD;
        n = rand() % 1000000000 + 1;
        long long a = solve(x, d, n);
        long long b = brute(x, d, n);
        if(a != b) {
            printf("::%d %d %d || %lld %lld\n", x, d, n, a, b);
        }
    }
}

int main() {
    srand(time(0));

    fac[0] = 1;
    ifac[0] = 1;
    for(int i = 1 ; i < MOD ; i++) {
        fac[i] = fac[i-1] * i % MOD;
        ifac[i] = exp(fac[i], MOD-2);
        inv[i] = exp(i, MOD-2);
    }

    int T;
    scanf("%d", &T);
    while(T--) {
        int n, m, k;
        scanf("%d %d %d", &n, &m, &k);
        printf("%lld\n", (solve(n, m, k) % MOD + MOD) % MOD);
    }

    // test();

    return 0;
}

