#include <bits/stdc++.h>
#define N 1000003
#define MAX 1100000
using namespace std;

long long factorial[MAX] = {0}, finverse[MAX] = {0},
          inverse[MAX] = {0};

void smodfact() {
  factorial[0] = factorial[1] = 1;
  finverse[0] = finverse[1] = 1;
  inverse[1] = 1;
  for(int i = 2; i < MAX; ++i) {
    factorial[i] = factorial[i - 1] * i % N;
    inverse[i] = N - (inverse[N % i] * (N / i)) % N;
    finverse[i] = finverse[i - 1] * inverse[i] % N;
  }
}

long long calccomb(long long n, long long k) {
  if(n == k && n == 0) return 1;
  if(n < 0 || k < 0 || n < k) return 0;
  return factorial[n] * finverse[k] % N * finverse[n - k] %
         N;
}

long long n, d, q, x;
long long memo[64] = {0};

long long solve();
long long calc(long long now);

int main() {
  smodfact();
  cin >> q;
  for(int i = 0; i < q; ++i) {
    cin >> x >> d >> n;
    cout << solve() << endl;
  }
  return 0;
}

long long solve() {
  long long ans = 0;
  if(d == 0)
    ans = calc(x);
  else {
    x *= inverse[d];
    x %= N;
    ans = factorial[(x + n + N - 1) % N] *
          finverse[(x + N - 1) % N] % N * calc(d) % N;
  }
  return ans;
}

long long calc(long long now) {
  long long ans = 1, nown = n;
  memo[0] = now;
  for(long long i = 1; i < 31; ++i)
    memo[i] = memo[i - 1] * memo[i - 1] % N;
  for(long long i = 30; i >= 0; --i)
    if((1 << i) <= nown) {
      nown -= 1 << i;
      ans *= memo[i];
      ans %= N;
    }
  return ans;
}

