int main() {
    const i64 mod = 1000003;;

    vector<i64> inv(mod + 1);
    vector<i64> fact(mod + 1);
    vector<i64> fact_inv(mod + 1);

    for (i64 i = 1; i < mod; i++) {
        inv[i] = (i == 1) ? 1 : (mod - (mod / i) * inv[mod % i] % mod);
    }

    fact[0] = 1;
    fact_inv[0] = 1;

    for(int i = 1; i < mod; ++i) {
        fact[i] = fact[i - 1] * i % mod;
        fact_inv[i] = fact_inv[i - 1] * inv[i] % mod;
    }

    int q;
    in(q);

    for (int i = 0; i < q; i++) {
        i64 x, d, n;
        in(x, d, n);

        i64 res;

        if (n >= mod) {
            out(0);
            continue;
        } else {
            res = fact[n];
        }

        x %= mod;
        d %= mod;


        i64 m_x = mod - (x % mod);
        i64 m_d = mod - (d % mod);
        i64 inv_d = inv[d % mod];

        i64 m = m_x * inv_d % mod;

        res = (res * fact[m] % mod * fact_inv[(m - n + mod) % mod] % mod * fact_inv[n % mod]) % mod;

        i64 t = n;
        i64 base = m_d;

        while(t > 0) {
            if (t & 1) {
                res = res * base % mod;
            }

            base = base * base % mod;

            t >>= 1;
        }

        out(res);
    }
}

