void cominit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}

long long modpow(long long a,long long b)
{
	if (b==0LL)
	{
		return 1LL;
	}
	long long ans=modpow(a,b/2LL);
	ans*=ans;
	ans%=mod;
	if (b%2LL==1LL)
	{
		ans*=a;
		ans%=mod;
	}
	return ans;
}

