const int MOD = 1e6 + 3;

i64 powMod(i64 x, i64 n = MOD - 2) {
	i64 ret = 1;
	while(n) {
		if(n & 1) (ret *= x) %= MOD;
		(x *= x) %= MOD;
		n >>= 1;
	}
	return ret;
}

int main() {
	int q; scanf("%d", &q);

	std::vector<i64> fact(MOD + 1, 1), inv(MOD + 1, 1);
	for(i64 i = 0; i < (int)fact.size() - 1; i++) fact[i + 1] = fact[i] * (i + 1) % MOD;
	for(int i = 0; i < fact.size(); i++) inv[i] = powMod(fact[i]);

	while(q--) {
		i64 x, d, n; scanf("%lld%lld%lld", &x, &d, &n);

		i64 ans = 0;
		if(d == 0) ans = powMod(x, n);
		else {
			(x *= powMod(d)) %= MOD;

			if(MOD <= x + n - 1) ans = 0;
			else {
				ans = fact[x + n - 1];
				if(x) (ans *= inv[x - 1]) %= MOD;
				(ans *= powMod(d, n)) %= MOD;
			}
		}
		printf("%lld\n", ans);
	}

	return 0;
}

