const ll mod=1000003;
ll pow(ll x,ll y){
  if(y==0) return 1;
  ll res=pow(x,y/2);
  res*=res;
  res%=mod;
  if(y%2==1) res*=x;
  return res%mod;
}
ll gyaku(ll x){
  return pow(x,mod-2);
}
vector<ll> frac,gfrac;
void set_frac(ll n){
  frac.push_back(1);
  gfrac.push_back(1);
  for(ll i=1;i<=n;i++){
    frac.push_back(frac[i-1]*i%mod);
    gfrac.push_back(gyaku(frac[i]));
  }
  frac[0]=0;
  gfrac[0]=0;
}
ll nCr(ll n,ll r){
  ll res=frac[n]*gfrac[r]%mod;
  res*=gfrac[n-r];
  return res%mod;
}
ll solve(ll x,ll d,ll n){
  ll ans=pow(d,n);
  ll X=(x*gyaku(d))%mod;
  if(mod-X<=n) return 0;
  ans*=frac[(X+n-1)%mod];
  ans%=mod;
  ans*=gfrac[(X+mod-1)%mod];
  ans%=mod;
  return ans;
}
