i32 calc (i32 x, i32 d, i32 n) {
  if (d == 0) return mod_pow (x, n % (mod - 1));
  if (x == 0) return 0;
  i32 y = (i64) x * inv (d) % mod;
  if (y + n - 1 >= mod) return 0;
  return (i64) fact[y + n - 1] * iFact[y - 1] * mod_pow (d, n % (mod - 1)) % mod;
}

