const int Mod = 1000003;

long long div_mod(long long x, long long y, long long z)
{
	if (x % y == 0) return x / y;
	else return (div_mod((1 + x / y) * y - x, (z % y), y) * z + x) / y;
}

long long pow_mod(int n, int k)
{
	long long N, ans = 1;
	for (N = n; k > 0; k >>= 1, N = N * N % Mod) if (k & 1) ans = ans * N % Mod;
	return ans;
}

int main()
{
	int q, Q, x, d, n;
	scanf("%d", &Q);

	int i;
	long long fact[1000003], fact_inv[1000003];
	for (i = 1, fact[0] = 1; i < Mod; i++) fact[i] = fact[i-1] * i % Mod;
	for (i = Mod - 2, fact_inv[Mod-1] = div_mod(1, fact[Mod-1], Mod); i >= 0; i--) fact_inv[i] = fact_inv[i+1] * (i + 1) % Mod;

	long long y;
	for (q = 1; q <= Q; q++) {
		scanf("%d %d %d", &x, &d, &n);
		if (d == 0) {
			printf("%lld\n", pow_mod(x, n));
			continue;
		} else if (x == 0) {
			printf("0\n");
			continue;
		}

		y = div_mod(x, d, Mod);
		if (y + n > Mod) printf("0\n");
		else printf("%lld\n", fact[y+n-1] * fact_inv[y-1] % Mod * pow_mod(d, n) % Mod);
	}
	fflush(stdout);
	return 0;
}

