                            (x/d + n-1)P(n) * pow(d,n)
            */
            if(d==0){
                pw.println(bx.modPow(bn, BMOD));
                continue;
            }
            BigInteger blx = bx.multiply(bd.modInverse(BigInteger.valueOf(MOD)));
            // System.err.println(blx);
            BigInteger last = blx.add(bn).subtract(BigInteger.ONE).mod(BMOD);
            // System.err.println(last);
            if(last.compareTo(BMOD)>=0){
                pw.println(0);
                continue;
            }

            if(blx.compareTo(BigInteger.ZERO)<=0){
                pw.println(last.multiply(bd.modPow(bn, BMOD)).mod(BMOD));
                continue;
            }
            BigInteger perm = modfact[last.intValueExact()].multiply(modfact[last.subtract(bn).intValueExact()].modInverse(BMOD)).mod(BMOD);
            // System.err.println(perm);
            BigInteger ans = perm.multiply(bd.modPow(bn, BMOD)).mod(BMOD);
            pw.println(ans);
        }
        pw.flush();
    }

    public static void main(String[] args) {
        new Main();
    }
}

