		 * そこで、一部を削れないか考える
		 * 1. 埋め込むと通る(酷い)
		 * 実装が面倒なので一度投げてみる、コンパイラを信じる
		 *
		 */
		int Q = io.nextInt();
		long[] inv = new long[MOD];
		inv[1] = 1;
		for (int i = 2;i < MOD;++ i) inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
		while(Q-- > 0) {
			int x = io.nextInt(), d = io.nextInt(), n = io.nextInt();
			if (n >= MOD) { // 自明を省く
				io.println(0);
				continue;
			}
			if (d == 0) { // 同様に自明
				io.println(pow(x, n, MOD));
				continue;
			}
			if ((MOD - x) % d == 0 && (MOD - x) / d < n) { // これも自明
				io.println(0);
				continue;
			}
			long ans = 1;
			/*for (int i = 0;i < n;++ i) {
				ans *= x + i * d;
				ans %= MOD;
			}*/

			long r = ((MOD + 1) - x) * inv[d] % MOD + 1, d2 = MOD - d, l = (r + MOD - n) % MOD;
			long first = (1 + l * d2) % MOD;
			for (int i = 0;i < n;++ i) {
				ans *= first + i * d2;
				ans %= MOD;
			}
			io.println(ans);
		}
		io.flush();
	}

