import java.io.*;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.Function;

public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int Q = sc.nextInt();
        init();
        PrintWriter out = new PrintWriter(System.out);
        for (int i = 0; i < Q; i++) {
            int ans = solve(sc.nextInt(), sc.nextInt(), sc.nextInt());
            out.println(ans);
        }
        out.flush();
    }

    static int solve(int X, int D, int N) {
        if( D == 0 ) return pow(X, N);
        if( X == 0 ) return 0;
        if( N >= MOD ) return 0;

        // X/D, X/D+1...
        // MODをまたぐとそこで0になるのでそれは処理する
        int x = div(X, D);
        if( x == 0 ) return 0;
        if( x + N - 1 >= MOD ) return 0;

        // debug(pow(D, N), dn, mul(dn, pow(D, N)));

        // [x, x+n-1]の階乗
        return mul(pow(D, N), div(FACT[x+N-1], FACT[x-1]));
    }

    static int[] FACT;

    static void init() {
        FACT = new int[MOD];
        FACT[0] = 1;
        for (int i = 1; i < MOD-1; i++) {
            FACT[i] = mul(FACT[i-1], i);
        }
    }

    static int MOD = 1_000_003;

    static int pow(int base, int exp) {
        if( exp == 0 ) return 1;

        int ans = 1;
        base %= MOD;
        while( exp > 0 ) {
            if( (exp & 1) == 1 ) {
                ans = mul(ans, base);
            }

            base = mul(base, base);
            exp = exp >> 1;
        }
        return ans;
    }

    static int sub(int a, int b) {
        int c = a - b;
        if( c <= 0 ) c += MOD;
        return c;
    }

    static int div(int a, int b) {
        return mul(a, pow(b, MOD-2));
    }

    static int add(int a, int b) {
        int c = a + b;
        if( c >= MOD ) c %= MOD;
        return c;
    }

    static int mul(int a, int b) {
        long c = (long)a * b;
        if( c >= MOD ) c %= MOD;
        return (int)c;
    }

    static class FermatCombination {
        private final int size;
        private final int[] factorial; // n -> factorial(n)
        private final int[] inverse;   // n -> inverse(factorial(n))

        FermatCombination(int size) {
            this.size = size;
            factorial = new int[size + 1];
            inverse = new int[size + 1];

            init();
        }

        private void init() {
            factorial[0] = 1;
            factorial[1] = 1;
            inverse[0] = 1;
            inverse[1] = 1;
            for (int i = 2; i <= size; i++) {
                factorial[i] = mul(factorial[i-1], i);
                inverse[i] = pow(factorial[i], MOD - 2);
            }
        }

        int comb(int n, int k) {
            if( n > size ) throw new RuntimeException("wtf : size=" + size + " n=" + n);
            return mul(mul(factorial[n], inverse[k]), inverse[n - k]);
        }

        // 重複組み合わせ
        // k種類からn個選ぶ場合の数
        int hcomb(int k, int n) {
            return comb(k+n-1, n);
        }

        int group(int n, int g, int k) {
            // C(n, g) * C(n-g, g)... / k!
            // n! / (n-gk)! / g! ^ k / k!
            int ret = factorial[n];             // n!
            ret = mul(ret, inverse[n - g*k]);   // 1 / (n-gk)!
            ret = mul(ret, pow(inverse[g], k)); // 1 / (g! ^ k)
            ret = mul(ret, inverse[k]);         // 1 / k!
            return ret;
        }
    }

