    static class EProductOfArithmeticProgression {
        private static final int MOD = 1_000_003;

        public void solve(int testNumber, LightScanner in, LightWriter out) {
            // out.setBoolLabel(LightWriter.BoolLabel.YES_NO_FIRST_UP);
            int queries = in.ints();
            ModMath mod = new ModMath(MOD);
            //Factorial fact = mod.getFactorial(MOD);
            for (int query = 0; query < queries; query++) {
                int x = in.ints(), d = in.ints(), n = in.ints();
                if (d == 0) {
                    out.ans(mod.pow(x, n)).ln();
                } else if (n >= MOD) {
                    out.ans(0).ln();
                }
                long ans = 1;
                for (int i = 0; i < n && ans > 0; i++) {
                    ans *= (x + i * (long) d);
                    ans %= MOD;
                }
