                long fact1 = fact[(int) ((x2 + n[i] - 1 + mod) % mod)];
                long fact2 = fact[(int) ((x2 - 1 + mod) % mod)];
                long mm = (fact1 * modInverseByFermatsLittleTheorem(fact2, mod)) % mod;
                System.out.println((dPowN * mm) % mod);
            }
        }
