                                .multiply(modfact[blx.subtract(BigInteger.ONE).intValueExact()].modInverse(BMOD)).mod(BMOD);
                        // System.err.println(perm);
                        BigInteger ans = perm.multiply(bd.modPow(bn, BMOD)).mod(BMOD);
                        pw.println(ans);
                    }
                }
            }

        }
        pw.flush();
    }

