import java.util.Scanner;

public class Main {
    public static void main(String args[]) {
        try (Scanner in = new Scanner(System.in)) {
            long mod = 1000003L;
            long[] fact = new long[(int) mod];
            fact[0] = 1;
            for (int i = 1; i < fact.length; i++) {
                fact[i] = (i * fact[i - 1]) % mod;
            }
            int Q = in.nextInt();
            long[] x = new long[Q];
            long[] d = new long[Q];
            long[] n = new long[Q];
            for (int i = 0; i < Q; i++) {
                x[i] = in.nextInt();
                d[i] = in.nextInt();
                n[i] = in.nextInt();

                if (d[i] == 0) {
                    long res = modPow(x[i], n[i], mod);
                    System.out.println(res);
                    continue;
                }

                long dPowN = modPow(d[i], n[i], mod);
                long invD = modInverseByFermatsLittleTheorem(d[i], mod);
                long x2 = (x[i] * invD) % mod;
                long fact1 = fact[(int) ((x2 + n[i] - 1 + mod) % mod)];
                long fact2 = fact[(int) ((x2 - 1 + mod) % mod)];
                long mm = (fact1 * modInverseByFermatsLittleTheorem(fact2, mod)) % mod;
                System.out.println((dPowN * mm) % mod);
            }
        }
    }

    public static long modInverseByFermatsLittleTheorem(long x, long modulo) {
        return modPow(x, modulo - 2, modulo);
    }

    public static final long modPow(long x, long n, long modulo) {
        long res = 1L;
        while (n > 0) {
            if ((n & 1L) != 0) {
                res = res * x % modulo;
            }
            x = x * x % modulo;
            n >>= 1;
        }
        return res;
    }
}

import java.util.*;

public class Main {
  public static long MOD = (long)Math.pow(10, 6) + 3;
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long[] kai = new long[(int)MOD];
    long[] inkai = new long[(int)MOD];
    long[] in = new long[(int)MOD];
    kai[0] = 1;
    kai[1] = 1;
    inkai[0] = 1;
    inkai[1] = 1;
    in[1] = 1;
    for(long i = 2; i < MOD; i++) {
      kai[(int)i] = (i * kai[(int)i - 1]) % MOD;
      inkai[(int)i] = func(kai[(int)i], MOD - 2);
      in[(int)i] = func(i, MOD - 2);
    }
    int q = sc.nextInt();
    for(int i = 0; i < q; i++) {
      long x = sc.nextLong();
      long d = sc.nextLong();
      long n = sc.nextLong();
      long ans = 0;
      if(d == 0) {
        if(x == 0) {
          ans = 0;
        } else {
          ans = func(x, n % (MOD - 1));
        }
      } else {
        x = (x * in[(int)d]) % MOD;
        if(x == 0) {
          ans = 0;
        } else {
          if((int)(x + n - 1) >= MOD) {
            ans = 0;
          } else {
            long t = func(d, n % (MOD - 1));
            ans = (((kai[(int)(x + n - 1)] * inkai[(int)(x - 1)]) % MOD) * t) % MOD;
          }
        }
      }
    }
  }

  public static long func(long a, long x) {
    if(x == 0) return 1;
    if(x >= 1) {
      if(x % 2 == 0) {
        long t = func(a, x / 2);
        return (t * t) % MOD;
      } else {
        long t = func(a, x - 1);
        return (a * t) % MOD;
      }
    }
    return 0;
  } 
}

