public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		int Q = ir.nextInt();
		long[] f = fact((int) mod - 1, mod);
		long[] fi = factInv((int) mod - 1, mod);
		while (Q-- > 0) {
			long x = ir.nextLong();
			long d = ir.nextLong();
			long n = ir.nextLong();
			if (d == 0) {
				out.println(modpow(x, n));
				continue;
			}
			if (x == 0) {
				out.println(0);
				continue;
			}
			if (n >= mod) {
				out.println(0);
				continue;
			}
			long res = modpow(d, n);
			long p = div(x, d, mod) + n - 1;
			long q = div(x, d, mod) - 1;
			if (p >= mod) {
				out.println(0);
				continue;
			}
			if (q < 0) {
				out.println(0);
