import java.io.IOException;
import java.io.InputStream;
import java.util.*;

public class Main implements Runnable {

    public static void main(String[] args) {
    	new Thread(null, new Main(), "", 16 * 1024 * 1024).start();
    }

    public void run() {
        FastScanner sc = new FastScanner();
        int q = sc.nextInt();
        int mod = 1000003;
        Combinatrics c = new Combinatrics(mod*2);

        for(int i=0;i<q;i++){
        	int x = sc.nextInt();
        	int d = sc.nextInt();
        	int n = sc.nextInt();

        	if(d==0){
        		long ans = iterationPowMod(x,n);
            	System.out.println(ans);
        	}
        	else{
            	long dinv = c.inv(d);
            	long moto = x * dinv % mod;
            	long up = c.factorial((int)moto + n -1);
            	long down = c.factInv((int)moto -1);
            	long dn = iterationPowMod(d,n);
            	long ans = (up*down % mod)*dn %mod;

            	System.out.println(ans);
        	}
        }


    }

	static int iterationPowMod(long x, long n){
		int mod = 1000003;
	    long sum = 1;
	    while(n>0){
	        if((n&1)== 1){  //ビットが立っていたら
	            sum *= x;        //x^2^k1 * x^2^k2 * x^2^k3 * ・・・
	            sum %= mod;
	        }
	        x *= x;              //((x^2)^2)^2・・・
	        x %= mod;
	        n >>= 1;
	    }
	    return (int)sum;
	}

}

class Combinatrics {

	static long mod = 1000003; //逆元を取るので素数前提
	static long[] fact; //階乗のテーブル
	static long[] inv;	//逆元のテーブル
	static long[] finv; //階乗の逆元のテーブル

	public Combinatrics(int n){
		fact = new long[n+1];
		inv = new long[n+1];
		finv = new long[n+1];
	    fact[0] = fact[1] = 1;
	    finv[0] = finv[1] = 1;
	    inv[1] = 1;
	    for(int i=2;i<n+1; i++){
	        fact[i] = fact[i-1] * i % mod;
	        inv[i] = mod - inv[(int)mod%i] * (mod / i) % mod;
	        finv[i] = finv[i-1] * inv[i] % mod;
	    }
	}

	//逆元
	int inv(int n){
		return (int)inv[n];
	}

	//n!
	int factorial(int n){
		return (int)fact[n];
	}

	//n!の逆元
	int factInv(int n){
		return (int)finv[n];
	}

	//nCr（n個からr個選ぶ）
    int combination(int n, int r) {
        if(n<r|| r<0){
        	return 0;
        }
        return (int)(fact[n]*finv[r]%mod*finv[n-r]%mod);
    }

    //nPr (=n*(n-1)*...*(n-r+1))（n個からr個選んで並べる）
    int permutation(int n, int r) {
        if(n<r || r<0){
        	return 0;
        }
        return (int)(fact[n]*finv[n-r]%mod);
    }

    //nHr (=n+r-1Cr)（n個から重複を許してk個とる）
    //（テーブルがn+r-1まで必要な事に注意！）
    int homogeneous(int n, int r) {
        if(n==0 && r==0){
        	return 1;
        }
        return combination(n+r-1,r);
    }

}


