	static int[][] fif;
	static int[] es;

	static void solve()
	{
		fif = enumFIF(1000002, 1000003);
		es = new int[1000003];
		int cur = 1;
		for(int i = 0;i <= 1000002;i++){
			es[cur] = i;
			cur = cur * 2 % 1000003;
		}
