	static long go(long x, long d, int n)
	{
		int mod = 1000003;
		x %= mod;
		d %= mod;
		if(d == 0){
			return pow(x, n, mod);
		}
		if(n == 0){
			return 1;
		}
		if(n == 1){
			return x;
		}
		if(n >= mod){
			return 0;
		}
		if(x == 0){
			return 0;
		}
		long e = es[(int)x];
		long f = es[(int)d];
		if(e < f)e += mod-1;
		// 2^e * (2^e+2^f)..
		long base = pow(2, e-f, mod);
		// base*(base+1)*(base+2)...
		if(base+n-1 >= mod)return 0;
		long val = (long)fif[0][(int)(base+n-1)] * fif[1][(int)(base-1)] % mod
				* pow(2, (long)f*n%(mod-1), mod) % mod;
		return val;
	}

	public static int[][] enumFIF(int n, int mod) {
		int[] f = new int[n + 1];
		int[] invf = new int[n + 1];
		f[0] = 1;
		for (int i = 1; i <= n; i++) {
			f[i] = (int) ((long) f[i - 1] * i % mod);
		}
		long a = f[n];
		long b = mod;
		long p = 1, q = 0;
		while (b > 0) {
			long c = a / b;
			long d;
			d = a;
			a = b;
			b = d % b;
			d = p;
			p = q;
			q = d - c * q;
		}
		invf[n] = (int) (p < 0 ? p + mod : p);
		for (int i = n - 1; i >= 0; i--) {
			invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
		}
		return new int[][] { f, invf };
	}

	public static long invl(long a, long mod) {
		long b = mod;
		long p = 1, q = 0;
		while (b > 0) {
			long c = a / b;
			long d;
			d = a;
			a = b;
			b = d % b;
			d = p;
			p = q;
			q = d - c * q;
		}
		return p < 0 ? p + mod : p;
	}



	public static long pow(long a, long n, long mod) {
		//		a %= mod;
		long ret = 1;
		int x = 63 - Long.numberOfLeadingZeros(n);
		for (; x >= 0; x--) {
			ret = ret * ret % mod;
			if (n << 63 - x < 0)
				ret = ret * a % mod;
		}
		return ret;
	}

