import java.util.*;

public class Main {
  public static long MOD = (long)Math.pow(10, 6) + 3;
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long[] kai = new long[MOD];
    long[] inkai = new long[MOD];
    long[] in = new long[MOD];
    kai[0] = 1;
    kai[1] = 1;
    inkai[1] = 1;
    in[1] = 1;
    for(long i = 2; i < MOD; i++) {
      kai[i] = (i * kai[(int)i - 1]) % MOD;
      inkai[i] = func(kai[i], MOD - 2);
      in[i] = func(i, MOD - 2);
    }
    int q = sc.nextInt();
    for(int i = 0; i < q; i++) {
      long x = sc.nextLong();
      long d = sc.nextLong();
      long n = sc.nextLong();
      if(d == 0) {
        return func(x, n);
      } else {
        x = (x * in[d]) % MOD;
        if(x == 0) {
          return 0;
        } else {
          if((int)(x + n - 1) >= MOD) {
            return 0;
          } else {
            return (kai[(int)(x + n - 1)] * inkai[(int)(x - 1)]) % MOD;
          }
        }
      }
    }
  }

  public static long func(long a, long x) {
    if(x == 0) return 1;
    if(x == 1) return a;
    if(x >= 2) {
      if(x % 2 == 0) {
        long t = func(a, x / 2);
        return (t * t) % MOD;
      } else {
        return (a * func(a, x / 2)) % MOD;
      }
    }
    return 0;
  } 
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int q = Integer.parseInt(br.readLine());
		int[] x = new int[q];
		int[] d = new int[q];
		int[] n = new int[q];
		for (int i = 0; i < q; i++) {
			String[] sa = br.readLine().split(" ");
			x[i] = Integer.parseInt(sa[0]);
			d[i] = Integer.parseInt(sa[1]);
			n[i] = Integer.parseInt(sa[2]);
		}
		br.close();

		int mod = 1000003;
		long[] p = new long[mod];
		long[] pi = new long[mod];
		p[0] = 1;
		for (int i = 1; i < p.length; i++) {
			p[i] = p[i - 1] * i % mod;
			pi[i] = modinv(p[i], mod);
		}

		PrintWriter pw = new PrintWriter(System.out);
		for (int i = 0; i < q; i++) {
			long xi = x[i];
			long di = d[i];
			long ni = n[i];
			if (di == 0) {
				pw.println(power(xi, ni));

			} else {
				long xd = xi * modinv(di, mod) % mod;
				if (xd == 0 || xd + ni - 1 >= mod) {
					pw.println(0);
				} else {
					long ans = p[(int) (xd + ni - 1)];
					if (xd > 1) {
						ans *= pi[(int) (xd - 1)];
						ans %= mod;
					}
					ans *= power(di, ni);
					ans %= mod;
					pw.println(ans);
				}
			}
		}
		pw.flush();
	}

	static long modinv(long a, long m) {
		long b = m;
		long u = 1;
		long v = 0;
		long tmp = 0;

		while (b > 0) {
			long t = a / b;
			a -= t * b;
			tmp = a;
			a = b;
			b = tmp;

			u -= t * v;
			tmp = u;
			u = v;
			v = tmp;
		}

		u %= m;
		if (u < 0) u += m;
		return u;
	}

	static long power(long x, long n) {
		if (n == 0) {
			return 1;
		}
		if (n % 2 == 0) {
			return power(x * x % 1000003, n / 2) % 1000003;
		} else {
			return x * power(x, n - 1) % 1000003;
		}
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int p = 1000003;
        long[] inv = invs(p);
        long[] fac = new long[2 * p + 1];
        fac[0] = 1;
        for (int i = 1; i <= 2 * p; i++) fac[i] = (fac[i - 1] * i) % p;
        int q = sc.nextInt();
        while (q --> 0) {
            long x = sc.nextInt();
            long d = sc.nextInt();
            long n = sc.nextInt();
            if (d == 0) {
                out.writeln(pow(x, n, p));
                continue;
            }
            long z = ((p - x) * inv[(int) d]) % p;
            long k = (x * inv[(int) d]) % p;
            if (n >= z) {
                out.writeln(0);
                continue;
            }
            long pow = pow(d, n, p);
            long v = (fac[(int) (k + n - 1)] * inv[(int) fac[(int) (k - 1)]]) % p;
            out.writeln((pow * v) % p);
        }
    }

    public static long[] invs(int p) {
        long[] inv = new long[p];
        inv[1] = 1;
        for (int i = 2; i < p; i++) {
            long q = p - p / i;
            long r = inv[p % i];
            inv[i] = (q * r) % p;
        }
        return inv;
    }

    public static long pow(long a, long b, long p) {
        if (b == 0 || a == 1) return 1;
        long res = 1;
        for (long pow = a, c = 1; b > 0;) {
            long lsb = b & -b;
            for (; lsb != c; c <<= 1, pow = (pow * pow) % p);
            res = (res * pow) % p;
            b ^= lsb;
        }
        return res;
    }
}


/**
 * @author https://atcoder.jp/users/suisen
 */
class BasicScanner {
    private final InputStream in;
    private final byte[] buf = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    public BasicScanner(InputStream in) {this.in = in;}
    private boolean hasNextByte() {
        if (ptr < buflen) return true;
        ptr = 0;
        try {buflen = in.read(buf);}
        catch (final IOException e) {e.printStackTrace();}
        return buflen > 0;
    }
    private int readByte() {return hasNextByte() ? buf[ptr++] : -1;}
    public boolean hasNext() {
        while (hasNextByte() && !(33 <= buf[ptr] && buf[ptr] <= 126)) ptr++;
        return hasNextByte();
    }
    private StringBuilder nextSequence() {
        if (!hasNext()) throw new NoSuchElementException();
        final StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (33 <= b && b <= 126) {sb.appendCodePoint(b); b = readByte();}
        return sb;
    }
    public char nextChar() {
        return (char) readByte();
    }
    public String next() {
        return nextSequence().toString();
    }
    public String next(int len) {
        return new String(nextChars(len));
    }
    public char[] nextChars() {
        final StringBuilder sb = nextSequence();
        int l = sb.length();
        char[] dst = new char[l];
        sb.getChars(0, l, dst, 0);
        return dst;
    }
    public char[] nextChars(int len) {
        if (!hasNext()) throw new NoSuchElementException();
        char[] s = new char[len];
        int i = 0;
        int b = readByte();
        while (33 <= b && b <= 126 && i < len) {s[i++] = (char) b; b = readByte();}
        if (i != len) throw new NoSuchElementException(String.format("length %d is longer than the sequence.", len));
        return s;
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {minus = true; b = readByte();}
        if (b < '0' || '9' < b) throw new NumberFormatException();
        while (true) {
            if ('0' <= b && b <= '9') n = n * 10 + b - '0';
            else if (b == -1 || !(33 <= b && b <= 126)) return minus ? -n : n;
            else throw new NumberFormatException();
            b = readByte();
        }
    }
    public int nextInt() {return Math.toIntExact(nextLong());}
    public double nextDouble() {return Double.parseDouble(next());}
}


