import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author cunbidun
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        EProductOfArithmeticProgression solver = new EProductOfArithmeticProgression();
        solver.solve(1, in, out);
        out.close();
    }

    static class EProductOfArithmeticProgression {
        private static final int MOD = (int) 1e6 + 3;
        private InputReader in;
        private PrintWriter out;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.in = in;
            this.out = out;
            int q = in.nextInt();

            int[] fac = new int[MOD + 1];
            int[] inv = new int[MOD + 1];
            fac[0] = 1;
            inv[0] = Op.inv(1, MOD);
            for (int i = 1; i <= MOD; i++) {
                fac[i] = Op.mulMod(fac[i - 1], i, MOD);
                inv[i] = Op.inv(fac[i], MOD);
            }

            while (q-- > 0) {
                int x = in.nextInt();
                int d = in.nextInt();
                int n = in.nextInt();
                if (d == 0) {
                    out.println(Op.powMod(x, n, MOD));
                    continue;
                }
                x = Op.mulMod(x, Op.inv(d, MOD), MOD);
                int ans;
                if (x + n - 1 >= MOD || x == 0) ans = 0;
                else
                    ans = Op.mulMod(fac[x + n - 1], inv[x - 1], MOD);
                out.println(Op.mulMod(ans, Op.powMod(d, n, MOD), MOD));
            }
        }

    }

    static class Op {
        public static int mulMod(int x, int y, int MOD) {
            return (int) (((long) x * y) % MOD);
        }

        public static int powMod(int x, long p, int MOD) {
            if (p == 0) return 1;
            int t = powMod(x, p / 2, MOD);
            if ((p & 1) == 1)
                return mulMod(mulMod(t, t, MOD), x, MOD);
            return mulMod(t, t, MOD);
        }

        public static int inv(int x, int MOD) {
            return powMod(x, MOD - 2, MOD);
        }

    }

    static class InputReader extends InputStream {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

import java.math.*;
import static java.math.BigInteger.*;
import java.util;

static class Split {
	static long N;

	static BigInteger factorial(long n) {
		if (n < 2) {
			return ONE;
		}
		BigInteger p = ONE, r = ONE;
		N = 1;
		long log2n = 31 - Integer.numberOfLeadingZeros(n);
		long h = 0, shift = 0, high = 1;
		while (h != n) {
			shift += h;
			h = n >>> log2n--;
			long len = high;
			high = (h & 1) == 1 ? h : h - 1;
			len = (high - len) >> 1;
			if (len > 0) {
				r = r.multiply((p = p.multiply(bp(len))));
			}
		}
		return r.shiftLeft(shift);
	}

	static BigInteger bp(long n) {
		long m = n >> 1;
		if (m == 0) {
			return valueOf(N += 2)%1000003;
		} else if (n == 2) {
			return valueOf(N += 2).multiply(valueOf(N += 2))%1000003;
		}
		return bp(n - m).multiply(bp(m))%1000003;
	}}
static final long modPow(long x, long n, final long mod) {
    long sum = 1;
    while (n > 0) {
        if ((n & 1) == 1) {      //ビットが立っていたら
            sum = sum * x % mod; //x^2^k1 * x^2^k2 * x^2^k3 * ・・・
        }
        x = x * x % mod;         //((x^2)^2)^2 ・・・
        n >>= 1;
    }
    return sum;
}

    public class Main{
        public static void main(string[]args){
            Scanner sc=new Scanner();
            int Q=sc.nextInt();
            for(int i=0;i<Q;i++){
                long x,d,n;
                x=sc.nextInt();
                d=sc.nextInt();
                n=sc.nextInt();
                System.out.println(Split.factorial(2*n)/Split.factorial(n)/modPow(2,n,1000003));
            }

        }

    }

