using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;
using static System.Math;

class Program
{
    static long mod = (long)1e6 + 3;
    static long[] f = new long[mod]; //階乗
    static long[] invf = new long[mod]; //階乗の逆元

    static void Main()
    {
        f[0] = 1;
        invf[0] = 1;
        for (int i = 1; i < mod; i++)
        {
            f[i] = f[i - 1] * i % mod;
            invf[i] = inv(f[i]);
        }
        int q = int.Parse(Console.ReadLine());
        for (int i = 0; i < q; i++)
        {
            long[] input = Console.ReadLine().Split().Select(long.Parse).ToArray();
            Console.WriteLine(Ans(input[0], input[1], input[2]));
        }
    }

    static long Ans(long x, long d, long n)
    {
        x %= mod;
        if (x == 0) return 0;
        if (n == 1) return x;
        if (d == 0) return pow(x, n);
        long y = x * inv(d) % mod;
        long r = (y + n - 1 + mod) % mod;
        long l = (y - 1 + mod) % mod;
        if (n >= mod || l > r) return 0;
        long ans = pow(d, n);
        return ans * f[r] % mod * invf[l] % mod;
    }

    static long pow(long a, long k)
    {
        if (k == 0) return 1;
        if (k == 1) return a % mod;
        long t = pow(a, k / 2);
        if (k % 2 == 0) return t * t % mod;
        return t * t % mod * a % mod;
    }

    static long inv(long k)
    {
        return pow(k, mod - 2);
    }
}

