using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		int Q = int.Parse(Console.ReadLine());
		long[]NA = new long[1000010];
		long[]INA = new long[1000010];
		long mod = 1000003;
		NA[0] = 1;
		INA[0] = 1;
		for(var i=1;i<1000010;i++){
			NA[i] = NA[i-1] * i % mod;
			INA[i] = INA[i-1] * Mpow(i,mod-2,mod) % mod;
		}
		for(var i=0;i<Q;i++){
			string[] str = Console.ReadLine().Split();
			long X = long.Parse(str[0]);
			long D = long.Parse(str[1]);
			long N = long.Parse(str[2]);
			long ans;
			if(D==0){
				ans = Mpow(X,N,mod);
			} else {
				ans = NA[(X*Mpow(D,mod-2,mod)+N-1)%mod] * INA[(X*Mpow(D,mod-2,mod)+mod-1)%mod] % mod;
              	ans = ans * Mpow(D,N,mod) % mod;
			}
			Console.WriteLine(ans);
		}
	}

	public static long Mpow(long x,long n,long m)
	{
		long ans = 1;
		while(n > 0){
			if(n % 2 == 1){
				ans = ans * x % m;
				n -= 1;
			}
			x = x * x % m;
			n /= 2;
		}
		return ans;
	}
}

