class Program
{
    static readonly long D = 1000003;

    static void Solve()
    {
        var Q = ReadInt();
        for (var i = 0; i < Q; i++)
        {
            var input = ReadInts();
            Console.WriteLine(P(input[0], input[1], input[2]));
        }
    }

    private static int P(int first, int diff, int n)
    {
        long p = first;
        long now = first;
        for (var i = 2; i <= n; i++)
        {
            now = first + (i - 1) * diff;
            p = (p * now) % D;

        }
        return (int)(p % D);
    }


    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();

    }

