namespace SolutionCS
{
    class Program
    {
        static void Main(string[] args)
        {
            const int M = 1000003;

            int Q = int.Parse(Console.ReadLine());

            for (int i = 0; i < Q; i++)
            {
                string[] instr = Console.ReadLine().Split(' ');

                long x = long.Parse(instr[0]);
                long d = long.Parse(instr[1]);
                int n = int.Parse(instr[2]);

                long result = x;
                for (int j = 1; j < n; j++)
                {
                    x += d;

                    result *= x;
                    result %= M;
                }

                Console.WriteLine(result);
            }
        }
    }
}

