namespace Program
{
    public class M_SOLUTIONSE
    {
        static public void Solve()
        {
            Mod._mod = 1000003;
            var factList = new Mod[Mod._mod];
            factList[0] = 1;
            for (int i = 1; i < Mod._mod; ++i)
            {
                factList[i] = factList[i - 1] * i;
            }
            var ifactList = new Mod[Mod._mod];
            ifactList[0] = 1;
            for (int i = 0; i < Mod._mod; ++i)
            {
                ifactList[i] = 1 / factList[i];
            }
            var Q = NextInt;
            for (int i = 0; i < Q; ++i)
            {
                var x = (Mod)NextInt;
                var d = (Mod)NextInt;
                var n = NextInt;
                if (n >= Mod._mod)
                {
                    Console.WriteLine(0);
                }
                else if (d == 0)
                {
                    Console.WriteLine(Mod.Pow(x, n));
                }
                else
                {
                    var ans = Mod.Pow(d, n) * (factList[(long)(x / d + n - 1)] * ifactList[(long)(x / d - 1)]);
                    Console.WriteLine(ans);
                }
            }
        }

