namespace Kujikatsu023.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/m-solutions2019/tasks/m_solutions2019_e
    /// </summary>
    public class QuestionG : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            Modular.Mod = 1000003;
            Modular.InitializeCombinationTable();

            var queries = inputStream.ReadInt();
            for (int q = 0; q < queries; q++)
            {
                var (x, d, n) = inputStream.ReadValue<int, int, int>();
                if (d == 0)
                {
                    yield return Modular.Pow(x, n);
                }
                else
                {
                    var p = new Modular(x) / new Modular(d);
                    var k = n + p.Value - 1;
                    var r = k - (p.Value - 1);
                    var permutation = Modular.Permutation(k, r);
                    var pow = Modular.Pow(d, n);
                    yield return (permutation * pow).Value;
                }
            }
        }
    }
}

namespace Kujikatsu023
{
    class Program
    {
        static void Main(string[] args)
        {
            IAtCoderQuestion question = new QuestionG();
            var answers = question.Solve(Console.In);

            var writer = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(writer);
            foreach (var answer in answers)
            {
                Console.WriteLine(answer);
            }
            Console.Out.Flush();
        }
    }
}

