        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static Modular Pi(int x, int n)
        {
            return (x > 0 && n < 1000002) ? Modular.Fac(x + n) / Modular.Fac(x - 1) : 0;
        }

        static int Solve(int x, int d, int n)
        {
            if (d == 0)
            {
                return (int)Modular.Pow(x, n);
            }
            else
            {
                var X = new Modular(x) / d;
                return (int)(Modular.Pow(d, n) * Pi((int)X, n - 1));
            }
        }

