namespace Kujikatsu023.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/m-solutions2019/tasks/m_solutions2019_e
    /// </summary>
    public class QuestionG : AtCoderQuestionBase
    {
        int Mod = 1000003;

        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            Modular.Mod = 1000003;
            InitializeCombinationTable(1000002);

            var queries = inputStream.ReadInt();

            for (int q = 0; q < queries; q++)
            {
                var (x, d, n) = inputStream.ReadValue<int, int, int>();
                if (d == 0)
                {
                    yield return Modular.Pow(x, n);
                }
                else
                {
                    if (n >= Modular.Mod)
                    {
                        yield return 0;
                    }
                    else
                    {
                        var p = new Modular(x) / new Modular(d);
                        var permutation = Factorial(n + p.Value - 1) * FactorialInverseCache[p.Value - 1];
                        var pow = Modular.Pow(d, n);
                        yield return (permutation * pow).Value;
                    }
                }
            }
        }

        int[] FactorialInverseCache;
        List<int> FactorialCache = new List<int>() { 1 };

        public Modular Factorial(int n)
        {
            if (n < 0)
            {
                throw new ArgumentOutOfRangeException(nameof(n), $"{nameof(n)}は0以上の整数でなければなりません。");
            }

            for (int i = FactorialCache.Count; i <= n; i++)  // Countが1（0!までキャッシュ済み）のとき1!～n!まで計算
            {
                FactorialCache.Add((int)((long)FactorialCache[i - 1] * i % Mod));
            }
            return new Modular(FactorialCache[n]);
        }

        public void InitializeCombinationTable(int max)
        {
            _ = Factorial(max);
            FactorialInverseCache = new int[max + 1];

            var fInv = (Modular.One / Factorial(max)).Value;
            FactorialInverseCache[max] = fInv;
            for (int i = max - 1; i >= 0; i--)
            {
                fInv = (int)((long)fInv * (i + 1) % Mod);
                FactorialInverseCache[i] = fInv;
            }
        }
    }
}

