using System;
using System.Collections.Generic;
using System.Linq;

public class Hello
{
    private const int MOD_N = 1000003;

    private struct XDN
    {
        public uint x, d, n;
    }

    public static void Main()
    {
        var q = int.Parse(Console.ReadLine());

        var xdns = new XDN[q];
        for (int i = 0; i < xdns.Length; ++i)
        {
            var list = Console.ReadLine().Split(' ');
            var x = uint.Parse(list[0]);
            var d = uint.Parse(list[1]);
            var n = uint.Parse(list[2]);
            xdns[i] = new XDN() { x = x, d = d, n = n };
        }

        for (int i = 0; i < xdns.Length; ++i)
        {
            var xdn = xdns[i];
            ulong x = xdn.x;
            var ans = x;
            var d = xdn.d;
            for (var n = xdn.n - 1; n != 0; --n)
            {
                x += d;
                x %= MOD_N;
                ans *= x;
                ans %= MOD_N;
            }

            Console.WriteLine(ans);
        }
    }

    private static int Comb(int m, int n)
    {
        var t = m - n;
        if (n > t)
            n = t;

        long numerator = 1;
        for (int i = 0; i < n; ++i)
        {
            numerator *= m - i;
            numerator %= MOD_N;
        }
        long denominator = 1;
        for (; n != 0; --n)
        {
            denominator *= n;
            denominator %= MOD_N;
        }

        var inv_denominator = ModInv((int)denominator, MOD_N);
        var ret = (int)(numerator * inv_denominator % MOD_N);

        return ret >= 0 ? ret : ret + MOD_N;
    }

    private static int ModInv(int a, int m)
    {
        int b = m, x = 1, y = 0;
        while (b != 0)
        {
            var t = a / b;
            a -= t * b;
            Swap(ref a, ref b);
            x -= t * y;
            Swap(ref x, ref y);
        }
        x %= m;
        return x >= 0 ? x : x + m;
    }

    private static void Swap<T>(ref T a, ref T b)
    {
        var t = a;
        a = b;
        b = t;
    }
}

using System;
