using System.Linq;

class Program
{
    static readonly long D = 1000003;

    static void Solve()
    {
        var Q = ReadInt();
        for (var i = 0; i < Q; i++)
        {
            var input = ReadInts();
            Console.WriteLine(P(input[0], input[1], input[2]));
        }
    }

    private static int P(int first, int diff, int n)
    {
        long p = first;
        long prev = first;
        for (var i = 2; i <= n; i++)
        {
            prev = (prev + diff) % D;
            p = (p * prev) % D;
        }
        return (int)p;
    }


    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();

    }

