namespace AtCoder
{
    class Modular
    {
        private const int M = 1000003;
        private long value;

        public Modular(long value) { this.value = value; }
        public static implicit operator Modular(long a) { return new Modular((a % M + M) % M); }
        public static Modular operator +(Modular a, Modular b) { return a.value + b.value; }
        public static Modular operator -(Modular a, Modular b) { return a.value - b.value; }
        public static Modular operator *(Modular a, Modular b) { return a.value * b.value; }
        public static Modular Pow(Modular a, int n)
        {
            switch (n)
            {
            case 0:
                return 1;
            case 1:
                return a;
            default:
                var p = Pow(a, n / 2);
                return p * p * Pow(a, n % 2);
            }
        }
        public static Modular operator /(Modular a, Modular b) { return a * Pow(b, M - 2); }
        private static readonly List<int> facs = new List<int> { 1 };
        public static Modular Fac(int n)
        {
            for (int i = facs.Count; i <= n; ++i) { facs.Add((int)(Math.BigMul(facs.Last(), i) % M)); }
            return facs[n];
        }
        public static Modular Ncr(int n, int r)
        {
            return (n < r) ? 0
                 : (n == r) ? 1
                            : Fac(n) / Fac(r) / Fac(n - r);
        }
        public static explicit operator int(Modular a) { return (int)a.value; }
    }

    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static Modular Pi(int x, int n)
        {
            return (0 < x && x < 1000003) ? Modular.Fac(x + n) / Modular.Fac(x - 1) : 0;
        }

        static int Solve(int x, int d, int n)
        {
            var X = new Modular(x) / d;
            return (int)(Modular.Pow(d, n) * Pi((int)X, n - 1));
        }

        static void Main(string[] args)
        {
            int Q = ReadInt();
            for (int i = 0; i < Q; ++i)
            {
                int[] V = ReadInts();
                Console.WriteLine(Solve(V[0], V[1], V[2]));
            }
        }
    }
}

