        static void Solve()
        {
            const long mod = 1000003;
            var F = new long[mod];F[0] = 1;
            for (var i = 0; i < mod - 1; i++) F[i + 1] = (F[i] * (i + 1)) % mod;
            long modpow(long a, long b) => b == 0 ? 1 : (b % 2 == 0 ? modpow((a * a) % mod, b >> 1) : (a * modpow(a, b - 1)) % mod);
