partial class Solver
{
    const int Mod = 1000003;
    public void Run()
    {
        var Q = ni();

        var MulTable = new long[Mod + 120];
        MulTable[1] = 1;
        for (int i = 2; i < MulTable.Length; i++)
        {
            MulTable[i] = (MulTable[i - 1] * i) % Mod;
        }

        for (int _ = 0; _ < Q; _++)
        {
            var x = nl();
            var d = nl();
            var n = nl();
            long ans = 0;

            if (d == 0)
            {
                ans = ModPow2(x, n, Mod);
            }
            else
            {
                // a = x / d
                var a = x * Inverse(d, Mod) % Mod;
                var dn = ModPow2(d, n, Mod);
                // a * (a+1) * ... * (a+n-1)

                if (a + n - 1 >= Mod)
                {
                    ans = 0;
                }
                else
                {
                    ans = MulTable[a + n - 1];
                    if (a - 1 > 0)
                    {
                        ans = (ans * Inverse(MulTable[a - 1], Mod)) % Mod;
                    }
                }

                ans *= dn;
                ans %= Mod;
            }

            cout.WriteLine(ans);
        }
    }

    static public long ModPow2(long x, long n, long mod)
    {
        long t = x, ret = 1;
        while (n > 0)
        {
            if ((n & 1) != 0)
            {
                ret = (t * ret) % mod;
            }
            t = t * t % mod;
            n >>= 1;
        }
        return ret;
    }
    static public long ExtendedGcd(long a, long b, ref long x, ref long y)
    {
        if (b == 0)
        {
            x = 1; y = 0;
            return a;
        }
        else
        {
            long d = ExtendedGcd(b, a % b, ref y, ref x);
            y -= a / b * x;
            return d;
        }
    }

    static public long Inverse(long a, long mod)
    {
        long x = 0, y = 0;
        if (ExtendedGcd(a, mod, ref x, ref y) == 1)
            return (x + mod) % mod;
        else
            return -1;
    }
}

