namespace AtCoderProject
{
    public class Program
    {
        public object Calc()
        {
            var Q = consoleReader.Int;
            var res = new List<long>(Q);
            Mod.InitCombine(1000003);
            foreach (var line in consoleReader.Repeat(Q).SplitInt)
            {
                var x = line[0];
                var d = line[1];
                var n = line[2];

                if (d == 0) res.Add(Mod.Pow(x, n).val);
                else if (d == 1)
                {
                    if (1000003 <= x + n - 1) res.Add(0);
                    else res.Add((Mod.fac[x + n - 1] * Mod.finv[x - 1]).val);
                }
                else
                {
                    var xMod = x / new Mod(d);
                    if (1000003 <= xMod.val + n - 1) res.Add(0);
                    else res.Add((Mod.fac[xMod.val + n - 1] * Mod.finv[xMod.val - 1] * Mod.Pow(d, n)).val);
                }
            }

            return AllLines(res);
        }

