		if e == nil {
			return i
		}
	}
	return 0
}

func cal(a int, d int, n int) uint64 {
	var p uint64
	p = 1

	var i int
	for i = 1; i <= n; i++ {
		p *= uint64((a + (i-1)*d))
	}

	return p
}

