	sc.Split(bufio.ScanWords)

	var answers []uint64

	q := nextInt()

	for i := 0; i < q; i++ {
		a, d, n := nextInt(), nextInt(), nextInt()
		p := cal(a, d, n)
		answers = append(answers, p%uint64(1000003))
	}

	for _, answer := range answers {
		fmt.Println(answer)
	}
}

