		d2 := (d * d) % mod

		var c int64
		var k int64
		if n%2 == 0 {
			k = (n - 2) / 2
			c = (x * (x + n*d/2) % mod) % mod
		} else {
			k = (n - 1) / 2
			c = x
		}
		for j := int64(1); j <= k; j++ {
			c = (c * (t + ((j*(n-j))%mod)*d2) % mod) % mod
		}

		fmt.Println(c)
	}
