type CombinationTable struct {
	// i! % MOD M
	fact []int
	// (i!)^(-1) MOD M
	finv []int
	// i^(-1) MOD M
	inv []int

	mod int
}

// ref: http://drken1215.hatenablog.com/entry/2018/06/08/210000
func prepareCombination(max int, mod int) CombinationTable {
	fact := make([]int, max+1)
	finv := make([]int, max+1)
	inv := make([]int, max+1)

	fact[0] = 1
	fact[1] = 1
	finv[0] = 1
	finv[1] = 1
	inv[1] = 1

	for i := 2; i <= max; i++ {
		fact[i] = fact[i-1] * i % mod
		inv[i] = mod - inv[mod%i]*(mod/i)%mod // a^(-1) ≡ -(p % a)^(-1) * (p/a) MOD p
		finv[i] = finv[i-1] * inv[i] % mod
	}

	return CombinationTable{
		fact: fact,
		finv: finv,
		inv:  inv,
		mod:  mod,
	}
}

// PowM gets the Pow value mod M
func PowM(a, e, mod int) int {
	res := 1

	for e != 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e = e >> 1
	}

	return res
}

// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	Q := io.NextInt()

	mod := 1000003
	ct := prepareCombination(mod, mod)

	for i := 0; i < Q; i++ {
		x := io.NextInt()
		d := io.NextInt()
		n := io.NextInt()

		if d == 0 {
			res := PowM(x, n, mod)
			io.Println(res)
			continue
		}

		xd := x * ct.inv[d] % mod

		if xd%mod == 0 || xd/mod != (xd+n-1)/mod {
			io.Println(0)
		}

		res := ct.fact[xd+n-1] * ct.finv[(xd+mod-1)%mod] % mod
		res *= PowM(d, n, mod)
		res %= mod
		io.Println(res)
	}
}

