const mod int64 = 1000003
const size int = 40

func main() {
  f := make([]int64,mod)
  f[0] = 1
  for i:=int64(1);i<mod;i++ { f[i] = (f[i-1]*i)%mod }
  input := Input{bufio.NewReaderSize(os.Stdin,100)}
  q := input.NextInt()
  for k:=0;k<q;k++ {
    x,d,n := input.NextInts()
    if x == 0 { fmt.Println(0);continue }
    if d == 0 { fmt.Println(pow(x,n));continue }
    j := ((mod-x)*inv(d))%mod
    if n > j { fmt.Println(0);continue }
    y := (x*inv(d))%mod
    m := (f[y+n-1]*inv(f[y-1]))%mod
    fmt.Println((m*pow(d,n))%mod)
  }
}

func pow(b,n int64) int64 {
  if n == 0 { return 1 }
  if n%2 == 0 {
    h := pow(b,n/2)
    return (h*h)%mod
  }
  return (b*pow(b,n-1))%mod
}
func inv(n int64) int64 {
  if n == 1 { return 1 }
  k := make([]int64,size)
  a,b,u := mod,n,size
