  for i, l := range L {
    (*A)[i], _ = strconv.ParseFloat(l, 64)
  }
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func WriteIntVec(A []int) {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

func MaxInt(A ...int32) int32 {
  max := A[0]
  for _, a := range A {
    if max < a { max = a }
  }
  return max
}
func MinInt(A ...int) int {
  min := A[0]
  for _, a := range A {
    if a < min { min = a }
  }
  return min
}
func SumInt(A ...int) int {
  sum := 0
  for _, a := range A {
    sum += a
  }
  return sum
}

func Factorial(N int) (F, Finv, Inv []int) {
  F = make([]int, N + 1)
  Finv = make([]int, N + 1)
  Inv = make([]int, N + 1)
  F[0] = 1
  F[1] = 1
  Finv[0] = 1
  Finv[1] = 1
  Inv[0] = 1
  Inv[1] = 1
  for i := 2; i < N + 1; i++ {
    F[i] = F[i - 1] * i % p
    Inv[i] = p - Inv[p % i] * (p / i) % p
    Finv[i] = Finv[i - 1] * Inv[i] % p
  }
  return
}

func Pow(x, n int) int {
  k := 1
  for _n := n; 0 < _n; k++ {
    _n /= 2
  }
  P := make([]int, k)
  P[0] = x
  for i := range P[1:] {
    P[i + 1] = P[i] * P[i] % p
  }
  xn := 1
  for i, _n := 0, n; 0 < _n; i++ {
    if _n % 2 == 1 { xn = xn * P[i] % p }
    _n /= 2
  }
  return xn
}

const p = 1000003

func Solve() {
  var Q int
  NextInt(&Q)
  F, Finv, Inv := Factorial(p - 1)
  var x, d, n int
  for i := 0; i < Q; i++ {
    NextInt(&x, &d, &n)
    if d == 0 {
      Write(Pow(x, n))
      continue
    }
    X := x * Inv[d] % p
    if X == 0 || p < X + n {
      Write(0)
      continue
    }
    Write(Pow(d, n) * (F[X + n - 1] * Finv[X - 1] % p) % p)
  }
  return
}

func main() {
  Solve()
  Output()
}

