			io.Println(res)
			continue
		}

		if x == 0 {
			io.Println(0)
			continue
		}

		xd := x * ct.inv[d] % mod
		res := ct.fact[xd+n-1] * ct.finv[(xd+mod-1)%mod] % mod
		res *= PowM(d, n, mod)
		res %= mod
		io.Println(res)
	}
}

