M pow(M m, long k) {
  if(k == 0) {
    return M(1);
  }
  auto ret = pow(m*m, k/2);
  if(k % 2 == 1) {
    return ret * m;
  } else {
    return ret;
  }
}
long solve(M x, M d, long n) {
  if(d == 0) {
    return pow(x, n).num;
  }
  auto i = (M(0) - x) / d;
  if (i.num < n) {
    return 0;
  } else {
    auto ans = M(1);
    foreach (j; iota(n)) {
      ans *= (x + d * j);
    }
    return ans.num;
  }
}

