enum long MO = 1_000_003;
enum LIM = cast(int)(MO);

long[] inv, fac, invFac;
void prepare() {
  inv = new long[LIM];
  fac = new long[LIM];
  invFac = new long[LIM];
  inv[1] = 1;
  foreach (i; 2 .. LIM) {
    inv[i] = MO - ((MO / i) * inv[cast(size_t)(MO % i)]) % MO;
  }
  fac[0] = invFac[0] = 1;
  foreach (i; 1 .. LIM) {
    fac[i] = (fac[i - 1] * i) % MO;
    invFac[i] = (invFac[i - 1] * inv[i]) % MO;
  }
}

long power(long a, long e) {
  long x = a % MO, y = 1;
  for (; e; e >>= 1) {
    if (e & 1) y = (y * x) % MO;
    x = (x * x) % MO;
  }
  return y;
}

void main() {
  prepare();

  try {
    for (; ; ) {
      const numCases = readInt();
      foreach (caseId; 0 .. numCases) {
        const X = readLong();
        const D = readLong();
        const N = readLong();

        long ans;
        if (D == 0) {
          ans = power(X, N);
        } else {
          const a = (X * inv[cast(size_t)(D)]) % MO;
          const b = a + (N - 1);
          if (0 < a && b < MO) {
            ans = fac[cast(size_t)(b)];
            ans *= invFac[cast(size_t)(a - 1)];
            ans %= MO;
            ans *= power(D, N);
            ans %= MO;
          }
        }
        writeln(ans);
      }
    }
  } catch (EOFException e) {
  }
}

