      ModNum s = x/d + n - 1;
      ModNum t = x/d - 1;
      if (n >= MOD || t.value > s.value) {
        writeln(0);
      } else {
        writeln(d^^n * ModNum.fact(s.value) * ModNum.invFact(t.value));
      }
    }
  }
}

