enum long mod = 1_000_000 + 3;

alias M = ModInt!mod;

long solve(M x, M d, long n) {
  auto i = (M(0) - x) / d;
  if (i.num < n) {
    return 0;
  } else {
    auto ans = M(1);
    foreach (j; iota(n)) {
      ans *= (x + d * j);
    }
    return ans.num;
  }
}

