import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int p = 1000003;
        int[] inv = invs(p);
        int[] fac = new int[2 * p + 1];
        fac[0] = 1;
        for (int i = 1; i <= 2 * p; i++) fac[i] = (int) (((long) fac[i - 1] * i) % p);
        int q = sc.nextInt();
        while (q --> 0) {
            long x = sc.nextInt();
            int d = sc.nextInt();
            int n = sc.nextInt();
            if (d == 0) {
                out.writeln(pow(x, n, p));
                continue;
            }
            int k = (int) ((x * inv[d]) % p);
            if ((k - 1) / p != (k + n - 1) / p) {
                out.writeln(0);
                continue;
            }
            long pow = pow(d, n, p);
            long v = ((long) fac[k + n - 1] * inv[fac[k - 1]]) % p;
            out.writeln((pow * v) % p);
        }
    }

    public static int[] invs(int p) {
        int[] inv = new int[p];
        inv[1] = 1;
        for (int i = 2; i < p; i++) {
            long q = p - p / i;
            long r = inv[p % i];
            inv[i] = (int) ((q * r) % p);
        }
        return inv;
    }

    public static long pow(long a, long b, int p) {
        if (b == 0 || a == 1) return 1;
        long res = 1;
        for (long pow = a, c = 1; b > 0;) {
            long lsb = b & -b;
            for (; lsb != c; c <<= 1, pow = (pow * pow) % p);
            res = (res * pow) % p;
            b ^= lsb;
        }
        return res;
    }
}


