    if q==0 or q==p:
        return 1
    if q > p-q:
        q = p-q
    num = p
    den = q
    for i in range(1,q):
        num = (num * (p-i))%r
        den = (den * (q-i))%r
    xden = modinv(den,r)
    return (num*xden)%r

