MOD = 1000003


class ModInt(object):

  def __init__(self, num, mod):
    self.num = num
    self.mod = mod

    if self.num >= self.mod:
      self.num %= self.mod

  def inv(self):
    a, b, u, v = self.mod, self.num, 0, 1

    while b != 0:
      t = a // b
      a -= t * b
      u -= t * v
      a, b = b, a
      u, v = v, u

    return ModInt(u % self.mod, self.mod)

  def __add__(self, n):
    raise NotImplementedError()

  def __sub__(self, n):
    raise NotImplementedError()

  def __mul__(self, n):
    return ModInt((self.num * int(n)) % self.mod, self.mod)

  def __div__(self, n):
    raise NotImplementedError()

  def __pow__(self, n):
    v = 1
    m = self.num

    while n != 0:
      if n & 1 != 0:
        v = (v * m) % self.mod

      m = (m * m) % self.mod
      n = n >> 1

    return ModInt(v, self.mod)

  def __int__(self):
    return self.num

  def __str__(self):
    return str(self.num)


def main():
  facs = [None] * MOD
  facs[0] = ModInt(1, MOD)

