#[macro_use]
pub mod contest {
    #[macro_use]
    pub mod math {
        //! math library.

        use std::ops::*;

        static mut MODULO: i64 = 1_000_000_007;

        #[inline]
        fn modulo() -> i64 {
            unsafe { MODULO }
        }

        #[derive(Copy, Clone)]
        pub struct Mint(pub i64);

        impl Mint {
            pub fn set_mod(modulo: i32) {
                unsafe {
                    MODULO = modulo as i64;
                }
            }
            pub fn value(self) -> i64 {
                self.0
            }
        }

        impl ::std::fmt::Display for Mint {
            fn fmt(&self, f: &mut ::std::fmt::Formatter) -> ::std::fmt::Result {
                write!(f, "{}", self.0)
            }
        }

        /// ```
        /// use contest::math::Mint;
        /// Mint::set_mod(5);
        /// assert_eq!(1, (Mint(2) + Mint(4)).0);
        /// ```
        impl<I: ToI64> Add<I> for Mint {
            type Output = Mint;
            fn add(self, o: I) -> Mint {
                let mut x = self.0 + o.to_i64();
                if x >= modulo() {
                    x -= modulo();
                }
                Mint(x)
            }
        }

        /// ```
        /// use contest::math::Mint;
        /// Mint::set_mod(5);
        /// let mut a = Mint(2);
        /// a += Mint(4);
        /// assert_eq!(1, a.0);
        /// ```
        impl<I: ToI64> AddAssign<I> for Mint {
            fn add_assign(&mut self, o: I) {
                let mut x = self.0 + o.to_i64();
                if x >= modulo() {
                    x -= modulo();
                }
                self.0 = x;
            }
        }

        /// ```
        /// use contest::math::Mint;
        /// Mint::set_mod(5);
        /// assert_eq!(4, (Mint(2) - Mint(3)).0);
        /// ```
        impl<I: ToI64> Sub<I> for Mint {
            type Output = Mint;
            fn sub(self, o: I) -> Mint {
                let mut x = self.0 - o.to_i64();
                if x < 0 {
                    x += modulo();
                }
                Mint(x)
            }
        }

        /// ```
        /// use contest::math::Mint;
        /// Mint::set_mod(5);
        /// let mut a = Mint(2);
        /// a -= Mint(4);
        /// assert_eq!(3, a.0);
        /// ```
        impl<I: ToI64> SubAssign<I> for Mint {
            fn sub_assign(&mut self, o: I) {
                let mut x = self.0 - o.to_i64();
                if x < modulo() {
                    x += modulo();
                }
                self.0 = x;
            }
        }

        /// ```
        /// use contest::math::Mint;
        /// Mint::set_mod(5);
        /// assert_eq!(1, (Mint(2) * Mint(3)).0);
        /// ```
        impl<I: ToI64> Mul<I> for Mint {
            type Output = Mint;
            fn mul(self, o: I) -> Mint {
                let x = (self.0 * o.to_i64()) % modulo();
                Mint(x)
            }
        }

        /// ```
        /// use contest::math::Mint;
        /// Mint::set_mod(5);
        /// let mut a = Mint(2);
        /// a *= Mint(4);
        /// assert_eq!(3, a.0);
        /// ```
        impl<I: ToI64> MulAssign<I> for Mint {
            fn mul_assign(&mut self, o: I) {
                let x = (self.0 * o.to_i64()) % modulo();
                self.0 = x;
            }
        }

        /// ```
        /// use contest::math::Mint;
        /// Mint::set_mod(5);
        /// assert_eq!(4, (Mint(2) / Mint(3)).0);
        /// ```
        impl<I: ToI64> Div<I> for Mint {
            type Output = Mint;
            fn div(self, o: I) -> Mint {
                let x = self.0 * inv(o.to_i64(), modulo()) % modulo();
                Mint(x)
            }
        }

        /// ```
        /// use contest::math::Mint;
        /// Mint::set_mod(5);
        /// let mut a = Mint(2);
        /// a /= Mint(4);
        /// assert_eq!(3, a.0);
        /// ```
        impl<I: ToI64> DivAssign<I> for Mint {
            fn div_assign(&mut self, o: I) {
                let x = self.0 * inv(o.to_i64(), modulo()) % modulo();
                self.0 = x;
            }
        }

        impl Mint {
            pub fn inv(self) -> Mint {
                Mint(self::inv(self.0, modulo()))
            }
        }

        pub trait ToI64 {
            fn to_i64(self) -> i64;
        }
        impl ToI64 for i32 {
            #[inline]
            fn to_i64(self) -> i64 {
                self as i64
            }
        }
        impl ToI64 for i64 {
            #[inline]
            fn to_i64(self) -> i64 {
                self
            }
        }
        impl ToI64 for Mint {
            #[inline]
            fn to_i64(self) -> i64 {
                self.0
            }
        }

        /// ```
        /// use contest::math;
        /// assert_eq!(3, math::inv(2,5));
        /// assert_eq!(1, math::inv(1,2));
        /// assert_eq!(1, math::inv(3,2));
        /// ```
        pub fn inv(value: i64, modulo_prime: i64) -> i64 {
            return pow_mod(value, modulo_prime - 2, modulo_prime);
        }

        /// ```
        /// use contest::math;
        /// assert_eq!(8, math::pow_mod(2,3,10));
        /// assert_eq!(1, math::pow_mod(3,4,10));
        /// assert_eq!(1, math::pow_mod(0,0,3));
        /// assert_eq!(0, math::pow_mod(0,0,1));
        /// ```
        pub fn pow_mod(value: i64, exponent: i64, modulo: i64) -> i64 {
            if exponent < 0 {
                panic!("Exponent should >= 0.");
            }
            if modulo == 1 {
                return 0;
            }
            let modulo = modulo;
            let mut value = value;
            if value >= modulo {
                value %= modulo;
            }
            if value < 0 {
                value = value % modulo + value;
            }
            let mut res = 1;
            let mut exponent = exponent;
            while exponent > 0 {
                if (exponent & 1) == 1 {
                    res = res * value % modulo;
                }
                value = value * value % modulo;
                exponent >>= 1;
            }
            res
        }
    }
