const MOD: i64 = 1_000_003;
fn main() {
    let mut sc = Scanner::new(std::io::stdin());
    let Q = sc.next::<i32>();

    let mut fact = v![0i64; MOD];
    for i in 0..MOD {
        fact[i] = if i == 0 { 1 } else { fact[i - 1] * i % MOD }
    }

    for _ in 0..Q {
        let x = sc.next::<i64>();
        let d = sc.next::<i64>();
        let n = sc.next::<i64>();

        if d == 0 {
            let res = math::pow_mod(x, n, MOD);
            println!("{}", res);
        } else {
            let a = x * math::inv(d, MOD) % MOD;
            if a + n - 1 >= MOD {
                println!("0");
                continue;
            }
            let mut res = math::pow_mod(d, n, MOD) * fact[a + n - 1] % MOD;
            if a > 0 {
                res = res * math::inv(fact[a - 1], MOD) % MOD;
            }
            println!("{}", res);
        }
    }
}

