fn run() {
    let q = read!(usize);
    let M = 1_000_003;

    let mut fact = Vec::new();
    fact.push(Mint103::from(1));
    for i in 1..M + 10 {
        let next = fact[i - 1] * i;
        fact.push(next);
    }

    for _ in 0..q {
        let (a1, d, n) = read!(usize, usize, usize);
        let start = Mint103::from(a1) / d;
        let start = start.val as usize;
        let end = start + n - 1;
        if end >= M || start == 0 {
            println!("0");
            continue;
        }
        if d != 0 {
            let ans = powm(Mint103::from(d), n as u64) * fact[end]
                / (if start == 0 {
                    1.into()
                } else {
                    fact[start - 1]
                });
            println!("{}", ans);
        } else {
            let ans = powm(Mint103::from(a1), n as u64);
            println!("{}", ans);
        }
    }
}

