fn run() {
    input! {
        q: usize,
        p: [(u32, u32, u32); q],
    }
    use modint::*;
    let mut fact = std::vec::Vec::with_capacity(MOD as usize);
    let mut ifact = std::vec::Vec::with_capacity(MOD as usize);
    fact.push(ModInt(1));
    ifact.push(ModInt(1));
    for i in 1..(MOD as usize) {
        let v = ModInt(i as u32) * fact[i - 1];
        fact.push(v);
        ifact.push(ModInt(1));
    }
    ifact[(MOD - 1) as usize] = ModInt(MOD - 1);
    for i in (0..((MOD - 1) as usize)).rev() {
        let v = ModInt((i + 1) as u32) * ifact[i + 1];
        ifact[i] = v;
    }
    let mut ans = String::new();
    for (x, d, n) in p {
        if d == 0 {
            ans.push_str(&ModInt(x).pow(n).to_string());
            ans.push('\n');
            continue;
        }
        let y = ModInt(d).pow(MOD - 2) * ModInt(x);
        if 0 < y.0 &&   y.0 + n - 1 < MOD {
            let v = fact[(y.0 + n - 1) as usize] * ifact[(y.0 - 1) as usize] * ModInt(d).pow(n);
            ans.push_str(&v.to_string());
            ans.push('\n');
        } else {
            ans.push_str("0\n");
        }
    }
    print!("{}", ans);
}

fn main() {
    run();
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

