    for i in 1..m {
        stair[i] = stair[i - 1] * i % m;
    }
    let stair_i: Vec<usize> = stair.iter().map(|x| inv_m(*x, m)).collect();
    for (x, d, n) in v {
        if d == 0 {
            println!("{}", pow_m(x, n, m));
            return;
        }
        let k = x * inv_m(d, m) % m;
        if k == 0 || k + n - 1 >= m {
            println!("0");
        } else {
            println!("{}", stair[k + n - 1] * stair_i[k - 1] % m * pow_m(d, n, m) % m);
        }
    }
}

fn pow_m(n: usize, mut p: usize, d: usize) -> usize {
    let mut r = n;
    let mut ret = 1;
    while p > 0 {
        if p % 2 == 0 {
            r = r * r % d;
            p /= 2;
        } else {
            ret = ret * r % d;
            p -= 1;
        }
    }
    ret
}

fn inv_m(n: usize, d: usize) -> usize {
    pow_m(n, d - 2, d)
}

