fn expmod(x: u64, e: u64, m: u64) -> u64 {
    let mut x = x;
    let mut e = e;

    if e == 0 {
        1
    } else if e % 2 == 0 {
        let y = (x * x) % m;
        expmod(y, e/2, m)
    } else {
        let y = (x * x) % m;
        x * expmod(y, e/2, m) % m
    }
}


fn product(x: u64, d: u64, n: u64, m: u64, exponent_to_value: &Vec<u64>, value_to_exponent: &Vec<u64>) -> u64 {
    let e = (0..n).fold(0, |a, i| {
        let y = (x + i * d) % m;
        a + value_to_exponent[y as usize]
    });
    let e = e % (m - 1);
    exponent_to_value[e as usize]
}


fn main() {
    // input! {
