    let mut exponent_to_value: Vec<u64> = Vec::with_capacity(M as usize);
    let mut value_to_exponent: Vec<u64> = vec![0; M as usize];

    for e in 0..M {
        let x = expmod(base, e, M);
        exponent_to_value.push(x);
        value_to_exponent[x as usize] = e;
    }

    // Check that the base is a primitive root.
    assert!(value_to_exponent[2..].iter().all(|x| *x != 0));

    // let y = product(7, 2, 4, M, &exponent_to_value, &value_to_exponent);
