const MOD: u64 = 1_000_003;

fn pow(x: u64, n: u64) -> u64 {
    if n == 0 { 1 } else {
        let sub = pow(x, n/2);
        if n % 2 == 0 {
            sub * sub % MOD
        } else {
            (x * sub) % MOD * sub % MOD
        }
    }
}

fn inv(x: u64) -> u64 {
    pow(x, MOD - 2)
}

