fn solve(x: usize, d: usize, n: usize, fact: &[ModInt<usize>]) -> usize {
    if d == 0 {
        return ModInt(x).pow(n).0;
    }

    if n >= MOD {
        return 0;
    }

    let y = ModInt(x) / d;
    // y*(y+1)*...*(y+n-1)
    let mut ans = fact[y.0 + n - 1];
    if y.0 > 0 {
        ans /= fact[y.0 - 1];
    } else {
        ans = ModInt(0);
    }
    ans *= ModInt(d).pow(n);
    ans.0
}

