use algonium::math::*;
pub const MOD_103: u32 = 1_000_003;
#[derive(Debug, Copy, Clone)]
pub struct Mod103;
impl Module for Mod103 {
    fn module() -> u32 {
        MOD_103
    }
}
pub type Mint103 = Mint<Mod103>;
fn powm(x: Mint103, y: u64) -> Mint103 {
    if y == 0 {
        1.into()
    } else if y == 1 {
        x
    } else if y % 2 == 1 {
        x * powm(x, y - 1)
    } else {
        powm(x * x, y / 2)
    }
}
fn run() {
    let q = read!(usize);
    let M = 1_000_003;

    let mut fact = Vec::new();
    fact.push(Mint103::from(1));
    for i in 1..M + 10 {
        let next = fact[i - 1] * i;
        fact.push(next);
    }

    for _ in 0..q {
        let (a1, d, n) = read!(usize, usize, usize);
        if d != 0 && a1 != 0 {
            let start = Mint103::from(a1) / d;
            let start = start.val as usize;
            let end = start + n - 1;
            if end >= M || start == 0 {
                println!("0");
                continue;
            }
            let ans = powm(Mint103::from(d), n as u64) * fact[end]
                / (if start == 0 {
                    1.into()
                } else {
                    fact[start - 1]
                });
            println!("{}", ans);
        } else if a1 != 0 && d == 0 {
            let ans = powm(Mint103::from(a1), n as u64);
            println!("{}", ans);
        } else if d != 0 && a1 == 0 {
            println!("0");
        } else {
            println!("0");
        }
    }
}

//{{{ template
fn main() {
    let _ = ::std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap();
}

pub trait SetMinMax {
    fn set_min(&mut self, v: Self) -> bool;
    fn set_max(&mut self, v: Self) -> bool;
}

impl<T> SetMinMax for T
where
    T: PartialOrd,
{
    fn set_min(&mut self, v: T) -> bool {
        *self > v && {
            *self = v;
            true
        }
    }
    fn set_max(&mut self, v: T) -> bool {
        *self < v && {
            *self = v;
            true
        }
    }
}

#[derive(PartialEq, Eq, Debug, Copy, Clone, Default, Hash)]
pub struct Reverse<T>(pub T);

impl<T: PartialOrd> PartialOrd for Reverse<T> {
    #[inline]
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }

    #[inline]
    fn lt(&self, other: &Self) -> bool {
        other.0 < self.0
    }
    #[inline]
    fn le(&self, other: &Self) -> bool {
        other.0 <= self.0
    }
    #[inline]
    fn ge(&self, other: &Self) -> bool {
        other.0 >= self.0
    }
    #[inline]
    fn gt(&self, other: &Self) -> bool {
        other.0 > self.0
    }
}

impl<T: Ord> Ord for Reverse<T> {
    #[inline]
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

