const MOD: usize = 1e6 as usize + 3;

#[allow(dead_code)]
pub struct ModDivision {
    fact: Vec<usize>,
    inv: Vec<usize>,
    finv: Vec<usize>,
}
impl ModDivision {
    pub fn new(max_value: usize) -> Self {
        let mut fact = vec![0; max_value + 1];
        let mut inv = vec![0; max_value + 1];
        let mut finv = vec![0; max_value + 1];
        fact[0] = 1;
        fact[1] = 1;
        finv[0] = 1;
        finv[1] = 1;
        inv[1] = 1;
        for i in 2..max_value + 1 {
            fact[i] = fact[i - 1] * i % MOD;
            inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
            finv[i] = finv[i - 1] * inv[i] % MOD;
        }
        ModDivision {
            fact: fact,
            inv: inv,
            finv: finv,
        }
    }
    pub fn combination(&self, n: usize, k: usize) -> usize {
        assert!(n >= k);
        self.fact[n] * self.finv[n - k] % MOD * self.finv[k] % MOD
    }
}

pub fn mod_pow(b: usize, p: usize) -> usize {
    if p == 0 {
        return 1;
    }
    let mut ret = mod_pow(b * b % MOD, p / 2) % MOD;
    if p % 2 == 1 {
        ret = ret * b % MOD;
    }
    ret
}

fn main() {
    input!{
      q: usize,
      xdns: [(usize,usize,usize); q],
    }
    let div = ModDivision::new(MOD);


    for (x, d, n) in xdns {
        if d==0 {
            println!("{}", mod_pow(x, n));
            return;
        }
        if x == 0 {
            println!("{}", 0);
            continue;
        }

        let inv = mod_pow(d, MOD-2);
        let x = x * inv % MOD;
        if (x + n - 1) / MOD > (x-1) / MOD {
            println!("{}", 0);
            continue;
        }
        let ans = div.fact[x+n-1] * div.finv[x-1] % MOD * mod_pow(d, n) % MOD;
        println!("{}", ans);
    }
}

