const MOD: usize = 1_000_003;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let mut fact = vec![ModInt(1); MOD * 2 + 1];
    for i in 1..fact.len() {
        fact[i] = fact[i - 1] * i;
    }

    let q: usize = sc.read();
    for _ in 0..q {
        let x: usize = sc.read();
        let d: usize = sc.read();
        let n: usize = sc.read();
        sc.write(solve(x, d, n, &fact).to_string());
        sc.write("\n");
    }
}

fn solve(x: usize, d: usize, n: usize, fact: &[ModInt<usize>]) -> usize {
    if n >= MOD {
        return 0;
    }
    if d == 0 {
        return ModInt(x).pow(n).0;
    }

    let y = ModInt(x) / d;
    // y*(y+1)*...*(y+n-1)
    let mut ans = fact[y.0 + n - 1];
    if y.0 > 0 {
        ans /= fact[y.0 - 1];
    }
    ans *= ModInt(d).pow(n);
    ans.0
}

