const MOD: usize = 1_000_003;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let q: usize = sc.read();

    let mut fact = vec![ModInt(1); MOD];
    for i in 1..fact.len() {
        fact[i] = fact[i - 1] * i;
    }

    for _ in 0..q {
        let x: usize = sc.read();
        let d: usize = sc.read();
        let n: usize = sc.read();
        if n >= MOD || x == 0 {
            sc.write("0\n");
            continue;
        }

        let x = ModInt(x);
        if d == 0 {
            let ans = x.pow(n);
            sc.write(format!("{}\n", ans.0));
            continue;
        }

        // (x/d+n-1)!/(x/d-1)!

        let x_d = x / d;

        let up = if x_d.0 + n - 1 >= MOD {
            ModInt(0)
        } else {
            fact[x_d.0 + n - 1]
        };
        let down = fact[x_d.0 - 1];
        let ans = up / down * ModInt(d).pow(n);
        sc.write(format!("{}\n", ans.0));
    }
}

