    }

    let mut facts = vec![Mod::new(0); 1000003+1];

    facts[0] = 1.into();
    for i in 1..facts.len() {
        facts[i] = facts[i-1] * Mod::new(i as _);
    }

    for &(x, d, n) in xdn.iter() {
        if d == 0 {
            println!("{}", Mod::new(x).pow(n));
        } else {
            // x*(x+d)*(x+2d)*...
            // (x/d)*(x/d+1)..(x/d+n-1)*d^n

            let x = Mod::new(x);
            let d = Mod::new(d);
            let n = Mod::new(n);

            let xd = x / d;

            // let ans = fact(xd+n-1) / fact(xd-1) * d.pow(n.0);
            let ans = facts[(xd+n-1).0 as usize] / facts[(xd-1).0 as usize] * d.pow(n.0);

            println!("{}", ans);
        }
    }
}

