// Depends on ModInt.rs
fn fact_init(w: usize) -> (Vec<ModInt>, Vec<ModInt>) {
    let mut fac = vec![ModInt::new(1); w];
    let mut invfac = vec![0.into(); w];
    for i in 1 .. w {
        fac[i] = fac[i - 1] * i as i64;
    }
    invfac[w - 1] = fac[w - 1].inv();
    for i in (0 .. w - 1).rev() {
        invfac[i] = invfac[i + 1] * (i as i64 + 1);
    }
    (fac, invfac)
}


fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        q: usize,
        xdn: [(i64, i64, i64); q],
    }
    let (fac, _) = fact_init(2 * 1_000_010);
    let (_, invfac) = fact_init(1_000_003);
    for &(x, d, n) in &xdn {
        if d == 0 {
            puts!("{}\n", ModInt::new(x).pow(n));
            continue;
        }
        let xd = ModInt::new(x) * ModInt::new(d).inv();
        if n >= MOD || xd.x == 0 {
            puts!("0\n");
            continue;
        }
        let lo = xd.x as usize - 1;
        let hi = lo + n as usize;
        puts!("{}\n", fac[hi] * invfac[lo] * ModInt::new(d).pow(n));
    }
}

