fn main() {
    input! {
        q: usize,
        queries: [(i64, i64, i64); q]
    };

    let mut fact = vec![0; 1000010];
    fact[0] = 1;
    for i in 1..1000010 {
        fact[i] = (i as i64) * fact[i-1] % MOD;
    }
    let solve = |x: i64, d: i64, n: i64| {
        if d == 0 {
            return Combination::pow(x, n) % MOD;
        }
        let invd = Combination::inv(d);
        let from = (x * invd) % MOD;
        if from + (n - 1) >= MOD || from == 0 {
            return 0;
        }
        let to = (from + n) as usize;
        let base = fact[to-1] * Combination::inv(fact[(from-1) as usize]) % MOD;
        let dn = Combination::pow(d, n);
        base * dn % MOD
    };

    for (x, d, n) in queries {
        println!("{}", solve(x, d, n));
    }
}

