struct Combination {
    fact: Vec<i64>,
    invfact: Vec<i64>,
}

impl Combination {
    fn inv(a: i64) -> i64 {
        Combination::pow(a, MOD - 2)
    }

    fn pow(a: i64, p: i64) -> i64 {
        let mut p = p;
        let mut aa = a;
        let mut ret = 1;
        while p >= 1 {
            if p & 1 == 1 {
                ret *= aa;
                ret %= MOD;
            }
            p >>= 1;
            aa = aa * aa % MOD;
        }
        ret
    }

    fn new(upto: usize) -> Self {
        let mut fact = vec![0; upto];
        let mut invfact = vec![0; upto];

        fact[0] = 1;
        for i in 1..upto {
            fact[i] = fact[i - 1] * (i as i64) % MOD;
        }

        invfact[upto - 1] = Combination::inv(fact[upto - 1]);
        invfact[0] = 1;
        for i in (1..upto - 1).rev() {
            invfact[i] = invfact[i + 1] * ((i + 1) as i64) % MOD;
        }

        Combination {
            fact: fact,
            invfact: invfact,
        }
    }

    fn comb(&self, n: usize, r: usize) -> i64 {
        if r < 0 || r > n {
            return 0;
        }
        self.fact[n] * self.invfact[r] % MOD * self.invfact[n - r] % MOD
    }
}

const MOD: i64 = 1000003;

//===

fn main() {
    input! {
        q: usize,
        queries: [(i64, i64, i64); q]
    };

    let mut fact = vec![0; 1000010];
    fact[0] = 1;
    for i in 1..1000010 {
        fact[i] = (i as i64) * fact[i-1] % MOD;
    }
    let solve = |x: i64, d: i64, n: i64| {
        if d == 0 {
            return Combination::pow(x, n) % MOD;
        }
        let invd = Combination::inv(d);
        let from = (x * invd) % MOD;
        if from + n >= MOD || from == 0 {
            return 0;
        }
        let to = (from + n) as usize;
        let base = fact[to-1] * Combination::inv(fact[(from-1) as usize]) % MOD;
        let dn = Combination::pow(d, n);
        base * dn % MOD
    };

    for (x, d, n) in queries {
        println!("{}", solve(x, d, n));
    }
}

