    let q: usize = sc.read();

    let mut fact = vec![ModInt(1); MOD];
    let mut inv_fact = vec![ModInt(1); MOD];
    for i in 2..fact.len() {
        fact[i] = fact[i - 1] * i;
        inv_fact[i] = inv_fact[i - 1] * ModInt(i).pow(MOD - 2);
    }

    for _ in 0..q {
