fn expmod(x: u64, e: u64, m: u64) -> u64 {
    let mut x = x;
    let mut e = e;

    if e == 0 {
        1
    } else if e % 2 == 0 {
        let y = (x * x) % m;
        expmod(y, e/2, m)
    } else {
        let y = (x * x) % m;
        x * expmod(y, e/2, m) % m
    }
}


